    /// The compatibility wrapper for navigating *by tab* - the write
    /// direction LibraryTab's synchronization rule reserves exclusively
    /// for this method (every other call site still navigates by setting
    /// `view` directly, exactly as before). Sets both fields together so
    /// they can never briefly disagree; `tools_overlay` is cleared to
    /// match every other navigation call site's behaviour (see the
    /// sidebar-click handler in `update`). Called by the unified Library
    /// shell's tab_row.
    fn navigate_to_library_tab(&mut self, tab: LibraryTab) {
        self.view = main_view_for_library_tab(tab);
        self.library_tab = tab;
        self.tools_overlay = ToolsOverlay::None;
    }

    fn navigate_to_missing_catalogue_review(&mut self) {
        self.navigate_to_library_tab(LibraryTab::Archives);
        administration_pages::set_missing_review_mode(&mut self.library_filters, true);
        self.archive_context.clear_selection();
    }

    /// `ProblemsRepairTab`'s exact counterpart to `navigate_to_library_tab` -
    /// same synchronization rule, same reason for existing (called by the
    /// consolidated page's own tab row).
    fn navigate_to_problems_repair_tab(&mut self, tab: ProblemsRepairTab) {
        self.view = main_view_for_problems_repair_tab(tab);
        self.problems_repair_tab = tab;
        self.tools_overlay = ToolsOverlay::None;
    }

    /// `SourcesTab`'s exact counterpart to `navigate_to_library_tab`.
    fn navigate_to_sources_tab(&mut self, tab: SourcesTab) {
        self.view = main_view_for_sources_tab(tab);
        self.sources_tab = tab;
        self.tools_overlay = ToolsOverlay::None;
    }

    fn navigate_to_home_card(&mut self, card: home_page::HomeCard) {
        match card {
            home_page::HomeCard::RomM => {
                // The RomM provider integration is the RomM source card on
                // Sources -> Libraries. Route there so the card's
                // `romm_snapshot` readiness badge and its destination
                // describe the same subsystem. (The whole-collection Playing
                // Library planner remains reachable honestly via Library
                // Organisation -> "Build Playing Library".) Sidebar and
                // top-menu "RomM" converge on this exact call.
                self.navigate_to_sources_tab(SourcesTab::Libraries);
            }
            home_page::HomeCard::ConvertDiscs => {
                // First-class Disc Conversion destination. The dispatch
                // branch lazily creates `optical_conversion_page`, so no
                // pre-seeding is needed; done here too so the state exists
                // the instant the card is clicked.
                self.navigate_to_main_view(MainView::DiscConversion);
                self.optical_conversion_page.get_or_insert_with(
                    optical_conversion_page::OpticalConversionPageState::default,
                );
            }
            home_page::HomeCard::DuplicateReview => {
                // First-class Duplicate Finder destination - renders
                // standalone, without Repair Review / Repair History.
                self.navigate_to_main_view(MainView::ExactDuplicateReview);
            }
            _ => self.navigate_to_main_view(main_view_for_home_card(card)),
        }
    }

    /// The one sanctioned way to change `self.view` in response to a user
    /// action (a sidebar click, a Home card, a menu item) - shared so
    /// every navigation source applies the same special cases
    /// (`CheatsMods` clears any open tools overlay; `Library` restores
    /// whichever tab was last selected rather than resetting to Archives)
    /// instead of each call site re-deriving them, and so the *last*
    /// navigation call in a frame always wins over anything set earlier
    /// that frame.
    fn navigate_to_main_view(&mut self, target: MainView) {
        if target == MainView::CheatsMods {
            self.view = MainView::CheatsMods;
            self.tools_overlay = ToolsOverlay::None;
        } else if target == MainView::Library {
            self.navigate_to_library_tab(self.library_tab);
        } else if target == MainView::Problems {
            // Restores whichever "Problems & Repair" tab was last selected,
            // exactly like `Library` above - clicking the one sidebar entry
            // a second time should not reset Diagnostics/Repair progress
            // back to Overview.
            self.navigate_to_problems_repair_tab(self.problems_repair_tab);
        } else if target == MainView::Sources {
            // Restores whichever Sources tab was last selected, exactly
            // like `Library`/`Problems` above.
            self.navigate_to_sources_tab(self.sources_tab);
        } else {
            self.view = target;
            self.tools_overlay = ToolsOverlay::None;
        }
    }

    /// Gamer View's gear menu has no sidebar behind it, so "Advanced View"
    /// is the only realistic path a genuine first-run user has to reach
    /// the task list. It must always land on Home, never on whatever
    /// `self.view` happened to hold from an earlier Advanced View visit.
    ///
    /// Deliberately does not persist `ui_mode` itself - the caller does
    /// that (see the gear menu's "Advanced View" handler) - so this method
    /// stays a pure state transition, callable from a test without writing
    /// to the real per-user GUI-mode file.
    fn switch_to_advanced_view_at_home(&mut self) {
        self.ui_mode = GuiMode::AdvancedView;
        self.view = MainView::Home;
        self.tools_overlay = ToolsOverlay::None;
    }

    /// LibraryTab's synchronization rule, applied once. Called at the top
    /// of every frame in `update`, before anything else runs - see
    /// LibraryTab's doc comment for the rule itself. Broken out as its own
    /// method (rather than inlined in `update`) purely so it can be
    /// exercised directly by tests without going through a full
    /// `eframe::App::update` call, which nothing else in this codebase
    /// does either.
    fn reconcile_library_tab(&mut self) {
        if let Some(tab) = library_tab_for_main_view(self.view) {
            self.library_tab = tab;
        }
    }

    /// `ProblemsRepairTab`'s exact counterpart to `reconcile_library_tab`,
    /// called alongside it every frame.
    fn reconcile_problems_repair_tab(&mut self) {
        if let Some(tab) = problems_repair_tab_for_main_view(self.view) {
            self.problems_repair_tab = tab;
        }
    }

    /// `SourcesTab`'s exact counterpart to `reconcile_library_tab`, called
    /// alongside it every frame.
    fn reconcile_sources_tab(&mut self) {
        if let Some(tab) = sources_tab_for_main_view(self.view) {
            self.sources_tab = tab;
        }
    }

    fn refresh(&mut self, context: &egui::Context) {
        self.refresh_generation = self.refresh_generation.next();
        let generation = self.refresh_generation;
        self.history.record(HistoryEntry::new(
            ActivityAction::Refresh,
            None,
            ActivityOutcome::Started,
            "Refreshing archive snapshot.",
        ));
        let previous = match std::mem::replace(
            &mut self.state,
            LoadState::Error("refresh starting".to_string()),
        ) {
            LoadState::Ready(data) => Some(data),
            LoadState::Loading { previous, .. } => previous,
            LoadState::Error(_) => None,
        };
        self.refresh_diagnostics(context);
        self.state = start_load(context.clone(), generation, previous);
    }
    fn start_archive_inspection(&mut self, context: egui::Context, archive_path: PathBuf) {
        self.archive_inspector_generation = self.archive_inspector_generation.next();
        let generation = self.archive_inspector_generation;
        let (sender, receiver) = mpsc::channel();
        let job_path = archive_path.clone();
        thread::spawn(move || {
            let result = inspect_archive(&job_path).map_err(|error| error.to_string());
            let _ = sender.send((generation, result));
            context.request_repaint();
        });
        self.archive_inspector = Some(ArchiveInspectorState::loading(
            archive_path,
            generation,
            receiver,
        ));
        self.tools_overlay = ToolsOverlay::ArchiveInspector;
    }

    /// Mirrors `poll_load`'s exact shape: read the receiver (immutable
    /// borrow) into an owned `result` first, then apply it as a separate
    /// step, so the borrow checker never sees a conflict between reading
    /// `self.archive_inspector` and later writing to it.
    fn poll_archive_inspection(&mut self) {
        let result = match self
            .archive_inspector
            .as_ref()
            .map(|inspector| &inspector.status)
        {
            Some(ArchiveInspectorStatus::Loading {
                generation,
                receiver,
            }) => match receiver.try_recv() {
                Ok(message) => Some(message),
                Err(TryRecvError::Empty) => None,
                Err(TryRecvError::Disconnected) => Some((
                    *generation,
                    Err("The inspection worker stopped unexpectedly.".to_string()),
                )),
            },
            Some(ArchiveInspectorStatus::Ready(_) | ArchiveInspectorStatus::Error(_)) | None => {
                None
            }
        };

        let Some((generation, result)) = result else {
            return;
        };
        if generation != self.archive_inspector_generation {
            return;
        }
        if let Some(inspector) = self.archive_inspector.as_mut() {
            inspector.status = match result {
                Ok(report) => ArchiveInspectorStatus::Ready(report),
                Err(message) => ArchiveInspectorStatus::Error(message),
            };
        }
    }

    fn poll_load(&mut self, _context: &egui::Context) {
        let result = match &self.state {
            LoadState::Loading {
                generation,
                receiver,
                ..
            } => match receiver.try_recv() {
                Ok(message) => Some(message),
                Err(TryRecvError::Empty) => None,
                Err(TryRecvError::Disconnected) => Some((
                    *generation,
                    Err("background data loader stopped unexpectedly".to_string()),
                )),
            },
            LoadState::Ready(_) | LoadState::Error(_) => None,
        };

        if let Some((generation, result)) = result {
            if generation != self.refresh_generation {
                return;
            }
            let (state_generation, previous) = match std::mem::replace(
                &mut self.state,
                LoadState::Error("load result pending".to_string()),
            ) {
                LoadState::Loading {
                    generation,
                    previous,
                    ..
                } => (Some(generation), previous),
                LoadState::Ready(_) | LoadState::Error(_) => (None, None),
            };
            if state_generation != Some(generation) {
                return;
            }
            self.state = match result {
                Ok(data) => {
                    let merged = build_display_rows(
                        &data.records,
                        &data.rows,
                        self.database_state.snapshot(),
                    );
                    self.filtered_rows = matching_row_indices(&merged, &self.filter);
                    self.prune_selection(&merged);
                    self.history.record(HistoryEntry::new(
                        ActivityAction::Refresh,
                        None,
                        ActivityOutcome::Completed,
                        "Archive snapshot refreshed.",
                    ));
                    self.refresh_error = None;
                    self.snapshot_stale = false;
                    self.snapshot_generation = Some(generation);
                    LoadState::Ready(Box::new(data))
                }
                Err(error) => {
                    self.history.record(HistoryEntry::new(
                        ActivityAction::Refresh,
                        None,
                        ActivityOutcome::Failed,
                        error.clone(),
                    ));
                    self.refresh_error = Some(error.clone());
                    self.snapshot_stale = previous.is_some();
                    self.tools_overlay = ToolsOverlay::Diagnostics;
                    previous.map_or_else(|| LoadState::Error(error), LoadState::Ready)
                }
            };
        }
    }

    /// Starts a background database load. `run_scan_first =
    /// true` is "Scan library" (runs `scan_and_persist` before reloading);
    /// `false` is "Refresh database status" / "Retry database load" (a
    /// read-only reload). Never blocks the UI thread - mirrors
    /// `refresh`/`start_load` exactly.
    fn start_database_action(&mut self, context: egui::Context, run_scan_first: bool) {
        if self.missing_removal.is_some() || self.database_state.is_loading() {
            return;
        }
        self.database_generation = self.database_generation.next();
        let generation = self.database_generation;
        let previous = match std::mem::replace(
            &mut self.database_state,
            DatabaseState::Error {
                message: "database action starting".to_string(),
                previous: None,
            },
        ) {
            DatabaseState::Ready { snapshot, .. } => Some(snapshot),
            DatabaseState::Outdated { previous, .. } | DatabaseState::Error { previous, .. } => {
                previous
            }
            DatabaseState::Loading { .. } => unreachable!("loading state was rejected above"),
            DatabaseState::NotCreated { .. } => None,
        };
        if run_scan_first {
            self.history.record(HistoryEntry::new(
                ActivityAction::LibraryDatabase,
                None,
                ActivityOutcome::Started,
                "Scanning configured source folders into the library database.",
            ));
        }
        self.database_state = start_database_load(context, generation, previous, run_scan_first);
    }

    fn poll_database_load(&mut self, _context: &egui::Context) {
        let message = match &self.database_state {
            DatabaseState::Loading {
                generation,
                receiver,
                ..
            } => match receiver.try_recv() {
                Ok(message) => Some(message),
                Err(TryRecvError::Empty) => None,
                Err(TryRecvError::Disconnected) => Some((
                    *generation,
                    Err(DatabaseLoadError::Failed {
                        message: "background database loader stopped unexpectedly".to_string(),
                    }),
                )),
            },
            DatabaseState::NotCreated { .. }
            | DatabaseState::Ready { .. }
            | DatabaseState::Outdated { .. }
            | DatabaseState::Error { .. } => None,
        };

        let Some((generation, result)) = message else {
            return;
        };
        // Two independent staleness checks, mirroring poll_load exactly:
        // (1) is this even the current database generation, and (2) does
        // the state we are about to replace still agree it is Loading at
        // that same generation (it could have been replaced by a newer
        // start_database_action call between the channel send and this
        // poll). Either mismatch means this message is from a previous
        // generation and must be ignored, never merged into current state.
        if generation != self.database_generation {
            return;
        }
        let (previous, worker) = match std::mem::replace(
            &mut self.database_state,
            DatabaseState::Error {
                message: "database load result pending".to_string(),
                previous: None,
            },
        ) {
            DatabaseState::Loading {
                generation: state_generation,
                previous,
                worker,
                ..
            } if state_generation == generation => (previous, worker),
            other => {
                self.database_state = other;
                return;
            }
        };
        if let Some(worker) = worker {
            let _ = worker.join();
        }

        // Consumed unconditionally, whatever `result` turns out to be below:
        // a pending Sources-page scan summary is only ever valid for the
        // very next reload completion, never a later one (requirement:
        // never invent a state transition - if this reload doesn't land in
        // `Ready`, there is no `last_scan_summary` to attach it to, so it
        // is simply dropped rather than held over).
        let pending_source_scan_summary = self.pending_source_scan_summary.take();
        self.database_state = match result {
            Ok(DatabaseOutcome::Loaded(snapshot)) => DatabaseState::Ready {
                snapshot: Box::new(snapshot),
                last_scan_summary: pending_source_scan_summary,
            },
            Ok(DatabaseOutcome::Scanned {
                snapshot,
                scan_summary,
                upgrade,
            }) => {
                let activity = match &upgrade {
                    Some(report) => format_database_upgrade_success(report, &scan_summary),
                    None => format_scan_activity(&scan_summary),
                };
                self.history.record(HistoryEntry::new(
                    ActivityAction::LibraryDatabase,
                    None,
                    ActivityOutcome::Completed,
                    activity.clone(),
                ));
                if upgrade.is_some() {
                    self.feedback = Some(ActionFeedback {
                        succeeded: true,
                        message: activity,
                        cleanup: None,
                        warning: None,
                        more_information: None,
                    });
                }
                DatabaseState::Ready {
                    snapshot: Box::new(snapshot),
                    last_scan_summary: Some(scan_summary),
                }
            }
            Err(DatabaseLoadError::NotCreated { database_path }) => {
                DatabaseState::NotCreated { database_path }
            }
            Err(DatabaseLoadError::Outdated { health }) => {
                DatabaseState::Outdated { health, previous }
            }
            Err(DatabaseLoadError::Failed { message }) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::LibraryDatabase,
                    None,
                    ActivityOutcome::Failed,
                    message.clone(),
                ));
                DatabaseState::Error { message, previous }
            }
        };

        let duplicate_report = self
            .database_state
            .snapshot()
            .map(|snapshot| snapshot.duplicate_report.clone());
        prune_duplicate_review_selection(
            &mut self.selected_duplicate_group,
            &mut self.selected_duplicate_archive,
            duplicate_report.as_ref(),
        );

        // The merged row set may have just changed (a cache reload/scan
        // just settled) - recompute the cached filtered-index list against
        // it now rather than leaving it stale until the next live refresh
        // or filter-text edit. Only meaningful once a live snapshot
        // exists; the cache-only preview shown before that filters itself
        // fresh each frame instead (see `show_loaded_data`'s Loading
        // branch).
        if let LoadState::Ready(data) = &self.state {
            let merged =
                build_display_rows(&data.records, &data.rows, self.database_state.snapshot());
            self.filtered_rows = matching_row_indices(&merged, &self.filter);
            self.prune_selection(&merged);
        }
    }

    /// Removes any exact-identity entry from `selected_archives` - and
    /// clears `selected_archive` if it was the one that vanished - that
    /// no longer names any row in `merged_rows`, the just-recomputed
    /// live+cache catalogue (requirement 7: "remove selections that no
    /// longer exist in the loaded catalogue"). Called from both
    /// `poll_load` and `poll_database_load`, right where each already
    /// recomputes `filtered_rows` against the same merged list, so
    /// selection state is never one step behind what is actually on
    /// screen. Compares exact `PathBuf` identity only, never a lossy
    /// display string, and never touches row indices - there are none to
    /// go stale here in the first place.
    fn prune_selection(&mut self, merged_rows: &[ArchiveRow]) {
        self.archive_context.prune(merged_rows);
    }

    fn refresh_diagnostics(&mut self, context: &egui::Context) {
        self.diagnostics_refresh_generation = self.diagnostics_refresh_generation.next();
        self.history.record(HistoryEntry::new(
            ActivityAction::Diagnostics,
            None,
            ActivityOutcome::Started,
            "Refreshing setup diagnostics.",
        ));
        self.diagnostics = start_diagnostics(context.clone(), self.refresh_generation);
    }

    /// The Health Dashboard's report, rebuilt only when the underlying
    /// live snapshot, database snapshot, diagnostics refresh, or recovery
    /// offers have actually changed since the last call - see
    /// `HealthReportCacheKey`'s doc comment for why pointer identity
    /// rather than a raw generation comparison. Never called unless the
    /// dashboard is actually open (see its one call site), so this adds
    /// no cost to the ordinary library view.
    fn cached_health_issues(&mut self) -> &[HealthIssue] {
        let key = HealthReportCacheKey {
            live_data_ptr: match &self.state {
                LoadState::Ready(data) => Some(std::ptr::from_ref(data.as_ref()) as usize),
                LoadState::Loading { .. } | LoadState::Error(_) => None,
            },
            database_snapshot_ptr: self
                .database_state
                .snapshot()
                .map(|snapshot| std::ptr::from_ref(snapshot) as usize),
            diagnostics_generation: self.diagnostics_refresh_generation,
        };

        let cache_is_fresh = self.health_report_cache.as_ref().is_some_and(|cache| {
            cache.key == key
                && cache.lazy_unmount_offers == self.lazy_unmount_offers
                && cache.remount_offers == self.remount_offers
        });

        if !cache_is_fresh {
            let live_records = match &self.state {
                LoadState::Ready(data) => Some(&data.records),
                LoadState::Loading { .. } | LoadState::Error(_) => None,
            };
            let issues = match (live_records, self.database_state.snapshot()) {
                (Some(records), Some(snapshot)) => build_health_issues(
                    records,
                    snapshot,
                    &self.lazy_unmount_offers,
                    &self.remount_offers,
                ),
                _ => Vec::new(),
            };
            self.health_report_cache = Some(HealthReportCache {
                key,
                lazy_unmount_offers: self.lazy_unmount_offers.clone(),
                remount_offers: self.remount_offers.clone(),
                issues,
            });
        }

        &self.health_report_cache.as_ref().unwrap().issues
    }

    fn poll_diagnostics(&mut self) {
        enum PollResult {
            Completed(DiagnosticsMessage),
            Disconnected(RefreshGeneration),
        }

        let result = match &self.diagnostics {
            DiagnosticsState::Loading {
                generation,
                receiver,
            } => match receiver.try_recv() {
                Ok(message) => Some(PollResult::Completed(message)),
                Err(TryRecvError::Empty) => None,
                Err(TryRecvError::Disconnected) => Some(PollResult::Disconnected(*generation)),
            },
            DiagnosticsState::Ready { .. } | DiagnosticsState::Error { .. } => None,
        };
        match result {
            Some(PollResult::Completed((generation, report)))
                if generation == self.refresh_generation =>
            {
                self.history.record(HistoryEntry::new(
                    ActivityAction::Diagnostics,
                    None,
                    ActivityOutcome::Completed,
                    if report.ready_for_actions {
                        "Diagnostics completed: EmuWiz is ready."
                    } else {
                        "Diagnostics completed: setup needs attention."
                    },
                ));
                if !report.config_missing && report.config_path_error.is_none() {
                    self.config_previously_confirmed = true;
                }
                self.diagnostics = DiagnosticsState::Ready { generation, report };
            }
            Some(PollResult::Disconnected(generation)) if generation == self.refresh_generation => {
                let message = "The diagnostics worker stopped unexpectedly. Run diagnostics again."
                    .to_string();
                self.history.record(HistoryEntry::new(
                    ActivityAction::Diagnostics,
                    None,
                    ActivityOutcome::Failed,
                    message.clone(),
                ));
                self.diagnostics = DiagnosticsState::Error {
                    generation,
                    message,
                };
                self.tools_overlay = ToolsOverlay::Diagnostics;
            }
            Some(PollResult::Completed(_)) | Some(PollResult::Disconnected(_)) | None => {}
        }
    }

    fn start_setup_action(&mut self, context: egui::Context, action: SetupAction) {
        if self.is_busy() {
            return;
        }
        let (sender, receiver) = mpsc::channel();
        self.history.record(HistoryEntry::new(
            ActivityAction::Setup,
            None,
            ActivityOutcome::Started,
            match action {
                SetupAction::CreateStarterConfig => "Creating starter config.",
                SetupAction::CreateMountRoot => "Creating configured mount root.",
                SetupAction::OpenConfigFolder => "Opening config folder.",
            },
        ));
        self.setup_action = Some(RunningSetupAction { action, receiver });
        thread::spawn(move || {
            let result = match action {
                SetupAction::CreateStarterConfig => create_starter_config_default()
                    .map(|path| format!("Created starter config at {}.", path.display())),
                SetupAction::CreateMountRoot => create_configured_mount_root_default()
                    .map(|path| format!("Created mount root at {}.", path.display())),
                SetupAction::OpenConfigFolder => open_default_config_folder(),
            }
            .map_err(|error| error.to_string());
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    // --- Doctor Stage 1A ------------------------------------------------

    /// Starts a read-only Doctor scan.
    ///
    /// Deliberately **not** `self.refresh(context)`: this never reloads the
    /// application, never rescans the library, never creates the mount root,
    /// and never touches the database. The path-based inputs are gathered on
    /// a worker thread; the preloaded, session-owned inputs are borrowed
    /// when the result arrives.
    ///
    /// Cancellation follows the existing generation pattern: a superseded
    /// run's result is discarded on arrival, and the previous result stays
    /// visible until a newer one completes.
    fn start_doctor_scan(&mut self, context: egui::Context) {
        let generation = self.doctor_scan_generation.next();
        self.doctor_scan_generation = generation;
        let (sender, receiver) = mpsc::channel();
        thread::spawn(move || {
            let _ = sender.send((generation, gather_doctor_inputs()));
            context.request_repaint();
        });
        let previous = match std::mem::replace(&mut self.doctor_scan, DoctorScanState::NotRun) {
            DoctorScanState::Ready(outcome) => Some(outcome),
            DoctorScanState::Running { previous, .. } => previous,
            DoctorScanState::NotRun => None,
        };
        self.doctor_scan = DoctorScanState::Running {
            generation,
            receiver,
            previous,
        };
    }

    /// Completes a Doctor scan once its worker delivers the gathered inputs.
    ///
    /// The pure runner itself is executed here, on the main thread, because
    /// it does no I/O and needs to borrow the session-owned inputs
    /// (`LoadedData::doctor`, the cached live health issues, and any already
    /// discovered RetroArch environment). None of those is re-collected: if
    /// a subsystem has not been loaded in this session it is reported as not
    /// checked, never as a pass.
    fn poll_doctor_scan(&mut self) {
        let received = match &self.doctor_scan {
            DoctorScanState::Running {
                generation,
                receiver,
                ..
            } => match receiver.try_recv() {
                Ok((received_generation, gathered)) => {
                    Some((received_generation == *generation, gathered))
                }
                Err(mpsc::TryRecvError::Empty) => None,
                Err(mpsc::TryRecvError::Disconnected) => {
                    // The worker vanished. Report it once, against the
                    // first subsystem, rather than as four identical copies.
                    Some((
                        true,
                        DoctorGathered {
                            mount_root_safety: Gathered::Failed(
                                "the Doctor worker stopped unexpectedly".to_string(),
                            ),
                            database: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                            source_health: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                            transactions: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                            stale_mount_directories: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                            index_freshness: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                            storage: Gathered::NotLoaded("not gathered: the Doctor worker stopped"),
                            emulator_profiles: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                            linux_emulator_installations: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                            arcade_dat_version: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                            xemu_readiness: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                            xenia_readiness: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                            ppsspp_readiness: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                            rpcs3_readiness: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                            managed_entries: Gathered::NotLoaded(
                                "not gathered: the Doctor worker stopped",
                            ),
                        },
                    ))
                }
            },
            DoctorScanState::NotRun | DoctorScanState::Ready(_) => None,
        };
        let Some((is_current, gathered)) = received else {
            return;
        };
        if !is_current {
            // A newer run superseded this one; discard it and keep waiting.
            return;
        }

        // `cached_health_issues` needs `&mut self`; copying the small,
        // already-built vector out ends that borrow before the immutable
        // borrows below - the same pattern the Health tab already uses.
        let health_issues = self.cached_health_issues().to_vec();
        let doctor_report = match &self.state {
            LoadState::Ready(data) => Gathered::Ready(&data.doctor),
            LoadState::Loading { .. } | LoadState::Error(_) => Gathered::NotLoaded(
                "The library has not finished loading, so the archive-scan and mount-status checks were not available.",
            ),
        };
        let retroarch = match &self.retroarch_profiles {
            RetroArchProfilesState::Ready(discovery) => Gathered::Ready(&discovery.environment),
            RetroArchProfilesState::Error(message) => Gathered::Failed(message.clone()),
            RetroArchProfilesState::NotScanned | RetroArchProfilesState::Scanning { .. } => {
                Gathered::NotLoaded(
                    "RetroArch profiles have not been discovered in this session. Doctor never starts that scan itself; use Settings to rescan.",
                )
            }
        };

        // The already-computed setup diagnostics, never recomputed here:
        // recomputing would run the mount-root write probe.
        let setup = match &self.diagnostics {
            DiagnosticsState::Ready { report, .. } => Gathered::Ready(report),
            DiagnosticsState::Error { message, .. } => Gathered::Failed(message.clone()),
            DiagnosticsState::Loading { .. } => Gathered::NotLoaded(
                "Configuration diagnostics are still loading. Doctor reuses them rather than re-running them, because that check writes a temporary file to test the mount root.",
            ),
        };
        let inputs = DoctorScanInputs {
            doctor_report,
            setup,
            health_issues: Gathered::Ready(health_issues.as_slice()),
            source_health: borrowed(&gathered.source_health, |value| value.as_slice()),
            database: borrowed(&gathered.database, |value| value),
            mount_root_safety: borrowed(&gathered.mount_root_safety, |value| value),
            retroarch,
            transactions: borrowed(&gathered.transactions, |value| value),
            stale_mount_directories: borrowed(&gathered.stale_mount_directories, |value| {
                value.as_slice()
            }),
            index_freshness: match &gathered.index_freshness {
                Gathered::Ready((freshness, path)) => Gathered::Ready((freshness, path.as_path())),
                Gathered::Failed(reason) => Gathered::Failed(reason.clone()),
                Gathered::NotLoaded(reason) => Gathered::NotLoaded(reason),
            },
            storage: borrowed(&gathered.storage, |value| value),
            emulator_profiles: borrowed(&gathered.emulator_profiles, |value| value),
            linux_emulator_installations: borrowed(
                &gathered.linux_emulator_installations,
                |value| value.as_slice(),
            ),
            arcade_dat_version: borrowed(&gathered.arcade_dat_version, |value| value.as_slice()),
            xemu_readiness: borrowed(&gathered.xemu_readiness, |value| value.as_slice()),
            xenia_readiness: borrowed(&gathered.xenia_readiness, |value| value.as_slice()),
            ppsspp_readiness: borrowed(&gathered.ppsspp_readiness, |value| value.as_slice()),
            rpcs3_readiness: borrowed(&gathered.rpcs3_readiness, |value| value.as_slice()),
            managed_entries: borrowed(&gathered.managed_entries, |value| value),
            // The verified-identity fact cache is not gathered by the GUI
            // Doctor worker yet; a later typed consumer will supply it.
            verified_identity: Gathered::NotLoaded(
                "not gathered: the GUI Doctor worker does not load the identity cache yet",
            ),
            free_space_policy: FreeSpacePolicy::default(),
        };
        let scan = run_doctor_scan(&inputs);
        let finished_at_unix_seconds = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs() as i64)
            .unwrap_or(0);
        // Keep the selected finding only if it still exists.
        if let Some(selected) = &self.doctor_selected_finding
            && scan
                .finding(doctor_page::doctor_finding_key_id(selected))
                .is_none()
        {
            self.doctor_selected_finding = None;
        }
        self.doctor_scan = DoctorScanState::Ready(Box::new(DoctorScanOutcome {
            scan,
            finished_at_unix_seconds,
        }));
    }

    /// Emulator Adapter Batch B: starts the one real, background RPCS3
    /// environment check. Explicit only (a button press); never called
    /// automatically. `verified_title_id` must already be authoritative -
    /// this method never derives one; see `rpcs3_page`'s own module doc.
    fn start_rpcs3_status_load(
        &mut self,
        context: egui::Context,
        verified_title_id: Option<String>,
    ) {
        self.rpcs3_status_generation += 1;
        let generation = self.rpcs3_status_generation;
        let (sender, receiver) = mpsc::channel();
        self.rpcs3_status = rpcs3_page::Rpcs3State::Loading {
            generation,
            receiver,
        };
        thread::spawn(move || {
            let outcome = rpcs3_page::gather_rpcs3_status(verified_title_id);
            let _ = sender.send((generation, outcome));
            context.request_repaint();
        });
    }

    /// Emulator Adapter Batch B: applies the pure
    /// [`rpcs3_page::Rpcs3Action`] the panel returned this frame - the
    /// only thing it can ever ask for, and read-only.
    fn handle_rpcs3_action(
        &mut self,
        context: &egui::Context,
        action: Option<rpcs3_page::Rpcs3Action>,
    ) {
        if let Some(rpcs3_page::Rpcs3Action::Load) = action {
            // No selected-ROM identity pipeline reaches this branch of the
            // GUI yet (see `rpcs3_page`'s own module doc) - always `None`
            // for now, so this panel only ever shows RPCS3's own
            // environment health, never a game mapping. Once a verified
            // PS3 title ID becomes available here, thread it through
            // unchanged rather than deriving one in this method.
            self.start_rpcs3_status_load(context.clone(), None);
        }
    }

    /// Emulator Adapter Batch B: drains a completed RPCS3 status check,
    /// discarding anything whose generation is no longer current - the
    /// same stale-result guard every other background loader in this app
    /// uses.
    fn poll_rpcs3_status(&mut self) {
        if let rpcs3_page::Rpcs3State::Loading {
            generation,
            receiver,
        } = &self.rpcs3_status
            && let Ok((message_generation, outcome)) = receiver.try_recv()
            && message_generation == *generation
        {
            self.rpcs3_status = rpcs3_page::Rpcs3State::Ready {
                generation: message_generation,
                outcome,
            };
        }
    }

    fn start_pcsx2_status_load(
        &mut self,
        context: egui::Context,
        archive_path: Option<PathBuf>,
        verified_ps2_serial: Option<String>,
        verified_executable_crc: Option<String>,
    ) {
        self.pcsx2_status_generation += 1;
        let generation = self.pcsx2_status_generation;
        self.pcsx2_status_archive_path = archive_path;
        let (sender, receiver) = mpsc::channel();
        self.pcsx2_status = pcsx2_page::Pcsx2StatusState::Loading {
            generation,
            receiver,
        };
        thread::spawn(move || {
            let outcome =
                pcsx2_page::gather_pcsx2_status(verified_ps2_serial, verified_executable_crc);
            let _ = sender.send((generation, outcome));
            context.request_repaint();
        });
    }

    /// PCSX2 GUI Integration Batch H2: resets the PCSX2 status panel to
    /// `Idle` whenever the focused selected-ROM archive has changed since
    /// the current (or in-flight) result was loaded for, so a stale
    /// per-title mapping for the previous selection is never shown against
    /// the new one. Cheap no-op when the selection has not changed. Called
    /// once per frame right before rendering the panel.
    fn invalidate_pcsx2_status_if_selection_changed(&mut self, focused_archive: Option<&Path>) {
        if self.pcsx2_status_archive_path.as_deref() != focused_archive {
            self.pcsx2_status = pcsx2_page::Pcsx2StatusState::Idle;
            self.pcsx2_status_archive_path = focused_archive.map(Path::to_path_buf);
        }
    }

    /// PCSX2 GUI Integration Batch H2: applies the pure
    /// [`pcsx2_page::Pcsx2StatusAction`] the panel returned this frame -
    /// the only thing it can ever ask for, and read-only. The verified PS2
    /// serial/CRC come exclusively from `pcsx2_identity_for_workflow`,
    /// which itself only ever surfaces a value core already marked
    /// `IdentityStatus::Verified` (see that helper and
    /// `Pcsx2GameIdentity::from_report`) - an unresolved, ambiguous, or
    /// conflicting selection, or one for which no cheat workflow has been
    /// opened yet, yields `None` here, exactly like RPCS3's still-pending
    /// wiring above.
    fn handle_pcsx2_action(
        &mut self,
        context: &egui::Context,
        action: Option<pcsx2_page::Pcsx2StatusAction>,
    ) {
        if let Some(pcsx2_page::Pcsx2StatusAction::Load) = action {
            let identity = self
                .cheat_workflow
                .as_ref()
                .and_then(pcsx2_identity_for_workflow);
            let verified_ps2_serial = identity.as_ref().and_then(|id| id.serial.clone());
            let verified_executable_crc = identity
                .as_ref()
                .and_then(|id| id.verified_crc())
                .map(str::to_string);
            let archive_path = self.archive_context.focused.clone();
            self.start_pcsx2_status_load(
                context.clone(),
                archive_path,
                verified_ps2_serial,
                verified_executable_crc,
            );
        }
    }

    /// PCSX2 GUI Integration Batch H2: drains a completed PCSX2 status
    /// check, discarding anything whose generation is no longer current -
    /// the same stale-result guard every other background loader in this
    /// app uses.
    fn poll_pcsx2_status(&mut self) {
        if let pcsx2_page::Pcsx2StatusState::Loading {
            generation,
            receiver,
        } = &self.pcsx2_status
            && let Ok((message_generation, outcome)) = receiver.try_recv()
            && message_generation == *generation
        {
            self.pcsx2_status = pcsx2_page::Pcsx2StatusState::Ready {
                generation: message_generation,
                outcome,
            };
        }
    }

    /// Opens the confirmation screen for a repair. Opening it changes
    /// nothing; only `confirm_doctor_repair` can execute.
    fn review_doctor_repair(&mut self, action: DoctorRepairAction, finding_id: String) {
        let Some(outcome) = self.doctor_scan.displayed() else {
            return;
        };
        // Ambiguous by id alone means the caller should have supplied the
        // resource (which `show_doctor_page` always does), so refuse to guess.
        let Some(finding) = outcome.scan.finding_for(&finding_id, None).found() else {
            return;
        };
        self.doctor_repair_review = Some(DoctorRepairReview {
            action,
            finding_id,
            affected: finding.affected.as_ref().map(|path| path.display.clone()),
            finding_title: finding.title.clone(),
            evidence: finding.evidence.clone(),
        });
        self.doctor_repair_result = None;
    }

    /// Same as [`Self::review_doctor_repair`], for a finding identified by
    /// both its id and its exact resource.
    fn review_doctor_repair_for(
        &mut self,
        action: DoctorRepairAction,
        finding_id: String,
        affected: String,
    ) {
        let Some(outcome) = self.doctor_scan.displayed() else {
            return;
        };
        // The resource comes from a finding this scan reproduced, and is
        // re-matched against it here - it can only select, never introduce.
        let Some(finding) = outcome
            .scan
            .finding_for(&finding_id, Some(affected.as_str()))
            .found()
        else {
            return;
        };
        self.doctor_repair_review = Some(DoctorRepairReview {
            action,
            finding_id,
            affected: Some(affected),
            finding_title: finding.title.clone(),
            evidence: finding.evidence.clone(),
        });
        self.doctor_repair_result = None;
    }

    fn cancel_doctor_repair(&mut self) {
        // Cancelling is purely a state reset. Nothing was executed, so there
        // is nothing to undo.
        self.doctor_repair_review = None;
    }

    /// Executes the reviewed repair. The only path that mutates.
    ///
    /// Every safety gate lives in `execute_doctor_repair`, which re-resolves
    /// the finding against live state; nothing here trusts the review's
    /// captured path. Afterwards only the affected finding's own check is
    /// re-run (inside the executor), never the whole scan, and exactly one
    /// History entry is recorded whatever the result.
    /// Draws the Cheat Sources page and applies whatever it asked for.
    ///
    /// The state is loaded on first visit rather than at startup: opening the
    /// GUI should not read a preferences file for a page nobody has looked
    /// at. A path that cannot even be resolved (no `HOME`) is reported in
    /// place instead of failing the whole page, since every other part of the
    /// GUI still works without it.
    /// Draws the Canonical Organisation page, loading its state lazily.
    fn show_rom_organisation_page(&mut self, ui: &mut egui::Ui) {
        let page = self
            .rom_organisation_page
            .get_or_insert_with(rom_organisation_page::RomOrganisationPageState::load);
        rom_organisation_page::show_rom_organisation_page(ui, page);
    }

    fn show_repair_review_page(&mut self, ui: &mut egui::Ui) {
        let page = self
            .repair_review_page
            .get_or_insert_with(repair_review_page::RepairReviewPageState::default);
        // Drained before the view is built, so a running apply or scan keeps
        // repainting (progress/result reach the screen promptly) without the
        // page needing its own render loop.
        if page.poll_apply() || page.is_apply_running() {
            ui.ctx().request_repaint();
        }
        if page.poll_scan() || page.is_scan_running() {
            ui.ctx().request_repaint();
        }
        repair_review_page::show_repair_review_page(ui, page);
    }

    fn show_repair_history_page(&mut self, ui: &mut egui::Ui) {
        let page = self
            .repair_history_page
            .get_or_insert_with(repair_history_page::RepairHistoryPageState::load);
        // Drained before the view is built, so a running undo keeps
        // repainting until it settles.
        if page.poll_undo() || page.is_undo_running() {
            ui.ctx().request_repaint();
        }
        repair_history_page::show_repair_history_page(ui, page, &mut self.clipboard);
    }

    fn show_exact_duplicate_review_page(&mut self, ui: &mut egui::Ui) {
        let page = self.exact_duplicate_review_page.get_or_insert_with(
            exact_duplicate_review_page::ExactDuplicateReviewPageState::default,
        );
        if page.poll_scan() || page.is_scan_running() {
            ui.ctx().request_repaint();
        }
        exact_duplicate_review_page::show_exact_duplicate_review_page(ui, page);
    }

    fn show_optical_conversion_page(&mut self, ui: &mut egui::Ui) {
        let page = self
            .optical_conversion_page
            .get_or_insert_with(optical_conversion_page::OpticalConversionPageState::default);
        optical_conversion_page::show_optical_conversion_page(ui, page);
    }

    /// Renders the Doctor page over the shared `doctor_scan` state and
    /// dispatches whatever action it returned. Shared verbatim by the
    /// Problems & Repair -> Diagnostics tab and the dedicated
    /// `MainView::EmulatorSetup` destination, so the two can never diverge in
    /// behaviour or state (there is exactly one `doctor_scan`, one scan
    /// engine, one repair-review flow).
    fn show_doctor_page_body(&mut self, ui: &mut egui::Ui, context: &egui::Context) {
        let action = doctor_page::show_doctor_page(
            ui,
            &self.doctor_scan,
            &mut self.doctor_selected_finding,
            self.doctor_repair_review.as_ref(),
            self.doctor_repair_result.as_deref(),
            self.doctor_repair_finished_at_unix_seconds,
            &mut self.clipboard,
            self.ui_mode == GuiMode::GamerView,
        );
        match action {
            // Never `self.refresh(context)`: Doctor must not reload the
            // application or rescan the library.
            Some(doctor_page::DoctorPageAction::RunScan) => {
                self.start_doctor_scan(context.clone());
            }
            Some(doctor_page::DoctorPageAction::ReviewRepair {
                action,
                finding_id,
                affected,
            }) => match affected {
                Some(affected) => {
                    self.review_doctor_repair_for(action, finding_id, affected);
                }
                None => self.review_doctor_repair(action, finding_id),
            },
            Some(doctor_page::DoctorPageAction::ConfirmRepair) => {
                self.confirm_doctor_repair();
            }
            Some(doctor_page::DoctorPageAction::CancelRepair) => {
                self.cancel_doctor_repair();
            }
            None => {}
        }
    }

    /// The dedicated "Emulator Setup" destination: the same read-only Doctor
    /// readiness check the Diagnostics tab runs, presented as its own
    /// clearly-named page so emulator setup is discoverable without entering
    /// "Problems & Repair". Per-emulator rows appear in the scan's
    /// "Emulators" / "Emulator profiles" categories once the check has run.
    fn show_emulator_setup_page(&mut self, ui: &mut egui::Ui, context: &egui::Context) {
        // One-shot navigation hint: `take()` here means the first frame
        // after a repair-action navigation may scroll the relevant card
        // into view, and every later frame (and any manual scroll) is left
        // alone. Sidebar/Home navigation never sets this, so it is `None`.
        let focus_retroarch = matches!(
            self.emulator_setup_focus.take(),
            Some(EmulatorSetupFocus::RetroArch)
        );
        // RetroArch has a dedicated, cached discovery lane because its
        // profile/environment scan is also used by Cheats & Mods. Starting
        // it here makes Emulator Setup truthful on first use without moving
        // filesystem work into the pure Doctor runner.
        if matches!(self.retroarch_profiles, RetroArchProfilesState::NotScanned) {
            self.start_retroarch_profile_scan(context.clone());
        }
        widgets::page_header_with_icon(
            ui,
            crate::ui::icons::CHECK,
            "Emulator Setup",
            "Check the emulators EmuWiz can find and the profile or launch evidence available \
             for each one. This page keeps library diagnostics out of the way.",
        );
        ui.add_space(theme::SECTION_GAP);
        show_emulator_setup_summary(ui, self.doctor_scan.displayed(), &self.retroarch_profiles);
        ui.add_space(theme::SECTION_GAP);
        self.show_retroarch_core_folder_card(ui, context, focus_retroarch);
        ui.add_space(theme::SECTION_GAP);
        fn show_emulator_setup_summary(
            ui: &mut egui::Ui,
            outcome: Option<&DoctorScanOutcome>,
            retroarch_profiles: &RetroArchProfilesState,
        ) {
            widgets::card(ui, |ui| {
                ui.heading("Emulator readiness");
                let Some(outcome) = outcome else {
                    widgets::empty_state(
                        ui,
                        "Emulators have not been checked",
                        "Open Full diagnostics to check the supported emulators on this computer.",
                        None,
                    );
                    return;
                };
                let emulators = [
                    "Dolphin",
                    "PCSX2",
                    "PPSSPP",
                    "RPCS3",
                    "xemu",
                    "Xenia",
                    "DuckStation",
                    "RetroArch",
                    "ScummVM",
                    "shadPS4",
                ];
                let mut not_found = Vec::new();
                for name in emulators {
                    let matching = outcome.scan.findings.iter().find(|finding| {
                        matches!(
                            finding.category,
                            DoctorCategory::Emulators | DoctorCategory::EmulatorProfiles
                        ) && (finding.title.contains(name)
                            || finding.explanation.contains(name)
                            || finding.evidence.iter().any(|line| line.contains(name)))
                    });
                    let installation = outcome.scan.findings.iter().find(|finding| {
                        finding.category == DoctorCategory::EmulatorProfiles
                            && finding.title == format!("{name} installation found")
                    });
                    if matching.is_none() && name != "RetroArch" {
                        not_found.push(name);
                        continue;
                    }
                    ui.group(|ui| {
                        ui.horizontal_wrapped(|ui| {
                            ui.label(egui::RichText::new(name).strong());
                            match matching {
                                // Integration (Merge Rule 3): a discovered shadPS4
                                // is explicitly "Needs setup" - PS4 launch support
                                // is not claimed, so it never reads "Ready" or the
                                // generic "Setup incomplete".
                                Some(finding)
                                    if name == "shadPS4"
                                        && finding.title.contains("installation found") =>
                                {
                                    widgets::status_badge(
                                        ui,
                                        "Needs setup",
                                        widgets::StatusTone::Pending,
                                    );
                                }
                                Some(finding)
                                    if finding.title.contains("ready to launch")
                                        && finding.severity == DoctorSeverity::Info =>
                                {
                                    widgets::status_badge(
                                        ui,
                                        "Ready",
                                        widgets::StatusTone::Success,
                                    );
                                }
                                Some(_) => {
                                    widgets::status_badge(
                                        ui,
                                        "Setup incomplete",
                                        widgets::StatusTone::Warning,
                                    );
                                }
                                None => {
                                    let (label, tone) =
                                        retroarch_integration_presentation(retroarch_profiles);
                                    widgets::status_badge(ui, label, tone);
                                }
                            }
                        });
                        match matching {
                            Some(finding)
                                if name == "shadPS4"
                                    && finding.title.contains("installation found") =>
                            {
                                // Plain explanation inline; the raw discovery
                                // path stays under Technical details below.
                                ui.label(
                                    "shadPS4 is installed, but PS4 game identity and launch \
                                     support are not enabled yet.",
                                );
                            }
                            Some(finding)
                                if finding.title.contains("ready to launch")
                                    && finding.severity == DoctorSeverity::Info =>
                            {
                                ui.label("Ready to launch games.");
                            }
                            Some(finding) => {
                                let next_step = if finding.severity == DoctorSeverity::Info {
                                    "EmuWiz found this emulator, but setup is not complete."
                                } else {
                                    "Open Full diagnostics for the recommended next step."
                                };
                                // Integration: 1c825e7's flattened body wins here.
                                // The PS4 branch's discovered-but-unconfigured
                                // shadPS4 state is preserved by the dedicated
                                // `Some(finding) if name == "shadPS4"` arm above
                                // (rewoven into this structure); a shadPS4 that is
                                // *not* discovered falls to the beginner-consistent
                                // "Other supported emulators" list like every other
                                // undetected emulator (Merge Rule 3).
                                ui.label(next_step);
                            }
                            None => match retroarch_profiles {
                                RetroArchProfilesState::Scanning { .. } => {
                                    ui.label("Checking RetroArch setup…");
                                }
                                RetroArchProfilesState::Ready(_) => {
                                    ui.label("See the RetroArch card below for current setup.");
                                }
                                _ => {
                                    ui.label("Try the RetroArch check below.");
                                }
                            },
                        }
                        if let Some(finding) = matching {
                            widgets::technical_details(ui, ("emulator-finding", name), |ui| {
                                ui.label(&finding.explanation);
                                if let Some(evidence) = installation {
                                    ui.label(egui::RichText::new("Installation evidence").strong());
                                    for line in &evidence.evidence {
                                        ui.label(line);
                                    }
                                }
                            });
                        } else if let Some(evidence) = installation {
                            widgets::technical_details(ui, ("emulator-installation", name), |ui| {
                                for line in &evidence.evidence {
                                    ui.label(line);
                                }
                            });
                        }
                    });
                }
                if !not_found.is_empty() {
                    egui::CollapsingHeader::new("Other supported emulators")
                        .id_salt("emulator-setup-not-found")
                        .default_open(false)
                        .show(ui, |ui| {
                            for name in not_found {
                                ui.horizontal(|ui| {
                                    ui.label(name);
                                    widgets::status_badge(
                                        ui,
                                        "Not found",
                                        widgets::StatusTone::Pending,
                                    );
                                });
                            }
                        });
                }
            });
        }
        egui::CollapsingHeader::new("Full diagnostics")
            .id_salt("emulator-setup-full-diagnostics")
            .default_open(false)
            .show(ui, |ui| self.show_doctor_page_body(ui, context));
    }

    /// The normal-user RetroArch layer for Emulator Setup: one badge, one
    /// sentence, the three repair actions, and a Technical details
    /// expander. Every readiness word comes from
    /// [`retroarch_core_setup::core_folder_readiness`], a pure projection
    /// of the shared discovery state - this method never re-derives core
    /// availability or launch readiness. "Check again" and the post-pick
    /// / post-reset refresh all go through the one existing
    /// [`Self::start_retroarch_profile_scan`] lane.
    ///
    /// `focus_retroarch` is the one-shot navigation hint from
    /// `show_emulator_setup_page`: when `true` (a repair-action arrival)
    /// this card is scrolled into view once, aligned to the top. It never
    /// expands Technical details and never re-scrolls on later frames.
    fn show_retroarch_core_folder_card(
        &mut self,
        ui: &mut egui::Ui,
        context: &egui::Context,
        focus_retroarch: bool,
    ) {
        use retroarch_core_setup::{
            CoreFolderMode, CoreFolderReadinessKind, CoreFolderScan, core_folder_readiness,
        };

        let mode = CoreFolderMode::from_override(self.retroarch_core_directory_override.as_deref());
        let scanning = matches!(
            self.retroarch_profiles,
            RetroArchProfilesState::Scanning { .. }
        );
        let readiness = {
            let scan = match &self.retroarch_profiles {
                RetroArchProfilesState::NotScanned => CoreFolderScan::NotScanned,
                RetroArchProfilesState::Scanning { .. } => CoreFolderScan::Scanning,
                RetroArchProfilesState::Error(message) => CoreFolderScan::Failed(message.as_str()),
                RetroArchProfilesState::Ready(discovery) => CoreFolderScan::Ready(discovery),
            };
            core_folder_readiness(scan, &mode)
        };
        let rejected_pick = self.retroarch_core_folder_rejected_pick.clone();

        enum CoreFolderAction {
            Rescan,
            ChooseFolder(PathBuf),
            Reset,
        }
        let mut pending: Option<CoreFolderAction> = None;

        // Record the card's vertical span so a one-shot focus arrival can
        // scroll exactly this card into view without wrapping (and
        // re-indenting) the card body.
        let card_top = ui.cursor().top();
        widgets::card(ui, |ui| {
            ui.horizontal_wrapped(|ui| {
                ui.heading("RetroArch");
                widgets::status_badge(ui, readiness.badge_label, readiness.badge_tone);
            });
            if let Some(headline) = readiness.headline {
                ui.label(egui::RichText::new(headline).strong());
            }
            ui.label(readiness.sentence.as_str());
            if scanning {
                ui.horizontal(|ui| {
                    ui.spinner();
                    ui.label("Checking RetroArch support files…");
                });
            }
            ui.add_space(theme::SECTION_GAP);
            ui.horizontal_wrapped(|ui| {
                if ui
                    .add_enabled(
                        !scanning,
                        egui::Button::new(if readiness.kind == CoreFolderReadinessKind::Error {
                            "Try again"
                        } else {
                            "Check again"
                        }),
                    )
                    .clicked()
                {
                    pending = Some(CoreFolderAction::Rescan);
                }
                if ui
                    .add_enabled(
                        !scanning,
                        egui::Button::new(if readiness.kind == CoreFolderReadinessKind::Error {
                            "Choose folder"
                        } else {
                            "Choose game-support folder"
                        }),
                    )
                    .clicked()
                    && let Some(folder) = rfd::FileDialog::new().pick_folder()
                {
                    pending = Some(CoreFolderAction::ChooseFolder(folder));
                }
                if mode.is_custom()
                    && ui
                        .add_enabled(!scanning, egui::Button::new("Reset to automatic"))
                        .clicked()
                {
                    pending = Some(CoreFolderAction::Reset);
                }
            });
            if rejected_pick.is_some() {
                widgets::banner(
                    ui,
                    "Folder not usable",
                    "This folder could not be used for RetroArch game support. Choose another \
                     folder or reset to automatic detection.",
                    widgets::StatusTone::Blocked,
                );
            }
            egui::CollapsingHeader::new("Technical details")
                .id_salt("retroarch-core-folder-technical")
                .default_open(false)
                .show(ui, |ui| {
                    show_retroarch_core_folder_technical(
                        ui,
                        &self.retroarch_profiles,
                        &mode,
                        rejected_pick.as_deref(),
                    );
                });
        });

        // First frame after a repair-action arrival: bring the card into
        // view, aligned near the top. `focus_retroarch` came from a
        // one-shot `take()`, so this fires once and never fights a manual
        // scroll afterward. Technical details is untouched - it stays
        // collapsed.
        if focus_retroarch {
            let card_rect = egui::Rect::from_min_max(
                egui::pos2(ui.min_rect().left(), card_top),
                egui::pos2(ui.min_rect().right(), ui.cursor().top()),
            );
            ui.scroll_to_rect(card_rect, Some(egui::Align::TOP));
        }

        match pending {
            Some(CoreFolderAction::Rescan) => {
                self.retroarch_core_folder_rejected_pick = None;
                if !scanning {
                    self.start_retroarch_profile_scan(context.clone());
                }
            }
            Some(CoreFolderAction::ChooseFolder(folder)) => {
                self.apply_picked_retroarch_core_folder(folder, context.clone());
            }
            Some(CoreFolderAction::Reset) => {
                self.retroarch_core_folder_rejected_pick = None;
                self.clear_retroarch_core_directory_override();
                self.start_retroarch_profile_scan(context.clone());
            }
            None => {}
        }
    }

    /// The consolidated "Problems & Repair" destination - see
    /// `problems_repair_page`'s module doc. Renders the shared tab chrome,
    /// then dispatches to whichever tab `self.problems_repair_tab` currently
    /// names. Each arm calls exactly the same rendering this destination
    /// used before consolidation (`doctor_page::show_doctor_page`,
    /// `self.show_repair_review_page`, `self.show_repair_history_page`) -
    /// nothing here re-implements diagnosis or repair.
    fn show_problems_repair_page(&mut self, ui: &mut egui::Ui, context: &egui::Context) {
        if let Some(tab) =
            problems_repair_page::show_problems_repair_tabs(ui, self.problems_repair_tab)
        {
            self.navigate_to_problems_repair_tab(tab);
        }
        match self.problems_repair_tab {
            ProblemsRepairTab::Overview => {
                if let Some(tab) =
                    problems_repair_page::show_problems_repair_overview(ui, &self.doctor_scan)
                {
                    self.navigate_to_problems_repair_tab(tab);
                }
            }
            ProblemsRepairTab::Diagnostics => {
                let stale_review_clicked =
                    problems_repair_page::show_stale_library_review_entry(ui, &self.doctor_scan);
                self.show_doctor_page_body(ui, context);
                if stale_review_clicked {
                    self.navigate_to_missing_catalogue_review();
                }
            }
            ProblemsRepairTab::Repair => {
                // Review and History are rendered together rather than as a
                // further sub-tab level: both already lazily load their own
                // state regardless of which of `RepairReview`/`RepairHistory`
                // is the current `self.view`, so showing both keeps every
                // existing deep-link (either MainView value) landing on
                // visible, correct content without inventing a third tab
                // layer this task's UX sketch does not ask for.
                //
                // Duplicate Finder and Disc Conversion used to be reached
                // through secondary buttons here; since 0.8.1's "core
                // workflows directly discoverable" pass they are first-class
                // destinations (`MainView::ExactDuplicateReview` /
                // `MainView::DiscConversion`) with their own sidebar and
                // top-menu entries, so this tab is now purely repair-plan
                // review + history. A quiet cross-link is kept for the user
                // who is already here.
                ui.horizontal(|ui| {
                    if widgets::action_button(
                        ui,
                        "Open Duplicate Finder",
                        widgets::ActionStyle::Secondary,
                        true,
                    )
                    .on_hover_text(
                        "Find identical or equivalent copies and move extras into a recoverable \
                         quarantine. Opens the dedicated Duplicate Finder page.",
                    )
                    .clicked()
                    {
                        self.navigate_to_main_view(MainView::ExactDuplicateReview);
                    }
                    if widgets::action_button(
                        ui,
                        "Open Disc Conversion",
                        widgets::ActionStyle::Secondary,
                        true,
                    )
                    .on_hover_text(
                        "Convert a supported CUE/BIN source to a fingerprint-verified CHD. Opens \
                         the dedicated Disc Conversion page.",
                    )
                    .clicked()
                    {
                        self.navigate_to_main_view(MainView::DiscConversion);
                    }
                });
                ui.add_space(theme::SECTION_GAP);

                self.show_repair_review_page(ui);
                ui.add_space(theme::SECTION_GAP);
                ui.separator();
                ui.add_space(theme::SECTION_GAP);
                self.show_repair_history_page(ui);
            }
        }
    }

    fn show_library_view_history_page(&mut self, ui: &mut egui::Ui) {
        let page = self
            .library_view_history_page
            .get_or_insert_with(library_view_history_page::LibraryViewHistoryPageState::load);
        library_view_history_page::show_library_view_history_page(ui, page);
    }

    /// Gathers exactly what [`launch_readiness_page::show_launch_readiness_panel`]
    /// needs from state this app already has - never adds any new
    /// app-level state, and never calls the planner unless both real
    /// prerequisites (evidence loaded, RetroArch scanned) already hold.
    ///
    /// The `GameIdentityReport` comes from the selected evidence worker and
    /// is only trusted when its exact path matches the focused archive. This
    /// keeps launch planning on the core identity bridge while making it
    /// available without opening Cheats & Mods first.
    fn build_launch_readiness_input(
        &self,
        live: Option<&LoadedData>,
    ) -> launch_readiness_page::LaunchReadinessInput {
        use launch_readiness_page::LaunchReadinessInput;

        if !matches!(
            self.selected_evidence,
            selected_evidence_page::SelectedEvidenceState::Ready { .. }
        ) {
            return LaunchReadinessInput::EvidenceNotLoaded;
        }
        let RetroArchProfilesState::Ready(discovery) = &self.retroarch_profiles else {
            return LaunchReadinessInput::RetroArchNotScanned;
        };

        let focused = self.archive_context.focused.as_deref();
        let selected_game_identity_report =
            focused.and_then(|focused| match &self.selected_evidence {
                selected_evidence_page::SelectedEvidenceState::Ready { report, .. }
                    if report.path == focused =>
                {
                    Some(&report.game_identity_report)
                }
                _ => None,
            });
        // Keep older in-process test/compatibility fixtures usable when they
        // have not yet been given the new selected-evidence report. A real
        // selected game always takes the evidence-worker report above, so
        // opening Cheats & Mods is no longer required for launch planning.
        let game_identity_report = selected_game_identity_report
            .filter(|report| {
                !matches!(
                    archivefs_core::launch::canonical_identity_from_game_report(report).0,
                    archivefs_core::launch::CanonicalIdentityStatus::Unknown
                )
            })
            .or_else(|| {
                focused
                    .and_then(|focused| {
                        self.cheat_workflow
                            .as_ref()
                            .filter(|workflow| workflow.archive_path == focused)
                    })
                    .and_then(ready_game_identity)
            });

        let (identity_status, verified_facts) = match game_identity_report {
            Some(report) => archivefs_core::launch::canonical_identity_from_game_report(report),
            None => (
                archivefs_core::launch::CanonicalIdentityStatus::Unknown,
                Vec::new(),
            ),
        };
        // PCSX2's `Pcsx2LaunchRequest` needs a genuinely verified PS2
        // serial specifically - never `plan.game_key` alone, which for PS2
        // may instead be a verified executable CRC (see
        // `evidence_bridge::resolved_identity_for_platform`'s `Ps2Serial`/
        // `Pcsx2ExecutableCrc` handling) when no serial was verified.
        let verified_ps2_serial = verified_facts.iter().find_map(|fact| match fact {
            archivefs_core::launch::VerifiedIdentityFact::Ps2Serial(serial) => Some(serial.clone()),
            _ => None,
        });

        match identity_status {
            archivefs_core::launch::CanonicalIdentityStatus::Unknown => {
                return LaunchReadinessInput::IdentityUnknown;
            }
            archivefs_core::launch::CanonicalIdentityStatus::Conflicting => {
                return LaunchReadinessInput::IdentityConflicting;
            }
            archivefs_core::launch::CanonicalIdentityStatus::Resolved(_) => {}
        }

        let focused_record = live.and_then(|data| {
            focused.and_then(|path| {
                data.records
                    .iter()
                    .find(|record| record.mount_plan.archive.path == path)
            })
        });
        // Archive safety: this first slice never tracks a specific resolved
        // inner archive member, so a mounted container archive always
        // stays honestly unresolved/blocked here - see
        // `evidence_bridge::launch_content_ref_from_archive_record`'s own
        // doc comment. Never the outer archive path, never guessed.
        let content = match focused_record {
            Some(record) => {
                archivefs_core::launch::launch_content_ref_from_archive_record(record, None)
            }
            // Live library data isn't loaded, so content cannot be honestly
            // classified either way - this reads exactly like an
            // unresolved bridge result, never a fabricated "found" or a
            // misleading reuse of the evidence-not-loaded message (evidence
            // genuinely was loaded; only the live library data was not).
            None => archivefs_core::launch::LaunchContentRef {
                kind: None,
                container: None,
                resolved_path: None,
                requires_mount: false,
                provenance: "live library data is not loaded; content readiness cannot be \
                             checked"
                    .to_string(),
            },
        };

        // Real, already-discovered Dolphin profiles only - never a
        // fabricated `StandaloneProfileInput`. `DolphinLocalProfilesState`
        // starting `NotScanned`/`Scanning`/`Error` simply contributes no
        // Dolphin candidate yet (the same honest, fail-closed shape as an
        // empty slice), rather than blocking the whole panel the way a
        // missing RetroArch scan does - Dolphin readiness is additive here.
        let dolphin_context = match &self.dolphin_local_profiles {
            DolphinLocalProfilesState::Ready(ready) => {
                Some(launch_readiness_page::DolphinLaunchContext {
                    discovery: ready.discovery.clone(),
                    roots: ready.roots.clone(),
                })
            }
            DolphinLocalProfilesState::NotScanned
            | DolphinLocalProfilesState::Scanning { .. }
            | DolphinLocalProfilesState::Error(_) => None,
        };
        let dolphin_standalone_profiles: Vec<archivefs_core::launch::StandaloneProfileInput> =
            dolphin_context
                .as_ref()
                .map(|context| {
                    context
                        .discovery
                        .profiles
                        .iter()
                        .map(|profile| archivefs_core::launch::StandaloneProfileInput {
                            adapter_id: "dolphin",
                            profile_id: profile.profile_id.clone(),
                            profile_path: Some(profile.configuration_root.clone()),
                            eligible: profile.eligible,
                            firmware: archivefs_core::launch::FirmwareReadiness::NotRequired,
                        })
                        .collect()
                })
                .unwrap_or_default();

        // Real, already-discovered PCSX2 profiles and already-resolved PS2
        // firmware evidence only - never fabricated. Both
        // `Pcsx2LaunchProfilesState` and `Pcsx2FirmwareEvidenceState`
        // starting anything other than `Ready` simply contribute no PCSX2
        // candidate yet, the same additive-not-blocking shape as `dolphin`
        // above - a missing/incomplete DAT scan never widens readiness, it
        // only means no PCSX2 candidate is offered until it completes.
        let pcsx2_firmware_evidence: &[archivefs_core::dat::firmware_evidence::FirmwareIdentityRecord] =
            match &self.pcsx2_firmware_evidence {
                Pcsx2FirmwareEvidenceState::Ready(evidence) => evidence,
                Pcsx2FirmwareEvidenceState::NotLoaded
                | Pcsx2FirmwareEvidenceState::Loading { .. }
                | Pcsx2FirmwareEvidenceState::Error(_) => &[],
            };
        let pcsx2_context = match &self.pcsx2_launch_profiles {
            Pcsx2LaunchProfilesState::Ready(ready) => {
                Some(launch_readiness_page::Pcsx2LaunchContext {
                    discovery: ready.discovery.clone(),
                    roots: ready.roots.clone(),
                    firmware_evidence: pcsx2_firmware_evidence.to_vec(),
                    verified_ps2_serial: verified_ps2_serial.clone(),
                })
            }
            Pcsx2LaunchProfilesState::NotScanned
            | Pcsx2LaunchProfilesState::Scanning { .. }
            | Pcsx2LaunchProfilesState::Error(_) => None,
        };
        // A profile's BIOS readiness never depends on the currently
        // selected game - `resolve_pcsx2_bios`/`inspect_pcsx2_bios` only
        // ever read the profile's own global config and `bios/` directory
        // - so an all-`None` `Pcsx2GameRequest` here is a genuine,
        // honest inspection, not a placeholder.
        let pcsx2_standalone_profiles: Vec<archivefs_core::launch::StandaloneProfileInput> =
            pcsx2_context
                .as_ref()
                .map(|context| {
                    context
                        .discovery
                        .profiles
                        .iter()
                        .map(|profile| {
                            let inspection =
                                archivefs_core::patch_manager::inspect_pcsx2_game_with_firmware_evidence(
                                    profile,
                                    &archivefs_core::patch_manager::Pcsx2GameRequest {
                                        verified_ps2_serial: None,
                                        verified_executable_crc: None,
                                        emulator_serial: None,
                                    },
                                    &context.firmware_evidence,
                                );
                            archivefs_core::launch::StandaloneProfileInput {
                                adapter_id: "pcsx2",
                                profile_id: profile.profile_id.clone(),
                                profile_path: Some(profile.configuration_path.clone()),
                                eligible: profile.eligible,
                                firmware: archivefs_core::launch::pcsx2_firmware_readiness(
                                    inspection.inspection.bios.verification,
                                ),
                            }
                        })
                        .collect()
                })
                .unwrap_or_default();

        // Flycast is additive to the existing readiness view. Its adapter
        // already owns configuration, executable and firmware inspection;
        // this page only projects those read-only results into the shared
        // launch planner. A binding is resolved here solely so a missing,
        // unsafe or ambiguous executable is shown as blocked rather than
        // advertised as launch-ready. Core preflight repeats the same check.
        let flycast_standalone_profiles: Vec<archivefs_core::launch::StandaloneProfileInput> =
            match &self.flycast_profiles {
                FlycastProfilesState::Ready(ready) => ready
                    .discovery
                    .profiles
                    .iter()
                    .map(|profile| {
                        let verified_product_code = verified_facts.iter().find_map(|fact| match fact {
                            archivefs_core::launch::VerifiedIdentityFact::DreamcastProductCode(code) => {
                                Some(code.clone())
                            }
                            _ => None,
                        });
                        let inspection = archivefs_core::patch_manager::inspect_flycast_game(
                            profile,
                            &archivefs_core::patch_manager::FlycastGameRequest {
                                canonical_platform: Some("Dreamcast".to_string()),
                                flycast_platform: Some(
                                    archivefs_core::patch_manager::FlycastPlatform::Dreamcast,
                                ),
                                verified_dreamcast_product_code: verified_product_code,
                                ..Default::default()
                            },
                        );
                        archivefs_core::launch::StandaloneProfileInput {
                            adapter_id: "flycast",
                            profile_id: profile.profile_id.clone(),
                            profile_path: Some(profile.configuration_path.clone()),
                            eligible: profile.eligible
                                && archivefs_core::patch_manager::resolve_flycast_native_launch_binding(
                                    profile,
                                )
                                .is_ok(),
                            firmware: archivefs_core::launch::flycast_firmware_readiness(
                                inspection.health.system.dreamcast_bios,
                            ),
                        }
                    })
                    .collect(),
                FlycastProfilesState::NotScanned
                | FlycastProfilesState::Scanning { .. }
                | FlycastProfilesState::Error(_) => Vec::new(),
            };

        let mut standalone_profiles: Vec<archivefs_core::launch::StandaloneProfileInput> =
            dolphin_standalone_profiles
                .into_iter()
                .chain(pcsx2_standalone_profiles)
                .chain(flycast_standalone_profiles)
                .collect();

        // The remaining native adapters are additive inputs to the same
        // shared planner. Discovery and inspection are kept read-only and
        // bounded by their existing adapters; this block does not rebuild a
        // command, infer identity, or turn an executable's presence into a
        // Ready result. A later launch click still invokes that adapter's
        // own preflight and execution path.
        let empty_firmware: &[archivefs_core::dat::firmware_evidence::FirmwareIdentityRecord] = &[];
        if let Ok(roots) =
            archivefs_core::patch_manager::DuckStationProfileDiscoveryRoots::from_environment()
        {
            let discovery = archivefs_core::patch_manager::discover_duckstation_profiles(&roots);
            let request = archivefs_core::patch_manager::DuckStationGameRequest {
                verified_ps1_serial: verified_facts.iter().find_map(|fact| match fact {
                    archivefs_core::launch::VerifiedIdentityFact::Ps1Serial(serial) => {
                        Some(serial.clone())
                    }
                    _ => None,
                }),
                ..Default::default()
            };
            standalone_profiles.extend(discovery.profiles.iter().map(|profile| {
                let inspection =
                    archivefs_core::patch_manager::inspect_duckstation_game_with_firmware_evidence(
                        profile,
                        &request,
                        empty_firmware,
                    );
                archivefs_core::launch::StandaloneProfileInput {
                    adapter_id: "duckstation",
                    profile_id: profile.profile_id.clone(),
                    profile_path: Some(profile.configuration_path.clone()),
                    eligible: profile.eligible,
                    firmware: archivefs_core::launch::duckstation_firmware_readiness(
                        inspection.inspection.health.bios,
                    ),
                }
            }));
        }
        if let Ok(roots) =
            archivefs_core::patch_manager::PpssppProfileDiscoveryRoots::from_environment()
        {
            let discovery = archivefs_core::patch_manager::discover_ppsspp_profiles(&roots);
            standalone_profiles.extend(discovery.profiles.iter().map(|profile| {
                archivefs_core::launch::StandaloneProfileInput {
                    adapter_id: "ppsspp",
                    profile_id: profile.profile_id.clone(),
                    profile_path: Some(profile.configuration_path.clone()),
                    eligible: profile.eligible,
                    firmware: archivefs_core::launch::FirmwareReadiness::NotRequired,
                }
            }));
        }
        if let Ok(roots) =
            archivefs_core::patch_manager::Rpcs3ProfileDiscoveryRoots::from_environment()
        {
            let discovery = archivefs_core::patch_manager::discover_rpcs3_profiles(&roots);
            let request = archivefs_core::patch_manager::Rpcs3GameRequest {
                verified_ps3_title_id: verified_facts.iter().find_map(|fact| match fact {
                    archivefs_core::launch::VerifiedIdentityFact::Ps3TitleId(id) => {
                        Some(id.clone())
                    }
                    _ => None,
                }),
                ..Default::default()
            };
            standalone_profiles.extend(discovery.profiles.iter().map(|profile| {
                let inspection =
                    archivefs_core::patch_manager::inspect_rpcs3_game(profile, &request);
                archivefs_core::launch::StandaloneProfileInput {
                    adapter_id: "rpcs3",
                    profile_id: profile.profile_id.clone(),
                    profile_path: Some(profile.configuration_path.clone()),
                    eligible: profile.eligible,
                    firmware: archivefs_core::launch::rpcs3_firmware_readiness(
                        &inspection.health.firmware,
                    ),
                }
            }));
        }
        if let Ok(roots) =
            archivefs_core::patch_manager::XemuProfileDiscoveryRoots::from_environment()
        {
            let discovery = archivefs_core::patch_manager::discover_xemu_profiles(&roots);
            standalone_profiles.extend(discovery.profiles.iter().map(|profile| {
                archivefs_core::launch::StandaloneProfileInput {
                    adapter_id: "xemu",
                    profile_id: profile.profile_id.clone(),
                    profile_path: Some(profile.configuration_path.clone()),
                    eligible: profile.eligible,
                    // xemu's command planner performs its own MCPX/BIOS/
                    // EEPROM/HDD health validation during preflight.
                    firmware: archivefs_core::launch::FirmwareReadiness::NotRequired,
                }
            }));
        }
        if let XeniaProfilesState::Ready(discovery) = &self.xenia_profiles {
            let (title_id, media_id) = game_identity_report
                .map(|report| {
                    (
                        report.verified_xex_title_id().map(str::to_owned),
                        report.verified_xex_media_id().map(str::to_owned),
                    )
                })
                .unwrap_or((None, None));
            standalone_profiles.extend(discovery.profiles.iter().map(|profile| {
                archivefs_core::launch::StandaloneProfileInput {
                    adapter_id: "xenia",
                    profile_id: profile.profile_id.clone(),
                    profile_path: Some(profile.configuration_path.clone()),
                    eligible: profile.eligible,
                    firmware: archivefs_core::launch::FirmwareReadiness::NotRequired,
                }
            }));
            let _ = (title_id, media_id);
        }

        let duckstation_context =
            archivefs_core::patch_manager::DuckStationProfileDiscoveryRoots::from_environment()
                .ok()
                .map(|roots| launch_readiness_page::DuckStationLaunchContext {
                    discovery: archivefs_core::patch_manager::discover_duckstation_profiles(&roots),
                    roots,
                    firmware_evidence: Vec::new(),
                    verified_ps1_serial: verified_facts.iter().find_map(|fact| match fact {
                        archivefs_core::launch::VerifiedIdentityFact::Ps1Serial(serial) => {
                            Some(serial.clone())
                        }
                        _ => None,
                    }),
                });
        let ppsspp_context =
            archivefs_core::patch_manager::PpssppProfileDiscoveryRoots::from_environment()
                .ok()
                .map(|roots| launch_readiness_page::PpssppLaunchContext {
                    discovery: archivefs_core::patch_manager::discover_ppsspp_profiles(&roots),
                    roots,
                    verified_psp_disc_id: verified_facts.iter().find_map(|fact| match fact {
                        archivefs_core::launch::VerifiedIdentityFact::PspDiscId(id) => {
                            Some(id.clone())
                        }
                        _ => None,
                    }),
                });
        let rpcs3_context =
            archivefs_core::patch_manager::Rpcs3ProfileDiscoveryRoots::from_environment()
                .ok()
                .map(|roots| launch_readiness_page::Rpcs3LaunchContext {
                    discovery: archivefs_core::patch_manager::discover_rpcs3_profiles(&roots),
                    roots,
                    verified_ps3_title_id: verified_facts.iter().find_map(|fact| match fact {
                        archivefs_core::launch::VerifiedIdentityFact::Ps3TitleId(id) => {
                            Some(id.clone())
                        }
                        _ => None,
                    }),
                });
        let xemu_context =
            archivefs_core::patch_manager::XemuProfileDiscoveryRoots::from_environment()
                .ok()
                .map(|roots| launch_readiness_page::XemuLaunchContext {
                    discovery: archivefs_core::patch_manager::discover_xemu_profiles(&roots),
                    roots,
                    verified_xbox_title_id: verified_facts.iter().find_map(|fact| match fact {
                        archivefs_core::launch::VerifiedIdentityFact::XboxTitleId(id) => {
                            Some(id.clone())
                        }
                        _ => None,
                    }),
                });
        let xenia_context = if let XeniaProfilesState::Ready(discovery) = &self.xenia_profiles {
            let roots = archivefs_core::patch_manager::XeniaProfileDiscoveryRoots {
                explicit_configuration_roots: discovery
                    .profiles
                    .iter()
                    .map(|profile| profile.configuration_path.clone())
                    .collect(),
            };
            game_identity_report.map(|report| launch_readiness_page::XeniaLaunchContext {
                discovery: discovery.clone(),
                roots,
                verified_xex_title_id: report.verified_xex_title_id().map(str::to_owned),
                verified_xex_media_id: report.verified_xex_media_id().map(str::to_owned),
            })
        } else {
            None
        };

        let plan = archivefs_core::launch::build_launch_plan(
            &identity_status,
            &content,
            &standalone_profiles,
            &discovery.environment,
            &[],
        );
        LaunchReadinessInput::Plan {
            plan,
            dolphin: dolphin_context,
            pcsx2: pcsx2_context,
            duckstation: duckstation_context,
            ppsspp: ppsspp_context,
            rpcs3: rpcs3_context,
            xemu: xemu_context,
            xenia: xenia_context,
        }
    }

    /// The consolidated "Sources" destination - one sidebar entry over
    /// Libraries/DATs/Cheats/Discovery tabs (`SourcesTab`). Renders the
    /// shared heading and tab row, then dispatches to whichever tab
    /// `self.sources_tab` currently names. Each arm calls exactly the same
    /// rendering this destination used before consolidation
    /// (`show_sources_libraries_tab`, `self.show_dat_sources_page`,
    /// `self.show_cheat_sources_page`, `show_sources_discovery_tab`) -
    /// nothing here re-implements source management, DAT handling, cheat
    /// provisioning, or collection discovery.
    fn show_sources_page(&mut self, context: &egui::Context, ui: &mut egui::Ui, tab: SourcesTab) {
        if let Some(clicked) = sources_page::show_sources_tabs(ui, tab) {
            self.navigate_to_sources_tab(clicked);
        }
        match tab {
            SourcesTab::Libraries => self.show_sources_libraries_tab(context, ui),
            SourcesTab::Dats => self.show_dat_sources_page(ui),
            SourcesTab::Cheats => self.show_cheat_sources_page(context, ui),
            SourcesTab::Discovery => {
                sources_page::show_sources_discovery_tab(ui, &self.database_state)
            }
        }
    }

    /// The "Libraries" tab: source-folder configuration, the RetroArch
    /// cheat-database catalogue manager, BSFree provisioning, and RomM -
    /// exactly the content `MainView::Sources` rendered before
    /// consolidation, unchanged apart from the outer page header now being
    /// `show_sources_page`'s shared one.
    fn show_sources_libraries_tab(&mut self, context: &egui::Context, ui: &mut egui::Ui) {
        let sources = self
            .database_state
            .snapshot()
            .map(|snapshot| snapshot.source_views.as_slice())
            .unwrap_or(&[]);
        let archives = self
            .database_state
            .snapshot()
            .map(|snapshot| snapshot.archives.as_slice())
            .unwrap_or(&[]);
        let mount_root = match &self.state {
            LoadState::Ready(data) => Some(data.mount_root.as_path()),
            LoadState::Loading { .. } | LoadState::Error(_) => None,
        };

        show_sources_overview(
            ui,
            sources,
            &self.catalogue_manager,
            self.catalogue_retrieval.as_ref(),
        );
        ui.add_space(theme::SECTION_GAP);

        if let Some(last_scan) = &self.sources_last_scan
            && show_sources_last_scan_banner(ui, last_scan)
        {
            self.show_skipped_files = true;
            self.skipped_files_filter = None;
        }
        ui.add_space(theme::SECTION_GAP);

        let sources_action = show_sources_page(
            ui,
            sources,
            archives,
            mount_root,
            self.source_action.is_some(),
            &mut self.sources_add_dialog,
            &mut self.sources_remove_dialog,
            &mut self.clipboard,
        );
        if let Some(sources_action) = sources_action {
            match sources_action {
                SourcesPageAction::AddFolder(path) => {
                    self.start_source_action(context.clone(), SourceAction::Add(path));
                }
                SourcesPageAction::ScanOne(path) => {
                    self.start_source_action(context.clone(), SourceAction::ScanOne(path));
                }
                SourcesPageAction::ScanAll => {
                    self.start_source_action(context.clone(), SourceAction::ScanAll);
                }
                SourcesPageAction::RefreshStatus => {
                    self.start_database_action(context.clone(), false);
                }
                SourcesPageAction::AssignPlatform { path, platform } => {
                    self.start_source_action(
                        context.clone(),
                        SourceAction::AssignPlatform { path, platform },
                    );
                }
                SourcesPageAction::SetEnabled { path, enabled } => {
                    self.start_source_action(
                        context.clone(),
                        SourceAction::SetEnabled { path, enabled },
                    );
                }
                SourcesPageAction::ConfirmRemove {
                    path,
                    keep_catalogue,
                } => {
                    self.start_source_action(
                        context.clone(),
                        SourceAction::Remove {
                            path,
                            keep_catalogue,
                        },
                    );
                }
                SourcesPageAction::ViewInLibrary(path) => {
                    self.navigate_to_library_tab(LibraryTab::Archives);
                    self.library_source_filter = Some(Some(path));
                }
            }
        }

        ui.add_space(theme::SECTION_GAP);
        // Large, infrequently-touched configuration blocks - collapsed by
        // default so the Sources page opens on the source-folder list rather
        // than a wall of stacked cards. State persists for the session.
        let catalogue_action = widgets::collapsible_section(
            ui,
            "sources_catalogue_manager",
            "Cheat database & RetroArch catalogue",
            false,
            |ui| {
                ui.label(
                    "Download, update, or verify the trusted cheat database EmuWiz uses for \
                     cheat setup.",
                );
                show_retroarch_catalogue_manager(
                    ui,
                    &self.catalogue_manager,
                    self.catalogue_review.as_ref(),
                    self.catalogue_retrieval.as_ref(),
                    self.catalogue_last_result.as_ref(),
                    &mut self.clipboard,
                )
            },
        )
        .flatten();
        if let Some(catalogue_action) = catalogue_action {
            self.handle_catalogue_manager_action(context, catalogue_action);
        }

        ui.add_space(theme::SECTION_GAP);
        let bsfree_operation =
            widgets::collapsible_section(ui, "sources_bsfree", "BSFree source", false, |ui| {
                show_bsfree_source_card(
                    ui,
                    &self.bsfree_manager,
                    self.bsfree_operation.is_some(),
                    &mut self.bsfree_ui,
                    &mut self.clipboard,
                )
            })
            .flatten();
        if let Some(operation) = bsfree_operation {
            self.start_bsfree_operation(context.clone(), operation);
        }

        ui.add_space(theme::SECTION_GAP);
        let romm_view = romm_source::build_card_view(
            self.romm_snapshot.as_deref(),
            self.romm_operation
                .as_ref()
                .map(|running| &running.operation),
            self.romm_operation
                .as_ref()
                .is_some_and(|running| running.cancellation_requested),
        );
        let romm_progress = self
            .romm_operation
            .as_ref()
            .and_then(|running| running.progress.as_ref())
            .cloned();
        if let Some(request) = romm_source::show_romm_source_card(
            ui,
            &romm_view,
            &mut self.romm_ui,
            romm_progress.as_ref(),
        ) {
            match request {
                RommCardRequest::Start(operation) => {
                    // Declines when something is already running, which
                    // is what makes a double click harmless.
                    self.start_romm_operation(context.clone(), operation);
                }
                RommCardRequest::Cancel => self.cancel_romm_operation(),
                RommCardRequest::OpenConfigure => self.open_romm_configuration(),
                RommCardRequest::OpenBrowse(view) => self.open_romm_browse(view),
            }
        }

        if let Some(request) = self.show_romm_configuration_window(context) {
            self.handle_romm_config_request(context, request);
        }

        // Drawn as a window rather than appended here - see
        // `show_romm_browse_window`. Appending it below the source
        // card put it past the bottom of the viewport, so clicking
        // "Browse records" looked like it did nothing at all.
        if let Some(request) = self.show_romm_browse_window(context) {
            self.handle_romm_browse_request(context, request);
        }

        ui.add_space(theme::SECTION_GAP);
        show_sources_recent_activity(ui, &self.history);
    }

    fn show_cheat_sources_page(&mut self, context: &egui::Context, ui: &mut egui::Ui) {
        if self.cheat_sources_page.is_none() {
            match archivefs_core::patch_manager::default_cheat_sources_config_path() {
                Ok(path) => {
                    self.cheat_sources_page =
                        Some(cheat_sources_page::CheatSourcesPageState::load(
                            path,
                            archivefs_core::patch_manager::default_cheat_source_data_root(),
                        ));
                }
                Err(error) => {
                    widgets::banner(
                        ui,
                        "Preferences location unknown",
                        &format!(
                            "{error}. Cheat source preferences cannot be read or saved without a \
                             home directory."
                        ),
                        widgets::StatusTone::Blocked,
                    );
                    return;
                }
            }
        }

        let Some(page) = self.cheat_sources_page.as_mut() else {
            return;
        };
        let view = page.view();
        let action = cheat_sources_page::show_cheat_sources_page(
            ui,
            &view,
            &mut self.cheat_sources_ui,
            self.ui_mode == GuiMode::GamerView,
        );
        if let Some(action) = action {
            // Reverting throws away in-progress text and any open picker too:
            // leaving a typed priority behind after "Discard changes" would
            // show a value that is no longer anywhere in the state.
            if matches!(action, cheat_sources_page::CheatSourcesPageAction::Revert) {
                self.cheat_sources_ui.clear();
            }
            page.apply(action);
        }

        // The BSFree Archive card: the same Download/Import/Validate/Enable/
        // Remove controls the Sources page already offers, reusing the exact
        // `BsFreeOperation` plumbing (`start_bsfree_operation`,
        // `sources_page::show_bsfree_source_card`). Cheats & Mods tells the
        // user BSFree is managed from the Cheat Sources page, so the real
        // controls must actually live here rather than only on the generic
        // Sources page.
        ui.add_space(theme::SECTION_GAP);
        if let Some(operation) = sources_page::show_bsfree_source_card(
            ui,
            &self.bsfree_manager,
            self.bsfree_operation.is_some(),
            &mut self.bsfree_ui,
            &mut self.clipboard,
        ) {
            self.start_bsfree_operation(context.clone(), operation);
        }
    }

    /// Draws the DAT Sources page and applies whatever it asked for.
    ///
    /// Loaded on first visit rather than at startup, for the same reason Cheat
    /// Sources is. A path that cannot be resolved (no `HOME`) is reported in
    /// place instead of failing the whole page.
    ///
    /// The library folders offered as audit targets, and the trusted roots the
    /// hashing policy uses, both come from the same `Config` the rest of the
    /// build reads. A missing or unreadable config is not fatal here: it means
    /// no folders are offered and no symlink may be followed, which are the
    /// safe answers rather than an error the user cannot act on from this page.
    fn show_dat_sources_page(&mut self, ui: &mut egui::Ui) {
        self.show_dat_sources_page_mode(ui, false);
    }

    /// Shares loading, background-job polling, action dispatch, and history
    /// recording between the advanced catalogue page and the task-oriented
    /// Identify & Rename workflow. The two views deliberately use the same
    /// state and core actions; neither gets a private rename implementation.
    fn show_identify_rename_page(&mut self, ui: &mut egui::Ui) {
        self.show_dat_sources_page_mode(ui, true);
    }

    fn show_dat_sources_page_mode(&mut self, ui: &mut egui::Ui, identify_rename: bool) {
        if self.dat_sources_page.is_none() {
            let path = match archivefs_core::dat::sources::default_dat_sources_config_path() {
                Ok(path) => path,
                Err(error) => {
                    widgets::banner(
                        ui,
                        "Registry location unknown",
                        &format!(
                            "{error}. DAT sources cannot be read or saved without a home \
                             directory."
                        ),
                        widgets::StatusTone::Blocked,
                    );
                    return;
                }
            };
            let config = Config::load_default().ok();
            let library_folders = config
                .as_ref()
                .map(|config| config.source_folders.clone())
                .unwrap_or_default();
            let trusted = config
                .as_ref()
                .map(archivefs_core::safe_read::TrustedRoots::from_config)
                .unwrap_or_else(archivefs_core::safe_read::TrustedRoots::none);
            self.dat_sources_page = Some(
                dat_sources_page::DatSourcesPageState::load(path, library_folders, trusted)
                    .with_database_path(database_state_path(&self.database_state)),
            );
        }

        let Some(page) = self.dat_sources_page.as_mut() else {
            return;
        };
        // Drained before the view is built, so the view stays a pure function
        // of state. A running job repaints continuously; an idle page does not.
        if page.poll() || page.is_busy() {
            ui.ctx().request_repaint();
        }
        let view = page.view();
        let action = if identify_rename {
            if self.quick_rename_mode {
                dat_sources_page::show_quick_rename_page(ui, &view, &mut self.dat_sources_ui)
            } else {
                dat_sources_page::show_identify_rename_page(ui, &view, &mut self.dat_sources_ui)
            }
        } else {
            dat_sources_page::show_dat_sources_page(ui, &view, &mut self.dat_sources_ui)
        };
        if let Some(action) = action {
            let open_dat_sources = matches!(
                action,
                dat_sources_page::DatSourcesPageAction::OpenDatSources
            );
            let open_advanced = matches!(
                action,
                dat_sources_page::DatSourcesPageAction::OpenAdvancedIdentifyRename
            );
            if matches!(action, dat_sources_page::DatSourcesPageAction::Revert) {
                self.dat_sources_ui.clear();
            }
            page.apply(action);
            if open_dat_sources {
                self.quick_rename_mode = false;
                self.view = MainView::DatSources;
            } else if open_advanced {
                self.quick_rename_mode = false;
            }
        }
        // Surface apply/rollback outcomes into History & Logs, without private
        // paths (the journal keeps those, never the general log).
        for record in page.drain_history_records() {
            let entry = match record.action {
                dat_sources_page::RenameHistoryAction::Apply => HistoryEntry::new(
                    ActivityAction::DatRenameApply,
                    None,
                    ActivityOutcome::Completed,
                    format!("{}: {}", record.transaction_id, record.message),
                ),
                dat_sources_page::RenameHistoryAction::Rollback => HistoryEntry::new(
                    ActivityAction::DatRenameRollback,
                    None,
                    ActivityOutcome::Completed,
                    format!("{}: {}", record.transaction_id, record.message),
                ),
            };
            self.history.record(entry);
        }
        let reload_enriched_catalogue = page.take_identity_enrichment_completed();
        if reload_enriched_catalogue {
            self.start_database_action(ui.ctx().clone(), false);
        }
    }

    fn confirm_doctor_repair(&mut self) {
        let config = match Config::load_default() {
            Ok(config) => config,
            Err(error) => {
                self.doctor_repair_review.take();
                self.history.record(HistoryEntry::new(
                    ActivityAction::DoctorRepair,
                    None,
                    ActivityOutcome::Failed,
                    format!("Doctor repair could not start: {error}"),
                ));
                return;
            }
        };
        let index_path = match default_index_path() {
            Ok(path) => path,
            Err(error) => {
                self.doctor_repair_review.take();
                self.history.record(HistoryEntry::new(
                    ActivityAction::DoctorRepair,
                    None,
                    ActivityOutcome::Failed,
                    format!("Doctor repair could not start: {error}"),
                ));
                return;
            }
        };
        self.confirm_doctor_repair_with(config, index_path);
    }

    /// The repair itself, against an already-resolved configuration.
    ///
    /// `confirm_doctor_repair` reads the per-user configuration and the index
    /// path and delegates here. Tests supply both directly: reading them meant a
    /// test of *refusal* first had to get past a config load, so it passed only
    /// on a machine that happened to have `~/.config/archivefs/config.toml` and
    /// failed on CI, which does not.
    fn confirm_doctor_repair_with(&mut self, config: Config, index_path: PathBuf) {
        let Some(review) = self.doctor_repair_review.take() else {
            return;
        };
        let Some(displayed) = self.doctor_scan.displayed() else {
            return;
        };
        let request = DoctorRepairRequest {
            action: review.action,
            finding_id: review.finding_id.clone(),
            affected: review.affected.clone(),
            confirmed: true,
            dry_run: false,
        };
        let outcome = execute_doctor_repair(
            &request,
            &DoctorRepairContext {
                config: &config,
                scan: &displayed.scan,
                index_path: &index_path,
            },
        );

        // One History entry per attempt, success or not.
        self.history.record(HistoryEntry::new(
            ActivityAction::DoctorRepair,
            outcome
                .record
                .affected
                .as_ref()
                .map(|path| PathBuf::from(&path.display)),
            match outcome.record.status {
                DoctorRepairStatus::Succeeded => match outcome.record.verification {
                    DoctorRepairVerification::Verified => ActivityOutcome::Completed,
                    _ => ActivityOutcome::Skipped,
                },
                DoctorRepairStatus::DryRun => ActivityOutcome::Offered,
                DoctorRepairStatus::Rejected => ActivityOutcome::Rejected,
                DoctorRepairStatus::Failed => ActivityOutcome::Failed,
            },
            doctor_page::doctor_repair_history_detail(&outcome),
        ));
        self.doctor_repair_finished_at_unix_seconds = Some(
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .map(|duration| duration.as_secs() as i64)
                .unwrap_or(0),
        );
        // Update only the affected finding, never the whole scan: the repair
        // verified (or did not verify) exactly one check, and unrelated
        // findings must be preserved.
        if outcome.record.status == DoctorRepairStatus::Succeeded
            && outcome.record.verification == DoctorRepairVerification::Verified
            && let DoctorScanState::Ready(displayed) = &mut self.doctor_scan
        {
            let finding_id = outcome.record.finding_id.clone();
            let affected = outcome
                .record
                .affected
                .as_ref()
                .map(|path| path.display.clone());
            displayed.scan.findings.retain(|finding| {
                finding.id != finding_id
                    || finding.affected.as_ref().map(|path| path.display.clone()) != affected
            });
        }
        if self
            .doctor_selected_finding
            .as_deref()
            .map(doctor_page::doctor_finding_key_id)
            == Some(outcome.record.finding_id.as_str())
        {
            self.doctor_selected_finding = None;
        }
        self.doctor_repair_result = Some(Box::new(outcome));
    }

    fn poll_setup_action(&mut self, context: &egui::Context) {
        let result = self.setup_action.as_ref().and_then(|running| {
            running
                .receiver
                .try_recv()
                .ok()
                .map(|result| (running.action, result))
        });
        if let Some((action, result)) = result {
            self.setup_action = None;
            match result {
                Ok(message) => {
                    self.history.record(HistoryEntry::new(
                        ActivityAction::Setup,
                        None,
                        ActivityOutcome::Completed,
                        message.clone(),
                    ));
                    self.feedback = Some(ActionFeedback {
                        succeeded: true,
                        message,
                        cleanup: None,
                        warning: None,
                        more_information: None,
                    });
                    if action != SetupAction::OpenConfigFolder {
                        self.refresh_diagnostics(context);
                    }
                }
                Err(message) => {
                    self.history.record(HistoryEntry::new(
                        ActivityAction::Setup,
                        None,
                        ActivityOutcome::Failed,
                        message.clone(),
                    ));
                    self.feedback = Some(ActionFeedback {
                        succeeded: false,
                        message,
                        cleanup: None,
                        warning: None,
                        more_information: None,
                    });
                }
            }
        }
    }

    /// Whether a new platform-assignment action may start: not already
    /// running one (single-row *or* bulk - only one platform-metadata
    /// writer at a time, since both ultimately write the same
    /// `platform_assignments` table), and not in the middle of a database
    /// load/scan (the same "one database writer at a time" convention
    /// `start_database_action`'s own UI already enforces by disabling its
    /// buttons while loading - see `show_database_panel`). This never
    /// touches `is_busy()`/mount safety - platform assignment is
    /// metadata-only and deliberately independent of it.
    fn platform_action_available(&self) -> bool {
        self.platform_action.is_none()
            && self.bulk_platform_action.is_none()
            && self.alias_action.is_none()
            && self.missing_removal.is_none()
            && self.source_action.is_none()
            && self.library_view_action.is_none()
            && !self.database_state.is_loading()
    }

    /// The bulk counterpart to `platform_action_available` - see its doc
    /// comment for why single-row and bulk platform actions share one
    /// "no concurrent writer" gate.
    fn bulk_platform_action_available(&self) -> bool {
        self.platform_action_available()
    }

    fn start_platform_action(
        &mut self,
        context: egui::Context,
        archive_path: PathBuf,
        action: PlatformAction,
    ) {
        if !self.platform_action_available() {
            return;
        }
        let (sender, receiver) = mpsc::channel();
        self.history.record(HistoryEntry::new(
            ActivityAction::PlatformAssignment,
            Some(archive_path.clone()),
            ActivityOutcome::Started,
            match &action {
                PlatformAction::Set(platform) => format!("Setting platform to {platform}."),
                PlatformAction::Clear => "Clearing manual platform.".to_string(),
            },
        ));
        self.platform_action = Some(RunningPlatformAction {
            archive_path: archive_path.clone(),
            receiver,
        });
        thread::spawn(move || {
            let result =
                apply_platform_action(&archive_path, &action).map_err(|error| error.to_string());
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    fn poll_platform_action(&mut self, context: &egui::Context) {
        let result = self.platform_action.as_ref().and_then(|running| {
            running
                .receiver
                .try_recv()
                .ok()
                .map(|result| (running.archive_path.clone(), result))
        });
        let Some((archive_path, result)) = result else {
            return;
        };
        self.platform_action = None;
        match result {
            Ok(change) => {
                let message = format!(
                    "Platform changed from {} to {}.",
                    describe_platform_assignment(
                        change.old_platform.as_deref(),
                        change.old_source.as_deref()
                    ),
                    describe_platform_assignment(
                        change.new_platform.as_deref(),
                        change.new_source.as_deref()
                    )
                );
                self.history.record(HistoryEntry::new(
                    ActivityAction::PlatformAssignment,
                    Some(archive_path),
                    ActivityOutcome::Completed,
                    message.clone(),
                ));
                self.feedback = Some(ActionFeedback {
                    succeeded: true,
                    message,
                    cleanup: None,
                    warning: None,
                    more_information: None,
                });
                // Refresh only the cached database row - never the live
                // snapshot (self.state), which this action never touches.
                self.start_database_action(context.clone(), false);
            }
            Err(message) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::PlatformAssignment,
                    Some(archive_path),
                    ActivityOutcome::Failed,
                    message.clone(),
                ));
                self.feedback = Some(ActionFeedback {
                    succeeded: false,
                    message,
                    cleanup: None,
                    warning: None,
                    more_information: None,
                });
            }
        }
    }

    /// Starts a bulk platform action for every archive in
    /// `archive_paths` (the current multi-selection - see
    /// `show_bulk_platform_action_bar`) on a background thread, exactly
    /// like `start_platform_action` for a single archive. A no-op if
    /// `archive_paths` is empty or a platform-metadata write is already
    /// in progress (`bulk_platform_action_available`).
    fn start_bulk_platform_action(
        &mut self,
        context: egui::Context,
        archive_paths: Vec<PathBuf>,
        kind: BulkPlatformActionKind,
    ) {
        if !self.bulk_platform_action_available() || archive_paths.is_empty() {
            return;
        }
        let (sender, receiver) = mpsc::channel();
        let requested_paths = archive_paths.len();
        self.history.record(HistoryEntry::new(
            ActivityAction::BulkPlatformAssignment,
            None,
            ActivityOutcome::Started,
            match &kind {
                BulkPlatformActionKind::Set(platform) => format!(
                    "Setting platform to {platform} for {requested_paths} selected archives."
                ),
                BulkPlatformActionKind::Clear => {
                    format!("Clearing manual platform for {requested_paths} selected archives.")
                }
            },
        ));
        self.bulk_platform_action = Some(RunningBulkPlatformAction {
            kind: kind.clone(),
            requested_paths,
            receiver,
        });
        thread::spawn(move || {
            let result = apply_bulk_platform_action(&archive_paths, &kind)
                .map_err(|error| error.to_string());
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    /// Mirrors `poll_platform_action`: on success, refreshes only the
    /// cached database snapshot (never the live archive snapshot, never a
    /// scan - see `start_database_action(.., false)`). The actual
    /// selection pruning (requirement 7's "remove selections that no
    /// longer exist in the loaded catalogue") happens once that reload
    /// settles, in `poll_load`/`poll_database_load` via `prune_selection`,
    /// not here, since the reload is itself asynchronous and has not
    /// necessarily completed yet when this returns.
    fn poll_bulk_platform_action(&mut self, context: &egui::Context) {
        let result = self.bulk_platform_action.as_ref().and_then(|running| {
            running
                .receiver
                .try_recv()
                .ok()
                .map(|result| (running.kind.clone(), running.requested_paths, result))
        });
        let Some((kind, requested_paths, result)) = result else {
            return;
        };
        self.bulk_platform_action = None;
        match result {
            Ok(outcome) => {
                let action_word = match &kind {
                    BulkPlatformActionKind::Set(platform) => format!("set to {platform}"),
                    BulkPlatformActionKind::Clear => "cleared".to_string(),
                };
                let mut message = format!(
                    "Platform {action_word} for {} of {requested_paths} selected archive(s) ({} unchanged, {} missing from the database",
                    outcome.result.changed,
                    outcome.result.unchanged,
                    outcome.result.missing.len(),
                );
                if outcome.unresolved_paths > 0 {
                    message.push_str(&format!(
                        ", {} not yet scanned into the database",
                        outcome.unresolved_paths
                    ));
                }
                message.push(')');
                self.history.record(HistoryEntry::new(
                    ActivityAction::BulkPlatformAssignment,
                    None,
                    ActivityOutcome::Completed,
                    message.clone(),
                ));
                self.feedback = Some(ActionFeedback {
                    succeeded: true,
                    message,
                    cleanup: None,
                    warning: None,
                    more_information: None,
                });
                // Refresh only the cached database row - never the live
                // snapshot (self.state), which this action never touches.
                self.start_database_action(context.clone(), false);
            }
            Err(message) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::BulkPlatformAssignment,
                    None,
                    ActivityOutcome::Failed,
                    message.clone(),
                ));
                self.feedback = Some(ActionFeedback {
                    succeeded: false,
                    message,
                    cleanup: None,
                    warning: None,
                    more_information: None,
                });
                // Deliberately does not touch database_state or
                // selected_archives - requirement 8: a failed bulk action
                // must preserve both the prior cached rows and the
                // selection exactly as they were.
            }
        }
    }

    /// Whether a new custom-platform-alias action may start: not already
    /// running one, and not in the middle of a database load/scan - the
    /// same "one database writer at a time" convention
    /// `platform_action_available` already enforces for individual
    /// archive platform assignment. This never touches `is_busy()`/mount
    /// safety - alias management is metadata-only and deliberately
    /// independent of it, exactly like platform assignment.
    fn alias_action_available(&self) -> bool {
        self.alias_action.is_none()
            && self.platform_action.is_none()
            && self.bulk_platform_action.is_none()
            && self.missing_removal.is_none()
            && self.source_action.is_none()
            && self.library_view_action.is_none()
            && !self.database_state.is_loading()
    }

    fn start_alias_action(&mut self, context: egui::Context, action: AliasAction) {
        if !self.alias_action_available() {
            return;
        }
        let (sender, receiver) = mpsc::channel();
        self.history.record(HistoryEntry::new(
            ActivityAction::PlatformAliasManagement,
            None,
            ActivityOutcome::Started,
            match &action {
                AliasAction::Add { alias, platform } => {
                    format!("Adding platform alias '{alias}' -> {platform}.")
                }
                AliasAction::Remove { alias } => format!("Removing platform alias '{alias}'."),
            },
        ));
        self.alias_action = Some(RunningAliasAction {
            action: action.clone(),
            receiver,
        });
        thread::spawn(move || {
            let result = apply_alias_action(&action).map_err(|error| error.to_string());
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    /// Mirrors `poll_platform_action`: on success, refreshes only the
    /// cached database snapshot (`platform_aliases` is now part of it;
    /// see `load_snapshot_from`), never the live archive snapshot and
    /// never a scan. On a successful add, clears the input fields so the
    /// panel is ready for the next alias; a successful remove leaves
    /// them untouched (there is nothing to clear).
    fn poll_alias_action(&mut self, context: &egui::Context) {
        let result = self.alias_action.as_ref().and_then(|running| {
            running
                .receiver
                .try_recv()
                .ok()
                .map(|result| (running.action.clone(), result))
        });
        let Some((action, result)) = result else {
            return;
        };
        self.alias_action = None;
        match result {
            Ok(()) => {
                let message = match &action {
                    AliasAction::Add { alias, platform } => {
                        format!(
                            "Alias added: '{alias}' -> {platform}. Run a library scan to apply it."
                        )
                    }
                    AliasAction::Remove { alias } => {
                        format!(
                            "Alias removed: '{alias}'. Run a library scan to apply this change."
                        )
                    }
                };
                self.history.record(HistoryEntry::new(
                    ActivityAction::PlatformAliasManagement,
                    None,
                    ActivityOutcome::Completed,
                    message.clone(),
                ));
                self.feedback = Some(ActionFeedback {
                    succeeded: true,
                    message,
                    cleanup: None,
                    warning: None,
                    more_information: None,
                });
                if matches!(action, AliasAction::Add { .. }) {
                    self.new_alias_text.clear();
                    self.new_alias_platform_choice = None;
                }
                self.start_database_action(context.clone(), false);
            }
            Err(message) => {
                let action_label = match &action {
                    AliasAction::Add { alias, .. } => format!("Add alias '{alias}'"),
                    AliasAction::Remove { alias } => format!("Remove alias '{alias}'"),
                };
                self.history.record(HistoryEntry::new(
                    ActivityAction::PlatformAliasManagement,
                    None,
                    ActivityOutcome::Failed,
                    format!("{action_label}: {message}"),
                ));
                self.feedback = Some(ActionFeedback {
                    succeeded: false,
                    message,
                    cleanup: None,
                    warning: None,
                    more_information: None,
                });
            }
        }
    }

    /// Whether a new Sources-page action may start - the same "one
    /// database writer at a time" convention `alias_action_available`
    /// already enforces, extended to also block while a source action is
    /// already running (and vice versa via the other `*_available`
    /// checks, once updated).
    fn source_action_available(&self) -> bool {
        self.source_action.is_none()
            && self.alias_action.is_none()
            && self.platform_action.is_none()
            && self.bulk_platform_action.is_none()
            && self.missing_removal.is_none()
            && self.library_view_action.is_none()
            && !self.database_state.is_loading()
    }

    fn start_source_action(&mut self, context: egui::Context, action: SourceAction) {
        if !self.source_action_available() {
            return;
        }
        let (sender, receiver) = mpsc::channel();
        self.history.record(HistoryEntry::new(
            source_action_log_category(&action),
            source_action_path(&action),
            ActivityOutcome::Started,
            source_action_started_message(&action),
        ));
        self.source_action = Some(RunningSourceAction {
            action: action.clone(),
            receiver,
            worker: None,
        });
        let worker = thread::spawn(move || {
            let result = run_source_action(&action).map_err(|error| error.to_string());
            let _ = sender.send(result);
            context.request_repaint();
        });
        self.source_action.as_mut().unwrap().worker = Some(worker);
    }

    /// Mirrors `poll_alias_action`: on success, refreshes only the cached
    /// database snapshot (never a live scan) - `source_views` is rebuilt
    /// fresh as part of that same snapshot load, which is also exactly
    /// what keeps the Health cache correctly invalidated (see
    /// `HealthReportCacheKey`'s doc comment: it already keys on the
    /// snapshot's pointer identity, and a source action always produces a
    /// new snapshot `Box`).
    fn poll_source_action(&mut self, context: &egui::Context) {
        let result = self.source_action.as_ref().and_then(|running| {
            running
                .receiver
                .try_recv()
                .ok()
                .map(|result| (running.action.clone(), result))
        });
        let Some((action, result)) = result else {
            return;
        };
        let worker = self
            .source_action
            .take()
            .and_then(|mut running| running.worker.take());
        if let Some(worker) = worker {
            let _ = worker.join();
        }
        let log_category = source_action_log_category(&action);
        let path = source_action_path(&action);
        let gamer_scan_pending =
            self.gamer_view_scan_pending_review || self.gamer_view_pending_first_scan.is_some();
        match result {
            Ok(outcome) => {
                let message = source_action_success_message(&outcome);
                // Adding, removing, enabling or disabling a source is an explicit
                // configuration-changing event. Refresh the sole GUI snapshot once;
                // ordinary rendering never polls the file.
                let config_reload_warning = self.gui_config.reload_default().err().map(|error| {
                    format!(
                        "The source change succeeded, but config.toml could not be reloaded: \
                         {error}. The previous in-memory configuration is still in use."
                    )
                });
                self.history.record(HistoryEntry::new(
                    log_category,
                    path,
                    ActivityOutcome::Completed,
                    message.clone(),
                ));
                self.feedback = Some(ActionFeedback {
                    succeeded: true,
                    message,
                    cleanup: None,
                    warning: config_reload_warning.clone(),
                    more_information: None,
                });
                if matches!(outcome, SourceActionOutcome::Added(_)) {
                    self.sources_add_dialog = None;
                }
                // Gamer View's "Add games" chains straight into a scan of
                // the exact folder just added - see
                // `gamer_view_pending_first_scan` - so a first-run person
                // never has to find a separate "Scan" step themselves, and
                // never sees the Advanced-View-flavored "Source added...
                // Use Scan to catalogue it" message this action would
                // otherwise set below. Only fires for the path Gamer View
                // itself just added; any other Add (including a normal
                // Advanced View Sources page add) leaves the pending path
                // at `None` and chains/overrides nothing. Left set (not
                // cleared here) so the *next* `Scanned` outcome - the one
                // this chains - is also recognised as Gamer View's, and
                // gets its own human-language override below instead of
                // "Scan complete: N source(s)... N archive(s)...".
                if let SourceActionOutcome::Added(added) = &outcome
                    && self.gamer_view_pending_first_scan.as_deref() == Some(added.path.as_path())
                {
                    self.feedback = Some(ActionFeedback {
                        succeeded: true,
                        message: "Looking through your folder...".to_string(),
                        cleanup: None,
                        warning: config_reload_warning.clone(),
                        more_information: None,
                    });
                    self.start_source_action(
                        context.clone(),
                        SourceAction::ScanOne(added.path.clone()),
                    );
                } else if let SourceActionOutcome::Scanned(summary) = &outcome
                    && gamer_scan_pending
                {
                    self.gamer_view_pending_first_scan = None;
                    self.gamer_view_scan_pending_review = false;
                    self.gamer_view_scan_review_available = gamer_view_scan_needs_review(summary);
                    self.feedback = Some(ActionFeedback {
                        succeeded: true,
                        message: gamer_view_first_scan_message(summary),
                        cleanup: None,
                        warning: config_reload_warning,
                        more_information: None,
                    });
                }
                if matches!(action, SourceAction::Remove { .. }) {
                    self.sources_remove_dialog = None;
                }
                // Carry this scan's skip detail into the plain snapshot
                // reload triggered below, so Database Status -> Skipped
                // files -> Inspect... becomes reachable without a separate
                // Database Status -> Scan library run. Any other source
                // action clears it, so a stale summary can never attach to
                // an unrelated later reload.
                self.pending_source_scan_summary = match &outcome {
                    SourceActionOutcome::Scanned(summary) => Some(summary.clone()),
                    _ => None,
                };
                if let SourceActionOutcome::Scanned(summary) = &outcome {
                    let scope = match &action {
                        SourceAction::ScanOne(scanned_path) => {
                            SourcesScanScope::One(scanned_path.clone())
                        }
                        _ => SourcesScanScope::AllEnabled,
                    };
                    self.sources_last_scan = Some(SourcesLastScan {
                        scope,
                        archives_found: summary.counts.archives_seen,
                        skipped_total: summary.skipped_files_total(),
                        ingestion_stats: summary.ingestion_stats,
                    });
                }
                self.start_database_action(context.clone(), false);
            }
            Err(message) => {
                if self.gamer_view_scan_pending_review {
                    self.gamer_view_scan_pending_review = false;
                }
                self.history.record(HistoryEntry::new(
                    log_category,
                    path,
                    ActivityOutcome::Failed,
                    message.clone(),
                ));
                self.feedback = Some(ActionFeedback {
                    succeeded: false,
                    message,
                    cleanup: None,
                    warning: None,
                    more_information: None,
                });
            }
        }
    }

    fn start_bsfree_operation(&mut self, context: egui::Context, operation: BsFreeOperation) {
        if self.bsfree_operation.is_some() {
            return;
        }
        let (sender, receiver) = mpsc::channel();
        self.bsfree_operation = Some(RunningBsFreeOperation {
            operation: operation.clone(),
            receiver,
        });
        thread::spawn(move || {
            let result = run_bsfree_operation(&operation).map_err(|error| error.to_string());
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    /// Starts one RomM operation, or declines.
    ///
    /// Declining is the point: a second click while something is running must not
    /// launch a duplicate, and a mutating operation must not overlap another. A
    /// status load is allowed to be the exception only because it writes nothing.
    fn start_romm_operation(&mut self, context: egui::Context, operation: RommOperation) -> bool {
        if let Some(running) = &self.romm_operation {
            // A status load asked for while something else runs is dropped rather
            // than queued: the operation that finishes will refresh anyway.
            let _ = running;
            return false;
        }
        self.romm_generation = self.romm_generation.wrapping_add(1);
        let generation = self.romm_generation;
        let cancellation = Arc::new(AtomicBool::new(false));
        let worker_cancellation = cancellation.clone();
        let (sender, receiver) = mpsc::channel();
        let (progress_sender, progress_receiver) = mpsc::channel();
        // A fresh operation supersedes the previous result, so the card never shows
        // an old outcome beside new progress.
        self.romm_ui.last_outcome = None;
        if operation.is_mutating() {
            self.history.record(HistoryEntry::new(
                ActivityAction::RommSource,
                None,
                ActivityOutcome::Started,
                format!("{}.", operation.label()),
            ));
        }
        self.romm_operation = Some(RunningRommOperation {
            generation,
            operation: operation.clone(),
            cancellation,
            receiver,
            progress_receiver,
            progress: operation.reports_progress().then(RommProgress::default),
            cancellation_requested: false,
        });
        let trusted_roots = self.gui_config.source_roots().map(|roots| roots.to_vec());
        let database_path = database_state_path(&self.database_state);
        let progress_context = context.clone();
        thread::spawn(move || {
            let report = |event: RommProgressEvent| {
                let _ = progress_sender.send((generation, event));
                progress_context.request_repaint();
            };
            let result = run_romm_operation(
                &operation,
                &trusted_roots,
                database_path.as_deref(),
                generation,
                &worker_cancellation,
                &report,
            );
            let _ = sender.send((generation, result));
            context.request_repaint();
        });
        true
    }

    /// Asks the running operation to stop. Only the current one: an older
    /// generation has already been forgotten.
    fn cancel_romm_operation(&mut self) {
        if let Some(running) = self.romm_operation.as_mut() {
            running.cancellation.store(true, Ordering::Release);
            running.cancellation_requested = true;
        }
    }

    fn poll_romm_operation(&mut self, context: &egui::Context) {
        // Progress first, discarding anything from a superseded generation.
        if let Some(running) = self.romm_operation.as_mut() {
            let current = running.generation;
            for (generation, event) in running.progress_receiver.try_iter() {
                if generation != current {
                    continue;
                }
                let progress = running.progress.get_or_insert_with(RommProgress::default);
                match event {
                    RommProgressEvent::Import(import) => progress.absorb(import),
                    RommProgressEvent::Note(note) => progress.note(note),
                    RommProgressEvent::StaleProgress { probed, total } => {
                        self.romm_stale_progress =
                            Some(crate::romm_browse::StaleProgress { probed, total });
                    }
                    RommProgressEvent::Hashing(hashing) => {
                        self.romm_hash_progress = Some(hashing);
                    }
                }
            }
        }

        let Some((generation, operation, result)) =
            self.romm_operation.as_ref().and_then(|running| {
                running
                    .receiver
                    .try_recv()
                    .ok()
                    .map(|(generation, result)| (generation, running.operation.clone(), result))
            })
        else {
            return;
        };
        if generation != self.romm_generation {
            // A result from an operation that has already been superseded. Dropping
            // it is what stops it overwriting the current one's outcome.
            self.romm_operation = None;
            return;
        }
        self.romm_operation = None;
        self.romm_hash_progress = None;

        let previous_outcome = self.romm_ui.last_outcome.take();
        let offline_usable = self.romm_snapshot.as_deref().is_some_and(|snapshot| {
            snapshot.status.state
                == archivefs_core::identity_source::status::ProviderState::ReadyOffline
        });
        self.romm_ui.last_outcome = Some(romm_source::build_result_view(
            &operation,
            result.as_ref().map_err(String::as_str),
            offline_usable,
        ));
        if operation.is_mutating() {
            // A failed connection test while imported identity is still being
            // served is the offline case working as intended: it must not
            // surface as a scary global "Failed". The technical reason stays
            // in the message, so History & Logs preserves it exactly.
            let offline_friendly =
                offline_usable && operation == RommOperation::TestConnection && result.is_err();
            self.history.record(HistoryEntry::new(
                ActivityAction::RommSource,
                None,
                if offline_friendly {
                    ActivityOutcome::OfflineUsable
                } else {
                    match &result {
                        Ok(_) => ActivityOutcome::Completed,
                        Err(_) => ActivityOutcome::Failed,
                    }
                },
                if offline_friendly {
                    format!(
                        "RomM could not be reached, but the offline copy still works. \
                         Technical detail: {message}",
                        message = result.as_ref().unwrap_err()
                    )
                } else {
                    match &result {
                        Ok(_) => format!("{} completed.", operation.label()),
                        Err(message) => format!("{} failed: {message}", operation.label()),
                    }
                },
            ));
        }
        // Browsing results belong to the panel rather than to the card, and each is
        // only accepted if it still answers what the panel is asking for.
        if let Ok(outcome) = &result {
            let landed = match outcome {
                RommOperationOutcome::Records(page) => {
                    match self.romm_browse.as_mut() {
                        Some(state) => {
                            if state.accepts_page(page, &page.cache) {
                                state.needs_reload = false;
                                state.page = Some(page.clone());
                            } else {
                                // The filters or the cache moved on while this was in
                                // flight. Mixing generations would show a page that
                                // answers a question nobody is asking any more.
                                state.needs_reload = true;
                            }
                            true
                        }
                        // The panel was closed before the page arrived.
                        None => true,
                    }
                }
                RommOperationOutcome::RecordDetail(detail) => {
                    if let Some(state) = self.romm_browse.as_mut() {
                        let requested_id = match &operation {
                            RommOperation::LoadRecordDetail { romm_game_id } => romm_game_id,
                            _ => unreachable!("a detail result must come from a detail request"),
                        };
                        if state.accepts_detail(requested_id, detail.as_ref().as_ref()) {
                            state.pending_detail_id = None;
                            state.detail = detail.as_ref().clone().map(Box::new);
                            state.detail_problem = detail.is_none().then(|| {
                                format!(
                                    "RomM record {requested_id} is no longer present in the \
                                     published cache. Refresh the records view."
                                )
                            });
                        }
                    }
                    true
                }
                RommOperationOutcome::Conflicts(page) => {
                    if let Some(state) = self.romm_browse.as_mut() {
                        if state.accepts_conflicts(page, &page.cache) {
                            state.conflicts = Some(page.clone());
                        } else {
                            state.needs_reload = true;
                        }
                    }
                    true
                }
                RommOperationOutcome::Stale(view) => {
                    if let Some(state) = self.romm_browse.as_mut() {
                        if state.accepts_stale(view, &view.cache) {
                            state.stale = Some(view.clone());
                        } else {
                            state.needs_reload = true;
                        }
                    }
                    self.romm_stale_progress = None;
                    true
                }
                RommOperationOutcome::GameIdentity(panel) => {
                    if self.romm_game.accepts_panel(panel) {
                        self.romm_game.panel = Some(panel.clone());
                        self.romm_game.needs_reload = false;
                    } else {
                        // The selection moved while this was in flight. Drawing it
                        // would attach one game's evidence to another's file.
                        self.romm_game.needs_reload = true;
                    }
                    true
                }
                RommOperationOutcome::Cover(outcome) => {
                    if self.romm_game.accepts_cover(outcome) {
                        // The texture is dropped here rather than in the renderer, so
                        // a cover cleared mid-fetch cannot leave the old pixels up.
                        self.romm_game.cover_texture = None;
                        self.romm_game.cover_key = None;
                        self.romm_game.cover = outcome.state.clone();
                        self.romm_game.cover_cache =
                            Some((outcome.cached_items, outcome.cached_bytes));
                    }
                    if let Some(state) = self.romm_browse.as_mut()
                        && state.accepts_cover(outcome)
                    {
                        state.detail_cover_texture = None;
                        state.detail_cover_key = None;
                        state.detail_cover = outcome.state.clone();
                    }
                    // A stale cover is deliberately discarded, but it is still a
                    // panel result rather than a source-card outcome banner.
                    true
                }
                _ => false,
            };
            if landed {
                // Not a card result: browsing produces no outcome banner.
                self.romm_ui.last_outcome = previous_outcome;
                return;
            }
        }
        if let (RommOperation::LoadRecordDetail { romm_game_id }, Err(message)) =
            (&operation, &result)
            && let Some(state) = self.romm_browse.as_mut()
            && state.pending_detail_id.as_deref() == Some(romm_game_id)
        {
            state.pending_detail_id = None;
            state.detail_problem = Some(message.clone());
        }
        if let Ok(RommOperationOutcome::Verified(outcome)) = &result {
            // Both a card result and panel state: the panel inside it was rebuilt
            // from the verification that was just stored, so the verdict on screen is
            // recomputed rather than assumed.
            if self.romm_game.accepts_verification(outcome) {
                self.romm_game.panel = Some(outcome.panel.clone());
                self.romm_game.verification = Some(outcome.clone());
                self.romm_game.needs_reload = false;
            }
            self.romm_hash_progress = None;
        }
        // An import that actually *published* replaced the identity cache, so what any
        // local path resolves to may have changed. Gamer View's worker holds its path
        // index in memory - rebuilding it costs a full read of 36,259 records, which
        // is why it is rebuilt on this signal rather than on a timer or per frame.
        //
        // `published` is the exact condition, not merely "an import finished". A
        // sample import deliberately never publishes, and an import that failed
        // leaves the previous cache in place; refreshing for either would withdraw
        // every cover on screen to revalidate against a catalogue that had not
        // changed. This is also what keeps a failed import from discarding a working
        // index.
        if matches!(&result, Ok(RommOperationOutcome::Import(summary)) if summary.published) {
            // Ready covers become `Revalidating`: their textures are kept so an
            // unchanged record costs no decode, but the placeholder is drawn until
            // the refreshed catalogue confirms the record, so a path whose provider
            // id moved cannot show the old cover even for one frame.
            self.gamer_covers.identity_refreshed();
            if let Some(worker) = self.gamer_cover_worker.as_ref() {
                worker.reindex();
            }
            // The same worker may have enriched platform metadata in the
            // existing catalogue. Reload the read-only snapshot so Library and
            // Gamer View show it immediately; no rescan or ROM read is needed.
            self.start_database_action(context.clone(), false);
        }
        if let Ok(RommOperationOutcome::Preview(summary)) = &result {
            // A preview is only meaningful while the dialog that asked for it is
            // open; if it has been closed, the result is dropped.
            if self.romm_config_draft.is_some() {
                self.romm_preview = Some(summary.clone());
            }
        }
        if let Ok(RommOperationOutcome::Saved(_)) = &result {
            // Saved, so the dialog has served its purpose and the card is reloaded
            // from disk rather than from what was typed.
            self.close_romm_configuration();
            // This is a deliberate reload boundary. Rendering never reloads the
            // application configuration, and a failed reload retains the previous
            // usable snapshot instead of replacing it with an empty one.
            if let Err(error) = self.gui_config.reload_default() {
                self.feedback = Some(ActionFeedback {
                    succeeded: false,
                    message: format!(
                        "RomM was saved, but EmuWiz could not reload its main configuration: \
                         {error}. The previous in-memory configuration is still in use."
                    ),
                    cleanup: None,
                    warning: None,
                    more_information: Some(
                        "Fix config.toml, then use an explicit refresh or save again.".to_string(),
                    ),
                });
            }
        }
        if let Ok(RommOperationOutcome::Snapshot(snapshot)) = &result {
            // The one result that is not a user-visible outcome: it *is* the card's
            // state. A snapshot never overwrites a real result view.
            self.romm_snapshot = Some(snapshot.clone());
            self.romm_ui.last_outcome = previous_outcome;
            return;
        }
        // A mutating operation may have changed what the card shows, so the card is
        // refreshed from authoritative state rather than from an optimistic counter.
        // A failure leaves the previous snapshot in place until the reload replaces
        // it, so a failed refresh never erases counts that were true.
        if operation.is_mutating() {
            self.start_romm_status_load(context.clone());
        }
    }

    /// Loads the snapshot. Separate from `start_romm_operation` so it can run
    /// straight after another operation completes.
    fn start_romm_status_load(&mut self, context: egui::Context) {
        if self.romm_operation.is_some() {
            return;
        }
        self.romm_generation = self.romm_generation.wrapping_add(1);
        let generation = self.romm_generation;
        let cancellation = Arc::new(AtomicBool::new(false));
        let (sender, receiver) = mpsc::channel();
        let (_progress_sender, progress_receiver) = mpsc::channel();
        self.romm_operation = Some(RunningRommOperation {
            generation,
            operation: RommOperation::LoadStatus,
            cancellation,
            receiver,
            progress_receiver,
            progress: None,
            cancellation_requested: false,
        });
        thread::spawn(move || {
            let result = load_romm_snapshot()
                .map(|snapshot| RommOperationOutcome::Snapshot(Box::new(snapshot)));
            let _ = sender.send((generation, result));
            context.request_repaint();
        });
    }

    /// Opens the configuration dialog on whatever is actually stored.
    ///
    /// Opening it twice is impossible: the draft *is* the open flag, so a second
    /// request while one is open is a no-op rather than a second dialog.
    fn open_romm_configuration(&mut self) {
        if self.romm_config_draft.is_some() {
            return;
        }
        let draft = match self.romm_snapshot.as_deref() {
            Some(snapshot) => RommConfigDraft::from_snapshot(snapshot),
            // A source that has never been configured still needs the dialog - that
            // is the only way it ever gets configured.
            None => RommConfigDraft::blank(),
        };
        self.romm_config_draft = Some(Box::new(draft));
        self.romm_preview = None;
    }

    /// Draws the configuration dialog.
    ///
    /// Split out so the borrow of the draft is over before a request is handled -
    /// which is what lets a save or a close mutate the same state the dialog was
    /// just drawn from.
    fn show_romm_configuration(&mut self, ui: &mut egui::Ui) -> Option<ConfigDialogRequest> {
        let source_roots_result = self.gui_config.source_roots().map(Vec::from);
        let source_roots = source_roots_result.clone().unwrap_or_default();
        let busy = self
            .romm_operation
            .as_ref()
            .is_some_and(|running| running.operation.blocks_actions());
        let preview_running = self
            .romm_operation
            .as_ref()
            .is_some_and(|running| matches!(running.operation, RommOperation::Preview { .. }));
        let previous = self
            .romm_snapshot
            .as_deref()
            .map(|snapshot| snapshot.settings.clone());
        let preview = self.romm_preview.clone();

        let draft = self.romm_config_draft.as_mut()?;
        // The token file's verdict comes from the core loader, and only its verdict:
        // the contents are never read into the GUI.
        let token_state = {
            let trimmed = draft.token_path.trim();
            if trimmed.is_empty() {
                None
            } else {
                let path = PathBuf::from(trimmed);
                Some(token_field_state(
                    archivefs_core::identity_source::settings::load_token_file(Some(&path))
                        .map(|_| ()),
                    trimmed,
                ))
            }
        };
        let validation = validate_draft(draft, token_state.as_ref(), &source_roots);
        let mappings = build_mappings_view(&draft.mappings, draft.path_kind, &source_roots);
        if let Err(problem) = source_roots_result {
            widgets::banner(
                ui,
                "EmuWiz configuration unavailable",
                &format!(
                    "The previous in-memory configuration is being preserved, but this dialog \
                     cannot validate source-folder mappings: {problem}"
                ),
                widgets::StatusTone::Blocked,
            );
        }
        show_config_dialog(
            ui,
            draft,
            &crate::romm_config::ConfigDialogInputs {
                validation: &validation,
                mappings: &mappings,
                preview: preview.as_deref(),
                previous: previous.as_ref(),
                busy,
                preview_running,
            },
            &mut self.clipboard,
        )
    }

    /// The configuration dialog's fixed footer - Save and Cancel.
    ///
    /// Split from `show_romm_configuration` so the window wrapper can place it
    /// outside the body's scroll area. It re-derives the same validation the
    /// body did rather than caching it, because the body may have just changed
    /// a field this frame and a stale `can_save` would be worse than the very
    /// small cost of recomputing it.
    fn show_romm_configuration_footer(&mut self, ui: &mut egui::Ui) -> Option<ConfigDialogRequest> {
        let source_roots = self
            .gui_config
            .source_roots()
            .map(Vec::from)
            .unwrap_or_default();
        let busy = self
            .romm_operation
            .as_ref()
            .is_some_and(|running| running.operation.blocks_actions());
        let preview_running = self
            .romm_operation
            .as_ref()
            .is_some_and(|running| matches!(running.operation, RommOperation::Preview { .. }));
        let previous = self
            .romm_snapshot
            .as_deref()
            .map(|snapshot| snapshot.settings.clone());
        let preview = self.romm_preview.clone();

        let draft = self.romm_config_draft.as_mut()?;
        let token_state = {
            let trimmed = draft.token_path.trim();
            if trimmed.is_empty() {
                None
            } else {
                let path = PathBuf::from(trimmed);
                Some(token_field_state(
                    archivefs_core::identity_source::settings::load_token_file(Some(&path))
                        .map(|_| ()),
                    trimmed,
                ))
            }
        };
        let validation = validate_draft(draft, token_state.as_ref(), &source_roots);
        let mappings = build_mappings_view(&draft.mappings, draft.path_kind, &source_roots);
        crate::romm_config::show_config_dialog_footer(
            ui,
            draft,
            &crate::romm_config::ConfigDialogInputs {
                validation: &validation,
                mappings: &mappings,
                preview: preview.as_deref(),
                previous: previous.as_ref(),
                busy,
                preview_running,
            },
        )
    }

    /// Draws the existing configuration content as an actual persistent window.
    ///
    /// Previously the content was appended below the source card, outside the
    /// visible scroll position. The draft still remains the single open/closed flag;
    /// this wrapper only gives that state a visible destination.
    ///
    /// # Window shape
    ///
    /// The same arrangement the RomM record Details window uses, for the same
    /// reason: a title-bar close (`.open`), a body that scrolls within a
    /// viewport-clamped window, and a footer holding Save and Cancel that is
    /// drawn *after* the body's scroll area so it can never scroll away. The
    /// previous version had none of these - the actions were the last widgets
    /// inside the scrolling body, so at TV resolution the dialog offered no
    /// visible exit at all and Escape was the only way out.
    fn show_romm_configuration_window(
        &mut self,
        context: &egui::Context,
    ) -> Option<ConfigDialogRequest> {
        self.romm_config_draft.as_ref()?;
        let mut request = None;
        let viewport = context.input(|input| input.screen_rect().size());
        let (initial, maximum) = romm_dialog_sizes(viewport, egui::vec2(640.0, 760.0));
        // egui only reports a title-bar close by clearing this flag, so it has
        // to outlive the closure.
        let mut open = true;
        egui::Window::new("Configure RomM")
            .id(egui::Id::new("romm_configuration_dialog"))
            .collapsible(false)
            .resizable(true)
            .open(&mut open)
            .default_size(initial)
            .max_size(maximum)
            // egui keeps a constrained window fully inside the screen, which
            // is what guarantees the fixed footer stays reachable.
            .constrain(true)
            .default_pos(egui::pos2(24.0, 24.0))
            .show(context, |ui| {
                let footer_height = crate::romm_config::CONFIG_FOOTER_HEIGHT;
                // Bounded from both directions, and both bounds matter.
                //
                // `available_height` alone is not enough: with content taller
                // than the screen it is effectively unbounded, the scroll area
                // claimed all of it, and the window grew past its own maximum
                // until the fixed footer sat below the bottom of the screen.
                //
                // The window maximum alone is not enough either: sizing the
                // body from it consumed the whole content area, and the
                // separator and footer were then laid out past the window's
                // clip rect, where they were never painted at all.
                //
                // Taking the smaller of the two keeps the footer inside the
                // window *and* the window inside the viewport.
                let body_height = crate::romm_config::config_body_height(
                    ui.available_height().min(romm_window_body_cap(maximum)),
                    footer_height,
                );
                egui::ScrollArea::vertical()
                    .id_salt("romm_configuration_body")
                    .scroll_bar_visibility(
                        egui::scroll_area::ScrollBarVisibility::VisibleWhenNeeded,
                    )
                    .max_height(body_height)
                    .auto_shrink([false, false])
                    .show(ui, |ui| request = self.show_romm_configuration(ui));
                ui.separator();
                if let Some(found) = self.show_romm_configuration_footer(ui) {
                    request = Some(found);
                }
            });
        // A title-bar close and Escape are both plain "leave without writing":
        // `Close` discards the draft and performs no save, no import and no
        // request. Neither is allowed to overwrite a Save the footer just
        // produced in this same frame.
        if request.is_none()
            && (!open || context.input(|input| input.key_pressed(egui::Key::Escape)))
        {
            request = Some(ConfigDialogRequest::Close);
        }
        request
    }

    /// Opens the browsing panel on one view, or switches an open one to it.
    ///
    /// Opening it twice is impossible for the same reason the configuration dialog
    /// cannot be: the state *is* the open flag.
    fn open_romm_browse(&mut self, view: crate::romm_browse::BrowseView) {
        match self.romm_browse.as_mut() {
            Some(state) if state.view != view => {
                state.view = view;
                state.detail = None;
                state.pending_detail_id = None;
                state.detail_problem = None;
            }
            Some(_) => {}
            None => {
                self.romm_browse = Some(Box::new(crate::romm_browse::BrowseState::opened_at(view)));
            }
        }
    }

    fn close_romm_browse(&mut self) {
        self.romm_browse = None;
        self.romm_stale_progress = None;
    }

    /// Draws the RomM records browser as its own persistent window.
    ///
    /// # Why a window
    ///
    /// It used to be appended to the Sources page underneath the RomM source
    /// card. On a page already taller than the viewport that put the browser
    /// entirely below the fold, so one click on "Browse records" produced no
    /// visible change whatsoever and read as a dead button. A window appears
    /// where the user is looking, on the frame the button is pressed.
    ///
    /// Opening twice cannot duplicate it: `self.romm_browse` *is* the open
    /// flag (see `open_romm_browse`), and the window carries a fixed id, so a
    /// second click at most switches which view is shown.
    ///
    /// Nothing here changes what browsing *does*: it still reads the published
    /// identity cache only. No transport is constructed, no token is read and
    /// no request is made - that is `handle_romm_browse_request`'s business,
    /// and it is untouched.
    fn show_romm_browse_window(
        &mut self,
        context: &egui::Context,
    ) -> Option<crate::romm_browse::BrowseRequest> {
        self.romm_browse.as_ref()?;
        let busy = self
            .romm_operation
            .as_ref()
            .is_some_and(|running| running.operation.blocks_actions());
        let progress = self.romm_stale_progress;
        let viewport = context.input(|input| input.screen_rect().size());
        let (initial, maximum) = romm_dialog_sizes(viewport, egui::vec2(900.0, 780.0));
        let title = self
            .romm_browse
            .as_ref()
            .map(|state| state.view.title())
            .unwrap_or("RomM records");
        let mut request = None;
        let mut open = true;
        egui::Window::new(title)
            .id(egui::Id::new("romm_browse_window"))
            .collapsible(false)
            .resizable(true)
            .open(&mut open)
            .default_size(initial)
            .max_size(maximum)
            // egui keeps a constrained window fully inside the screen, which
            // is what guarantees the fixed footer stays reachable.
            .constrain(true)
            .default_pos(egui::pos2(24.0, 24.0))
            .show(context, |ui| {
                let footer_height = crate::romm_browse::BROWSE_FOOTER_HEIGHT;
                // See `show_romm_configuration_window` for why both bounds
                // are needed. The records list is the case that proves it:
                // its content is far taller than any screen.
                let body_height = crate::romm_config::config_body_height(
                    ui.available_height().min(romm_window_body_cap(maximum)),
                    footer_height,
                );
                egui::ScrollArea::vertical()
                    .id_salt("romm_browse_body")
                    .scroll_bar_visibility(
                        egui::scroll_area::ScrollBarVisibility::VisibleWhenNeeded,
                    )
                    .max_height(body_height)
                    .auto_shrink([false, false])
                    .show(ui, |ui| {
                        if let Some(found) = self.romm_browse.as_mut().and_then(|state| {
                            crate::romm_browse::show_browse_panel(
                                ui,
                                state,
                                busy,
                                progress.as_ref(),
                            )
                        }) {
                            request = Some(found);
                        }
                    });
                ui.separator();
                if let Some(found) = crate::romm_browse::show_browse_panel_footer(ui) {
                    request = Some(found);
                }
            });
        // Escape belongs to the record Details window whenever one is open -
        // it closes that, not the browser underneath it - so the browser only
        // consumes Escape when nothing is layered on top.
        let detail_open = self
            .romm_browse
            .as_ref()
            .is_some_and(|state| state.detail.is_some());
        if request.is_none()
            && (!open
                || (!detail_open && context.input(|input| input.key_pressed(egui::Key::Escape))))
        {
            request = Some(crate::romm_browse::BrowseRequest::Close);
        }
        request
    }

    /// Routes one request from the browsing panel.
    fn handle_romm_browse_request(
        &mut self,
        context: &egui::Context,
        request: crate::romm_browse::BrowseRequest,
    ) {
        use crate::romm_browse::BrowseRequest;
        match request {
            BrowseRequest::LoadRecords { offset, limit } => {
                if let Some(state) = self.romm_browse.as_mut() {
                    state.invalidate_detail_request();
                }
                let filters = self
                    .romm_browse
                    .as_ref()
                    .map(|state| state.filters.clone())
                    .unwrap_or_default();
                self.start_romm_operation(
                    context.clone(),
                    RommOperation::LoadRecords {
                        filters: Box::new(filters),
                        offset,
                        limit,
                    },
                );
            }
            BrowseRequest::OpenDetail { romm_game_id } => {
                let requested_id = romm_game_id.clone();
                if self.start_romm_operation(
                    context.clone(),
                    RommOperation::LoadRecordDetail { romm_game_id },
                ) && let Some(state) = self.romm_browse.as_mut()
                {
                    state.begin_detail(requested_id);
                }
            }
            BrowseRequest::CloseDetail => {
                if let Some(state) = self.romm_browse.as_mut() {
                    state.detail = None;
                    state.pending_detail_id = None;
                    state.detail_problem = None;
                    state.detail_cover = crate::romm_game::CoverState::Idle;
                    state.detail_cover_texture = None;
                    state.detail_cover_key = None;
                }
            }
            BrowseRequest::LoadDetailCover {
                local_path,
                romm_game_id,
            } => {
                if self.start_romm_operation(
                    context.clone(),
                    RommOperation::LoadCover {
                        local_path,
                        romm_game_id,
                    },
                ) && let Some(state) = self.romm_browse.as_mut()
                {
                    state.detail_cover = crate::romm_game::CoverState::Loading;
                }
            }
            BrowseRequest::LoadConflicts { offset } => {
                self.start_romm_operation(context.clone(), RommOperation::LoadConflicts { offset });
            }
            BrowseRequest::RunStaleSummary => {
                self.romm_stale_progress = None;
                self.start_romm_operation(context.clone(), RommOperation::StaleSummary);
            }
            BrowseRequest::Cancel => self.cancel_romm_operation(),
            BrowseRequest::Switch(view) => self.open_romm_browse(view),
            BrowseRequest::Close => self.close_romm_browse(),
        }
    }

    /// What EmuWiz itself says the selected archive's platform is.
    ///
    /// Read from the catalogue the GUI already holds. `manual` is the whole point: it
    /// makes the assignment count as verified local evidence, which is what stops a
    /// disagreeing RomM record from being presented as a correction.
    fn romm_local_platform(&self, path: &Path) -> crate::romm_game::LocalPlatformClaim {
        let persisted = self.database_state.snapshot().and_then(|snapshot| {
            snapshot
                .archives
                .iter()
                .find(|archive| archive.absolute_path == path)
        });
        match persisted {
            Some(archive) => crate::romm_game::LocalPlatformClaim {
                platform: archive.platform.clone(),
                manual: archive.platform_source.as_deref() == Some(MANUAL_PLATFORM_SOURCE),
            },
            None => crate::romm_game::LocalPlatformClaim::default(),
        }
    }

    /// Draws the selected game's RomM panel, and follows the selection.
    fn show_romm_game_panel(&mut self, context: &egui::Context, ui: &mut egui::Ui) {
        // Following the selection discards the previous game's panel, cover and
        // verification, but starts nothing: a lookup is a button press.
        self.romm_game
            .focus(self.archive_context.focused.as_deref());
        let running = self
            .romm_operation
            .as_ref()
            .map(|running| &running.operation);
        let busy = running.is_some_and(RommOperation::blocks_actions);
        let busy_reason = running.map(|operation| operation.label());
        let cache_present = self
            .romm_snapshot
            .as_deref()
            .is_some_and(|snapshot| snapshot.status.records_imported > 0);
        let hash_progress = self.romm_hash_progress.clone();
        let request = crate::romm_game::show_game_identity_panel(
            ui,
            &mut self.romm_game,
            &crate::romm_game::GamePanelInputs {
                busy,
                busy_reason,
                hash_progress: hash_progress.as_ref(),
                cache_present,
            },
        );
        if let Some(request) = request {
            self.handle_romm_game_request(context, request);
        }
    }

    fn handle_romm_game_request(
        &mut self,
        context: &egui::Context,
        request: crate::romm_game::GamePanelRequest,
    ) {
        use crate::romm_game::GamePanelRequest;

        let Some(local_path) = self.romm_game.local_path.clone() else {
            return;
        };
        let local_platform = Box::new(self.romm_local_platform(&local_path));
        match request {
            GamePanelRequest::Resolve => {
                self.start_romm_operation(
                    context.clone(),
                    RommOperation::ResolveGame {
                        local_path,
                        local_platform,
                        chosen_game_id: self.romm_game.chosen_game_id.clone(),
                    },
                );
            }
            GamePanelRequest::Choose { romm_game_id } => {
                // A choice is recorded and then re-resolved, so the verdict on screen
                // is the one that record actually earns rather than a relabelling.
                self.romm_game.chosen_game_id = Some(romm_game_id.clone());
                self.romm_game.verification = None;
                self.romm_game.cover = crate::romm_game::CoverState::Idle;
                self.romm_game.cover_texture = None;
                self.romm_game.cover_key = None;
                self.start_romm_operation(
                    context.clone(),
                    RommOperation::ResolveGame {
                        local_path,
                        local_platform,
                        chosen_game_id: Some(romm_game_id),
                    },
                );
            }
            GamePanelRequest::Verify { romm_game_id } => {
                self.start_romm_operation(
                    context.clone(),
                    RommOperation::VerifyLocalFile {
                        local_path,
                        romm_game_id,
                        local_platform,
                        chosen_game_id: self.romm_game.chosen_game_id.clone(),
                    },
                );
            }
            GamePanelRequest::LoadCover { romm_game_id } => {
                if self.start_romm_operation(
                    context.clone(),
                    RommOperation::LoadCover {
                        local_path,
                        romm_game_id,
                    },
                ) {
                    self.romm_game.cover = crate::romm_game::CoverState::Loading;
                }
            }
            GamePanelRequest::Cancel => self.cancel_romm_operation(),
            GamePanelRequest::Close => {
                // Closed for this selection only. Choosing a different archive brings
                // it back, which is what someone expects from a per-game panel.
                self.romm_game.dismissed = true;
            }
            GamePanelRequest::Reopen => {
                self.romm_game.dismissed = false;
            }
        }
    }

    fn close_romm_configuration(&mut self) {
        self.romm_config_draft = None;
        self.romm_preview = None;
    }

    /// Routes one request from the configuration dialog.
    fn handle_romm_config_request(
        &mut self,
        context: &egui::Context,
        request: ConfigDialogRequest,
    ) {
        match request {
            ConfigDialogRequest::Save(settings) => {
                // Declined while anything else runs, so a save cannot race an import.
                if self.start_romm_operation(
                    context.clone(),
                    RommOperation::SaveConfiguration(settings),
                ) {
                    // The dialog stays open until the save succeeds, so a refused
                    // save does not lose what was typed.
                }
            }
            ConfigDialogRequest::Preview { limit } => {
                self.start_romm_operation(context.clone(), RommOperation::Preview { limit });
            }
            ConfigDialogRequest::CancelPreview => self.cancel_romm_operation(),
            ConfigDialogRequest::Close => self.close_romm_configuration(),
        }
    }

    fn poll_bsfree_operation(&mut self, context: &egui::Context) {
        let result = self.bsfree_operation.as_ref().and_then(|running| {
            running
                .receiver
                .try_recv()
                .ok()
                .map(|result| (running.operation.clone(), result))
        });
        let Some((operation, result)) = result else {
            return;
        };
        self.bsfree_operation = None;
        match result {
            Ok(BsFreeOperationResult::Status(status)) => {
                self.bsfree_manager = BsFreeManagerState::Ready(status);
            }
            Ok(BsFreeOperationResult::Removed) => {
                self.bsfree_manager = BsFreeManagerState::NotLoaded;
                self.bsfree_ui = BsFreeGuiState::default();
                self.feedback = Some(ActionFeedback {
                    succeeded: true,
                    message: "Removed EmuWiz's local BSFree source copy only.".to_string(),
                    cleanup: None,
                    warning: None,
                    more_information: None,
                });
            }
            Ok(BsFreeOperationResult::Search(result)) => {
                self.bsfree_ui.search_result = Some(Ok(result));
                self.bsfree_ui.selected_game = None;
                self.bsfree_ui.cheats = None;
            }
            Ok(BsFreeOperationResult::Game(game, cheats)) => {
                self.bsfree_ui.selected_game = Some(game);
                self.bsfree_ui.cheats = Some(Ok(cheats));
            }
            Err(message) => match operation {
                BsFreeOperation::Search(_) => self.bsfree_ui.search_result = Some(Err(message)),
                BsFreeOperation::LoadGame { .. } => self.bsfree_ui.cheats = Some(Err(message)),
                BsFreeOperation::LoadStatus => {
                    self.bsfree_manager = BsFreeManagerState::Failed(message)
                }
                _ => {
                    self.feedback = Some(ActionFeedback {
                        succeeded: false,
                        message,
                        cleanup: None,
                        warning: None,
                        more_information: None,
                    });
                    self.start_bsfree_operation(context.clone(), BsFreeOperation::LoadStatus);
                }
            },
        }
    }

    fn start_catalogue_status_load(&mut self, context: egui::Context) {
        if matches!(self.catalogue_manager, CatalogueManagerState::Loading(_)) {
            return;
        }
        let (sender, receiver) = mpsc::channel();
        self.catalogue_manager = CatalogueManagerState::Loading(receiver);
        thread::spawn(move || {
            let result = default_cheat_source_cache_root()
                .and_then(|root| list_retroarch_cheat_sources(&root));
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    fn start_catalogue_retrieval(&mut self, context: egui::Context) {
        if self.catalogue_retrieval.is_some() {
            return;
        }
        let Some(review) = self.catalogue_review.take() else {
            return;
        };
        self.catalogue_generation = self.catalogue_generation.wrapping_add(1);
        let generation = self.catalogue_generation;
        let source_id = review.source_id;
        let force_refresh = review.kind == CatalogueRetrievalKind::Update;
        let cancellation = CheatSourceCancellation::default();
        let worker_cancellation = cancellation.clone();
        let (sender, receiver) = mpsc::channel();
        let (progress_sender, progress_receiver) = mpsc::channel();
        self.history.record(HistoryEntry::new(
            ActivityAction::CheatSourceRetrieval,
            None,
            ActivityOutcome::Started,
            format!(
                "RetroArch catalogue {review_kind} started for '{source_id}'.",
                review_kind = if force_refresh { "update" } else { "download" }
            ),
        ));
        self.catalogue_retrieval = Some(RunningCatalogueRetrieval {
            generation,
            source_id: source_id.clone(),
            cancellation,
            receiver,
            progress_receiver,
            progress: None,
            cancellation_requested: false,
        });
        let progress_context = context.clone();
        let progress = CheatSourceProgressReporter::new(move |event| {
            let _ = progress_sender.send(event);
            progress_context.request_repaint();
        });
        thread::spawn(move || {
            let result = default_cheat_source_cache_root().and_then(|cache_root| {
                fetch_retroarch_cheat_source(
                    &source_id,
                    &CheatSourceFetchOptions {
                        cache_root,
                        force_refresh,
                        offline: false,
                        expected_sha256: None,
                        max_download_bytes: None,
                        cancellation: Some(worker_cancellation),
                        progress: Some(progress),
                    },
                    &HttpsCheatSourceTransport::new(),
                )
            });
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    /// The single dispatch point for `CatalogueManagerAction` - shared by
    /// every page that renders `show_retroarch_catalogue_manager` (Sources,
    /// and now Cheats & Mods) so the Review-then-Confirm two-step and the
    /// "no automatic network access" guarantee it enforces cannot drift
    /// between call sites.
    fn handle_catalogue_manager_action(
        &mut self,
        context: &egui::Context,
        action: CatalogueManagerAction,
    ) {
        match action {
            CatalogueManagerAction::Refresh => {
                self.start_catalogue_status_load(context.clone());
            }
            CatalogueManagerAction::Review { source_id, kind } => {
                self.catalogue_review = Some(CatalogueReview { source_id, kind });
            }
            CatalogueManagerAction::Confirm => {
                self.start_catalogue_retrieval(context.clone());
            }
            CatalogueManagerAction::CancelReview => {
                self.catalogue_review = None;
            }
            CatalogueManagerAction::CancelRunning => {
                if let Some(running) = self.catalogue_retrieval.as_mut() {
                    running.cancellation.cancel();
                    running.cancellation_requested = true;
                }
            }
        }
    }

    fn poll_catalogue_manager(&mut self, context: &egui::Context) {
        if let CatalogueManagerState::Loading(receiver) = &self.catalogue_manager {
            match receiver.try_recv() {
                Ok(Ok(list)) => self.catalogue_manager = CatalogueManagerState::Ready(list),
                Ok(Err(error)) => self.catalogue_manager = CatalogueManagerState::Failed(error),
                Err(TryRecvError::Empty) => {}
                Err(TryRecvError::Disconnected) => {
                    self.catalogue_manager = CatalogueManagerState::Failed(CheatSourceError {
                        schema_version:
                            archivefs_core::patch_manager::CHEAT_SOURCE_RESULT_SCHEMA_VERSION,
                        stage: archivefs_core::patch_manager::CheatSourceErrorStage::Cache,
                        code: "status_worker_stopped".to_string(),
                        message: "catalogue status worker stopped unexpectedly".to_string(),
                        retry_after_seconds: None,
                    });
                }
            }
        }
        if let Some(running) = self.catalogue_retrieval.as_mut() {
            for progress in running.progress_receiver.try_iter() {
                running.progress = Some(progress);
            }
        }
        let result = self.catalogue_retrieval.as_ref().and_then(|running| {
            running
                .receiver
                .try_recv()
                .ok()
                .map(|result| (running.generation, running.source_id.clone(), result))
        });
        let Some((generation, source_id, result)) = result else {
            return;
        };
        self.catalogue_retrieval = None;
        if generation != self.catalogue_generation {
            return;
        }
        match &result {
            Ok(fetch) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatSourceRetrieval,
                    None,
                    ActivityOutcome::Completed,
                    format!(
                        "RetroArch catalogue '{}': revision resolved to {}.",
                        source_id, fetch.manifest.resolved_revision
                    ),
                ));
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatSourceRetrieval,
                    None,
                    ActivityOutcome::Completed,
                    format!(
                        "RetroArch catalogue '{}': download and verification completed ({} bytes, {} manifest files).",
                        source_id,
                        fetch.manifest.downloaded_bytes,
                        fetch.manifest.files.len()
                    ),
                ));
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatSourceRetrieval,
                    None,
                    ActivityOutcome::Completed,
                    format!(
                        "RetroArch catalogue '{}' activated at revision {} ({} files verified; {} indexed, {} excluded).",
                        source_id,
                        fetch.manifest.resolved_revision,
                        fetch.manifest.files.len(),
                        fetch.manifest.indexed_file_count,
                        fetch.manifest.malformed_cheat_count
                            + fetch.manifest.excluded_unsupported_count
                            + fetch.manifest.excluded_path_encoding_count
                    ),
                ));
                if let Some(workflow) = self.cheat_workflow.as_mut() {
                    workflow.source_fetch = CheatStepResource::Ready(fetch.clone());
                    workflow.source_list = CheatStepResource::NotLoaded;
                    clear_cheat_candidate_state(workflow);
                }
            }
            Err(error) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatSourceRetrieval,
                    None,
                    if error.code == "cancelled" {
                        ActivityOutcome::Skipped
                    } else {
                        ActivityOutcome::Failed
                    },
                    format!(
                        "RetroArch catalogue '{source_id}': {error}. Existing snapshot retained."
                    ),
                ));
            }
        }
        self.catalogue_last_result = Some(result);
        self.catalogue_manager = CatalogueManagerState::NotLoaded;
        self.start_catalogue_status_load(context.clone());
    }

    fn start_dolphin_catalogue_status_load(&mut self, context: egui::Context) {
        if matches!(
            self.dolphin_catalogue_manager,
            DolphinCatalogueManagerState::Loading(_)
        ) {
            return;
        }
        let (sender, receiver) = mpsc::channel();
        self.dolphin_catalogue_manager = DolphinCatalogueManagerState::Loading(receiver);
        thread::spawn(move || {
            let result = default_dolphin_catalogue_cache_root().and_then(|root| {
                let catalogue = match load_dolphin_catalogue(&root)? {
                    DolphinCatalogueLoad::NotInstalled => None,
                    DolphinCatalogueLoad::Ready(catalogue) => Some(*catalogue),
                };
                let last_check_unix_seconds =
                    load_dolphin_catalogue_update_state(&root)?.last_check_unix_seconds;
                Ok(DolphinCatalogueStatusSnapshot {
                    catalogue,
                    last_check_unix_seconds,
                })
            });
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    fn start_dolphin_catalogue_retrieval(&mut self, context: egui::Context) {
        if self.dolphin_catalogue_retrieval.is_some() {
            return;
        }
        let Some(kind) = self.dolphin_catalogue_review.take() else {
            return;
        };
        self.dolphin_catalogue_generation = self.dolphin_catalogue_generation.wrapping_add(1);
        let generation = self.dolphin_catalogue_generation;
        let cancellation = CheatSourceCancellation::default();
        let worker_cancellation = cancellation.clone();
        let (sender, receiver) = mpsc::channel();
        let (progress_sender, progress_receiver) = mpsc::channel();
        self.history.record(HistoryEntry::new(
            ActivityAction::DolphinCatalogueRetrieval,
            None,
            ActivityOutcome::Started,
            format!(
                "Dolphin cheat catalogue {} started.",
                dolphin_catalogue_retrieval_kind_verb(kind)
            ),
        ));
        self.dolphin_catalogue_retrieval = Some(RunningDolphinCatalogueRetrieval {
            generation,
            kind,
            cancellation,
            receiver,
            progress_receiver,
            progress: None,
            cancellation_requested: false,
        });
        let progress_context = context.clone();
        let progress = CheatSourceProgressReporter::new(move |event| {
            let _ = progress_sender.send(event);
            progress_context.request_repaint();
        });
        thread::spawn(move || {
            let result = default_dolphin_catalogue_cache_root().and_then(|cache_root| {
                let options = DolphinCatalogueFetchOptions {
                    cache_root,
                    cancellation: Some(worker_cancellation),
                    progress: Some(progress),
                };
                let transport = HttpsCheatSourceTransport::new();
                match kind {
                    DolphinCatalogueRetrievalKind::Download
                    | DolphinCatalogueRetrievalKind::Update => {
                        fetch_dolphin_catalogue_with_transport(&options, &transport)
                    }
                    DolphinCatalogueRetrievalKind::Rebuild => {
                        rebuild_dolphin_catalogue_index_with_transport(&options, &transport)
                    }
                }
            });
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    fn start_dolphin_catalogue_update_check(&mut self, context: egui::Context) {
        if self.dolphin_catalogue_update_check.is_some() {
            return;
        }
        let (sender, receiver) = mpsc::channel();
        self.dolphin_catalogue_update_check = Some(receiver);
        thread::spawn(move || {
            let result = default_dolphin_catalogue_cache_root().and_then(|root| {
                check_dolphin_catalogue_update_with_transport(
                    &root,
                    &HttpsCheatSourceTransport::new(),
                )
            });
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    /// The single dispatch point for `DolphinCatalogueManagerAction` -
    /// mirrors `handle_catalogue_manager_action`'s Review-then-Confirm
    /// two-step and "no automatic network access" guarantee.
    fn handle_dolphin_catalogue_manager_action(
        &mut self,
        context: &egui::Context,
        action: DolphinCatalogueManagerAction,
    ) {
        match action {
            DolphinCatalogueManagerAction::Refresh => {
                self.start_dolphin_catalogue_status_load(context.clone());
            }
            DolphinCatalogueManagerAction::Review(kind) => {
                self.dolphin_catalogue_review = Some(kind);
            }
            DolphinCatalogueManagerAction::Confirm => {
                self.start_dolphin_catalogue_retrieval(context.clone());
            }
            DolphinCatalogueManagerAction::CancelReview => {
                self.dolphin_catalogue_review = None;
            }
            DolphinCatalogueManagerAction::CancelRunning => {
                if let Some(running) = self.dolphin_catalogue_retrieval.as_mut() {
                    running.cancellation.cancel();
                    running.cancellation_requested = true;
                }
            }
            DolphinCatalogueManagerAction::CheckForUpdates => {
                self.start_dolphin_catalogue_update_check(context.clone());
            }
            DolphinCatalogueManagerAction::RequestRemove => {
                self.dolphin_catalogue_remove_confirm = true;
            }
            DolphinCatalogueManagerAction::CancelRemove => {
                self.dolphin_catalogue_remove_confirm = false;
            }
            DolphinCatalogueManagerAction::ConfirmRemove => {
                self.dolphin_catalogue_remove_confirm = false;
                let outcome = default_dolphin_catalogue_cache_root()
                    .and_then(|root| remove_dolphin_catalogue(&root));
                self.history.record(HistoryEntry::new(
                    ActivityAction::DolphinCatalogueRetrieval,
                    None,
                    match &outcome {
                        Ok(()) => ActivityOutcome::Completed,
                        Err(_) => ActivityOutcome::Failed,
                    },
                    match &outcome {
                        Ok(()) => {
                            "Dolphin cheat catalogue removed. Installed Dolphin codes and profiles were not touched."
                                .to_string()
                        }
                        Err(error) => format!("Dolphin cheat catalogue removal failed: {error}"),
                    },
                ));
                self.dolphin_catalogue_update_available = None;
                self.start_dolphin_catalogue_status_load(context.clone());
            }
        }
    }

    fn poll_dolphin_catalogue_manager(&mut self, context: &egui::Context) {
        if let DolphinCatalogueManagerState::Loading(receiver) = &self.dolphin_catalogue_manager {
            match receiver.try_recv() {
                Ok(Ok(snapshot)) => {
                    self.dolphin_catalogue_manager =
                        DolphinCatalogueManagerState::Ready(Box::new(snapshot));
                }
                Ok(Err(error)) => {
                    self.dolphin_catalogue_manager = DolphinCatalogueManagerState::Failed(error);
                }
                Err(TryRecvError::Empty) => {}
                Err(TryRecvError::Disconnected) => {
                    self.dolphin_catalogue_manager =
                        DolphinCatalogueManagerState::Failed(DolphinCatalogueError {
                            kind: DolphinCatalogueErrorKind::CacheUnavailable,
                            detail: "catalogue status worker stopped unexpectedly".to_string(),
                        });
                }
            }
        }
        if let Some(receiver) = &self.dolphin_catalogue_update_check {
            match receiver.try_recv() {
                Ok(result) => {
                    self.dolphin_catalogue_update_available =
                        Some(result.as_ref().is_ok_and(|check| check.update_available));
                    self.dolphin_catalogue_update_check = None;
                    self.start_dolphin_catalogue_status_load(context.clone());
                }
                Err(TryRecvError::Empty) => {}
                Err(TryRecvError::Disconnected) => {
                    self.dolphin_catalogue_update_available = Some(false);
                    self.dolphin_catalogue_update_check = None;
                }
            }
        }
        if let Some(running) = self.dolphin_catalogue_retrieval.as_mut() {
            for progress in running.progress_receiver.try_iter() {
                running.progress = Some(progress);
            }
        }
        let result = self
            .dolphin_catalogue_retrieval
            .as_ref()
            .and_then(|running| {
                running
                    .receiver
                    .try_recv()
                    .ok()
                    .map(|result| (running.generation, result))
            });
        let Some((generation, result)) = result else {
            return;
        };
        self.dolphin_catalogue_retrieval = None;
        if generation != self.dolphin_catalogue_generation {
            return;
        }
        match &result {
            Ok(fetch) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::DolphinCatalogueRetrieval,
                    None,
                    ActivityOutcome::Completed,
                    format!(
                        "Dolphin cheat catalogue activated at commit {}: {} games, {} usable Gecko codes ({} GameSettings files inspected, {} skipped).",
                        fetch.catalogue.metadata.resolved_commit,
                        fetch.catalogue.games.len(),
                        fetch.catalogue.metadata.total_usable_gecko_entries,
                        fetch.catalogue.metadata.game_settings_files_inspected,
                        fetch.catalogue.metadata.malformed_or_skipped_files
                    ),
                ));
                // A freshly downloaded/updated catalogue may now answer a
                // lookup that previously came up empty; let the next
                // selection re-check local sources instead of keeping a
                // stale "nothing found" verdict pinned from before this
                // catalogue existed.
                if let Some(workflow) = self.cheat_workflow.as_mut()
                    && workflow.adapter == CheatEmulatorAdapter::Dolphin
                    && matches!(workflow.dolphin_provider, CheatStepResource::NotLoaded)
                {
                    workflow.dolphin_local_lookup = DolphinLocalLookupState::NotAttempted;
                }
            }
            Err(error) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::DolphinCatalogueRetrieval,
                    None,
                    if error.kind == DolphinCatalogueErrorKind::Cancelled {
                        ActivityOutcome::Skipped
                    } else {
                        ActivityOutcome::Failed
                    },
                    format!("Dolphin cheat catalogue retrieval failed: {error}. Existing catalogue, if any, retained."),
                ));
            }
        }
        self.dolphin_catalogue_last_result = Some(result);
        self.dolphin_catalogue_update_available = None;
        self.dolphin_catalogue_manager = DolphinCatalogueManagerState::NotLoaded;
        self.start_dolphin_catalogue_status_load(context.clone());
    }

    /// Whether a new Library Views action may start - the same "one
    /// writer at a time" convention `source_action_available` uses
    /// (Preview/Apply reads the same database a scan writes to).
    fn library_view_action_available(&self) -> bool {
        self.library_view_action.is_none()
            && self.source_action.is_none()
            && self.alias_action.is_none()
            && self.platform_action.is_none()
            && self.bulk_platform_action.is_none()
            && self.missing_removal.is_none()
            && !self.database_state.is_loading()
    }

    /// Re-reads the configured Library Views list from disk - a cheap,
    /// synchronous, read-only file read (the same kind
    /// `source_action_log_category`'s doc comment already calls out for
    /// config reads of this size), never a background thread. A read
    /// failure is treated as "no views configured" here rather than
    /// surfaced as an error, matching `load_library_view_configs_default`'s
    /// own "missing file is not an error" contract - the only way this can
    /// actually fail once the file exists is a corrupt/foreign-format
    /// file, which the next successful Add/Edit save overwrites anyway.
    fn reload_library_views(&mut self) {
        self.library_views = load_library_view_configs_default().unwrap_or_default();
    }

    fn start_library_view_action(&mut self, context: egui::Context, action: LibraryViewAction) {
        if !self.library_view_action_available() {
            return;
        }
        let (sender, receiver) = mpsc::channel();
        self.history.record(HistoryEntry::new(
            library_view_action_log_category(&action),
            None,
            ActivityOutcome::Started,
            library_view_action_started_message(&action),
        ));
        self.library_view_action = Some(RunningLibraryViewAction {
            action: action.clone(),
            receiver,
        });
        thread::spawn(move || {
            let result = run_library_view_action(&action);
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    /// Mirrors `poll_source_action`: refreshes `library_views` from disk on
    /// every successful outcome (Add/Edit/SetEnabled/Remove all mutate the
    /// configured list; Preview/Apply/Repair don't, but reloading anyway is
    /// harmless and keeps this one code path for all six), and updates
    /// `library_view_last_plan` for the two outcomes that produce or
    /// invalidate a plan.
    fn poll_library_view_action(&mut self, context: &egui::Context) {
        let result = self.library_view_action.as_ref().and_then(|running| {
            running
                .receiver
                .try_recv()
                .ok()
                .map(|result| (running.action.clone(), result))
        });
        let Some((action, result)) = result else {
            return;
        };
        self.library_view_action = None;
        let log_category = library_view_action_log_category(&action);
        match result {
            Ok(outcome) => {
                let message = library_view_action_success_message(&outcome);
                self.history.record(HistoryEntry::new(
                    log_category,
                    None,
                    ActivityOutcome::Completed,
                    message.clone(),
                ));
                self.feedback = Some(ActionFeedback {
                    succeeded: true,
                    message,
                    cleanup: None,
                    warning: None,
                    more_information: None,
                });
                match &outcome {
                    LibraryViewActionOutcome::Added(_) => {
                        self.library_view_form_dialog = None;
                    }
                    LibraryViewActionOutcome::Edited(view) => {
                        self.library_view_form_dialog = None;
                        // The edited view's own filters may have changed -
                        // any previously computed plan for it no longer
                        // reflects the current configuration truthfully.
                        if self
                            .library_view_last_plan
                            .as_ref()
                            .is_some_and(|(previous, _)| previous.id == view.id)
                        {
                            self.library_view_last_plan = None;
                        }
                    }
                    LibraryViewActionOutcome::Previewed { view, plan } => {
                        self.library_view_last_plan = Some((view.clone(), plan.clone()));
                    }
                    LibraryViewActionOutcome::Applied { view, .. }
                    | LibraryViewActionOutcome::Repaired { view, .. } => {
                        // Apply/Repair change what is actually on disk -
                        // the previous plan's Create/Repair/Remove counts
                        // no longer describe reality, even though the
                        // view itself is unchanged.
                        if self
                            .library_view_last_plan
                            .as_ref()
                            .is_some_and(|(previous, _)| previous.id == view.id)
                        {
                            self.library_view_last_plan = None;
                        }
                    }
                    LibraryViewActionOutcome::Removed { view, .. } => {
                        self.library_view_remove_dialog = None;
                        if self
                            .library_view_last_plan
                            .as_ref()
                            .is_some_and(|(previous, _)| previous.id == view.id)
                        {
                            self.library_view_last_plan = None;
                        }
                    }
                    LibraryViewActionOutcome::SetEnabled(_) => {}
                }
                self.reload_library_views();
            }
            Err(message) => {
                self.history.record(HistoryEntry::new(
                    log_category,
                    None,
                    ActivityOutcome::Failed,
                    message.clone(),
                ));
                self.feedback = Some(ActionFeedback {
                    succeeded: false,
                    message,
                    cleanup: None,
                    warning: None,
                    more_information: None,
                });
                // Deliberately does not clear `library_view_form_dialog`/
                // `library_view_remove_dialog` on failure - exactly like
                // `poll_source_action`, a failed Add/Edit/Remove should
                // leave the dialog open with its input intact.
            }
        }
        context.request_repaint();
    }

    fn missing_removal_action_available(&self) -> bool {
        self.missing_removal.is_none()
            && self.platform_action.is_none()
            && self.bulk_platform_action.is_none()
            && self.alias_action.is_none()
            && self.source_action.is_none()
            && self.library_view_action.is_none()
            && matches!(self.database_state, DatabaseState::Ready { .. })
    }

    fn missing_removal_unavailable_reason(&self) -> Option<String> {
        match &self.database_state {
            DatabaseState::Loading { .. } => Some(
                "Catalogue is still loading. Removal will be available when loading completes."
                    .to_string(),
            ),
            DatabaseState::Outdated { .. } => Some(
                "Catalogue data needs to be refreshed before stale entries can be removed."
                    .to_string(),
            ),
            DatabaseState::Error { message, .. } => Some(message.clone()),
            DatabaseState::NotCreated { .. } => Some(
                "Catalogue is not available yet. Create or load the catalogue before removing stale entries."
                    .to_string(),
            ),
            DatabaseState::Ready { .. } => {
                if self.missing_removal.is_some()
                    || self.platform_action.is_some()
                    || self.bulk_platform_action.is_some()
                    || self.alias_action.is_some()
                    || self.source_action.is_some()
                    || self.library_view_action.is_some()
                {
                    Some("Another catalogue operation is currently running.".to_string())
                } else {
                    None
                }
            }
        }
    }

    fn start_missing_removal(&mut self, context: egui::Context, archive_paths: Vec<PathBuf>) {
        if !self.missing_removal_action_available() || archive_paths.is_empty() {
            return;
        }
        let requested_paths = archive_paths.len();
        let (sender, receiver) = mpsc::channel();
        self.missing_removal = Some(RunningMissingRemoval {
            requested_paths,
            receiver,
        });
        thread::spawn(move || {
            let result = apply_missing_removal(&archive_paths).map_err(|error| error.to_string());
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    fn poll_missing_removal(&mut self, context: &egui::Context) {
        let result = self.missing_removal.as_ref().and_then(|running| {
            running
                .receiver
                .try_recv()
                .ok()
                .map(|result| (running.requested_paths, result))
        });
        let Some((requested_paths, result)) = result else {
            return;
        };
        self.missing_removal = None;
        match result {
            Ok(result) => {
                let message = format!(
                    "Removed {} missing catalogue entr{}. No archive files were deleted.",
                    result.removed,
                    if result.removed == 1 { "y" } else { "ies" }
                );
                self.history.record(HistoryEntry::new(
                    ActivityAction::CatalogueCleanup,
                    None,
                    ActivityOutcome::Completed,
                    message.clone(),
                ));
                self.feedback = Some(ActionFeedback {
                    succeeded: true,
                    message,
                    cleanup: None,
                    warning: None,
                    more_information: None,
                });
                self.start_database_action(context.clone(), false);
            }
            Err(message) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CatalogueCleanup,
                    None,
                    ActivityOutcome::Failed,
                    format!(
                        "Could not remove {requested_paths} selected missing catalogue entr{}: {message}",
                        if requested_paths == 1 { "y" } else { "ies" }
                    ),
                ));
                self.feedback = Some(ActionFeedback {
                    succeeded: false,
                    message,
                    cleanup: None,
                    warning: None,
                    more_information: None,
                });
            }
        }
    }

    fn start_operation(
        &mut self,
        context: egui::Context,
        action: ArchiveAction,
        archive_path: PathBuf,
        cleanup_after_unmount: bool,
    ) -> bool {
        self.start_operation_with_worker(
            context,
            action,
            archive_path,
            cleanup_after_unmount,
            |action, archive_path, cleanup_after_unmount, progress_sender| {
                perform_archive_action(
                    action,
                    &archive_path,
                    cleanup_after_unmount,
                    progress_sender,
                )
            },
        )
    }

    fn start_operation_with_worker<F>(
        &mut self,
        context: egui::Context,
        action: ArchiveAction,
        archive_path: PathBuf,
        cleanup_after_unmount: bool,
        worker: F,
    ) -> bool
    where
        F: FnOnce(ArchiveAction, PathBuf, bool, mpsc::Sender<OperationProgress>) -> OperationResult
            + Send
            + 'static,
    {
        if self.is_busy() {
            let message = "Another archive operation is already running.".to_string();
            self.feedback = Some(ActionFeedback {
                succeeded: false,
                message: message.clone(),
                cleanup: None,
                warning: None,
                more_information: None,
            });
            self.history.record(HistoryEntry::new(
                ActivityAction::from(action),
                Some(archive_path),
                ActivityOutcome::Rejected,
                message,
            ));
            return false;
        }

        let (sender, receiver) = mpsc::channel();
        let (progress_sender, progress_receiver) = mpsc::channel();
        self.confirm_mount_all = None;
        self.confirm_unmount_all = None;
        self.confirm_unmount_selected = None;
        self.focus_mount_all_cancel = false;
        self.confirm_unmount = None;
        self.confirm_lazy_unmount = None;
        self.confirm_lazy_unmount_final = None;
        self.focus_lazy_cancel = false;
        self.focus_final_lazy_cancel = false;
        self.feedback = None;
        self.history.record(HistoryEntry::new(
            ActivityAction::from(action),
            Some(archive_path.clone()),
            ActivityOutcome::Started,
            match action {
                ArchiveAction::Mount => "Mount started.",
                ArchiveAction::Unmount => "Unmount started.",
                ArchiveAction::LazyUnmount => "Lazy unmount started.",
                ArchiveAction::Remount => "Remount started.",
            },
        ));
        self.operation = Some(RunningOperation {
            action,
            archive_path: archive_path.clone(),
            receiver,
            progress_receiver,
        });
        thread::spawn(move || {
            let result = worker(action, archive_path, cleanup_after_unmount, progress_sender);
            let _ = sender.send(result);
            context.request_repaint();
        });
        true
    }

    fn record_pending_operation_progress(&mut self) {
        let progress = self
            .operation
            .as_ref()
            .map(|operation| operation.progress_receiver.try_iter().collect::<Vec<_>>())
            .unwrap_or_default();
        for event in progress {
            match event {
                OperationProgress::CleanupStarted(mount_path) => {
                    record_cleanup_started_activity(&mut self.history, &mount_path);
                }
            }
        }
    }

    fn poll_operation(&mut self, context: &egui::Context) {
        self.record_pending_operation_progress();

        let result = self.operation.as_ref().and_then(|operation| {
            let result = match operation.receiver.try_recv() {
                Ok(result) => Some(result),
                Err(TryRecvError::Empty) => None,
                Err(TryRecvError::Disconnected) => Some(Err(OperationFailure {
                    message: "background archive operation stopped unexpectedly".to_string(),
                    offer_lazy_unmount: false,
                })),
            };
            result.map(|result| (operation.action, operation.archive_path.clone(), result))
        });

        if result.is_some() {
            self.record_pending_operation_progress();
        }

        if let Some((action, archive_path, result)) = result {
            self.operation = None;
            match result {
                Ok(success) => {
                    self.history.record(HistoryEntry::new(
                        ActivityAction::from(action),
                        Some(archive_path.clone()),
                        ActivityOutcome::Completed,
                        success.message.clone(),
                    ));
                    let cleanup_feedback = success.cleanup.as_ref().map(|cleanup| {
                        record_cleanup_finished_activity(&mut self.history, cleanup);
                        CleanupFeedback {
                            succeeded: matches!(cleanup, CleanupOutcome::Completed { .. }),
                            message: cleanup.message().to_string(),
                        }
                    });
                    self.feedback = Some(ActionFeedback {
                        succeeded: true,
                        message: success.message,
                        cleanup: cleanup_feedback,
                        warning: success.warning,
                        more_information: None,
                    });
                    match action {
                        ArchiveAction::Unmount | ArchiveAction::LazyUnmount => {
                            self.lazy_unmount_offers.remove(&archive_path);
                            self.remount_offers.insert(archive_path.clone());
                            self.history.record(HistoryEntry::new(
                                ActivityAction::Remount,
                                Some(archive_path),
                                ActivityOutcome::Offered,
                                "Remount offered after successful unmount.",
                            ));
                        }
                        ArchiveAction::Remount => {
                            self.remount_offers.remove(&archive_path);
                        }
                        ArchiveAction::Mount => {}
                    }
                    self.refresh(context);
                }
                Err(failure) => {
                    let normal_unmount_recovery =
                        action == ArchiveAction::Unmount && failure.offer_lazy_unmount;
                    let activity_message = if normal_unmount_recovery {
                        format!("Normal unmount failed: {}", failure.message)
                    } else {
                        failure.message.clone()
                    };
                    self.history.record(HistoryEntry::new(
                        ActivityAction::from(action),
                        Some(archive_path.clone()),
                        ActivityOutcome::Failed,
                        activity_message,
                    ));
                    if normal_unmount_recovery {
                        self.lazy_unmount_offers.insert(archive_path.clone());
                        self.history.record(HistoryEntry::new(
                            ActivityAction::LazyUnmount,
                            Some(archive_path),
                            ActivityOutcome::Offered,
                            "Lazy unmount offered after normal unmount failed.",
                        ));
                    }
                    self.feedback = Some(ActionFeedback {
                        succeeded: false,
                        message: if normal_unmount_recovery {
                            NORMAL_UNMOUNT_FAILURE_SUMMARY.to_string()
                        } else {
                            failure.message.clone()
                        },
                        cleanup: None,
                        warning: None,
                        more_information: normal_unmount_recovery.then(|| {
                            format!(
                                "{NORMAL_UNMOUNT_RECOVERY_GUIDANCE}\n\nEmuWiz detail: {}",
                                failure.message
                            )
                        }),
                    });
                }
            }
        }
    }

    /// Applies a `MountPageAction` returned by the Mount or Selected
    /// page. Queue execution re-derives eligibility from the live
    /// snapshot at the moment of the click (queue order, `Pending`
    /// only), then hands the items to the proven `start_mount_all`
    /// batch engine - never a stale item list captured at render time.
    fn handle_mount_page_action(
        &mut self,
        context: &egui::Context,
        action: Option<MountPageAction>,
    ) {
        match action {
            Some(MountPageAction::MountQueue) => {
                let items = match &self.state {
                    LoadState::Ready(data) => {
                        let eligible = queued_pending_paths(&self.mount_queue, &data.records);
                        mount_all_items_for_paths(&data.records, &eligible)
                    }
                    _ => Vec::new(),
                };
                if !items.is_empty() {
                    self.start_mount_all(context.clone(), items);
                }
            }
            Some(MountPageAction::Refresh) => self.refresh(context),
            Some(MountPageAction::GoToMount) => {
                self.view = MainView::Mount;
                self.tools_overlay = ToolsOverlay::None;
            }
            Some(MountPageAction::OpenCheatsMods(archive_path)) => {
                self.archive_context.select_only(archive_path.clone());
                self.open_cheats_mods_workspace(context, archive_path);
            }
            Some(MountPageAction::ScanRetroArchProfiles) => {
                self.start_retroarch_profile_scan(context.clone());
            }
            None => {}
        }
    }

    /// Selects the full-page Cheats & Mods workspace context without
    /// starting I/O. Returning to the same exact archive preserves the
    /// existing workflow; changing archive replaces it wholesale. The
    /// return value says whether a new source-list load is needed.
    fn prepare_cheats_mods_workspace(&mut self, archive_path: PathBuf) -> bool {
        // Phase 5 fix: this used to only set `self.view`, which Gamer
        // View's own render branch never reads (chosen purely from
        // `ui_mode` - see the Phase 4 fix to `start_cheat_install_
        // rollback` for the identical bug shape). Clicking "Cheats &
        // Mods" from Gamer View therefore changed internal state with
        // nothing visible happening on screen at all - the design doc's
        // own stated centerpiece workflow (§2.5) was silently
        // unreachable from the screen it names as its entry point. This
        // page is deliberately the *existing* full workflow, unsimplified
        // (§2.1: "opens the existing 5-area workflow page... no
        // independent archive picker"), so switching modes here is
        // correct, not a compromise - the doc's own design already
        // expects this transition.
        self.ui_mode = GuiMode::AdvancedView;
        save_gui_mode(self.ui_mode);
        self.view = MainView::CheatsMods;
        self.tools_overlay = ToolsOverlay::None;
        if self
            .cheat_workflow
            .as_ref()
            .is_some_and(|workflow| workflow.archive_path == archive_path)
        {
            return false;
        }
        if let Some(cancellation) = self
            .cheat_workflow
            .as_ref()
            .and_then(|workflow| workflow.gamecube_gamehacking_cancellation.as_ref())
        {
            cancellation.store(true, Ordering::Relaxed);
        }
        let (
            source_mode,
            selected_source_id,
            fetch_force_refresh,
            previous_profile_id,
            previous_pcsx2_profile_id,
            previous_dolphin_profile_id,
            previous_xenia_profile_id,
        ) = self
            .cheat_workflow
            .as_ref()
            .map(|workflow| {
                (
                    workflow.source_mode,
                    workflow.selected_source_id.clone(),
                    workflow.fetch_force_refresh,
                    workflow.selected_profile_id.clone(),
                    workflow.selected_pcsx2_profile_id.clone(),
                    workflow.selected_dolphin_profile_id.clone(),
                    workflow.selected_xenia_profile_id.clone(),
                )
            })
            .unwrap_or((
                CheatSourceMode::ArchiveFsTrustedCatalogue,
                None,
                false,
                None,
                None,
                None,
                None,
            ));
        let record_details = match &self.state {
            LoadState::Ready(data) => Some(data.as_ref()),
            LoadState::Loading { previous, .. } => previous.as_deref(),
            LoadState::Error(_) => None,
        }
        .and_then(|data| {
            data.records
                .iter()
                .find(|record| record.mount_plan.archive.path == archive_path)
                .map(|record| {
                    (
                        record.identity.display_name.clone(),
                        record.identity.normalized_name.clone(),
                        record.identity.platform.clone(),
                        record.identity.region.clone(),
                        record.identity.source_root.clone(),
                        record.identity.size_bytes,
                    )
                })
        });
        let Some((display_name, normalized_name, platform, region, source_root, size_bytes)) =
            record_details
        else {
            self.cheat_workflow = None;
            return false;
        };
        let adapter = cheat_adapter_route(platform.as_deref());
        let persisted_identity = self
            .database_state
            .snapshot()
            .and_then(|snapshot| {
                snapshot
                    .archives
                    .iter()
                    .find(|archive| archive.absolute_path == archive_path)
            })
            .and_then(|archive| archive.identity_report.clone());
        let persisted_identity_request = persisted_identity.as_ref().map(|_| GameIdentityRequest {
            archive_path: archive_path.clone(),
            platform: platform.clone(),
            adapter,
        });
        let selected_profile_id = match &self.retroarch_profiles {
            RetroArchProfilesState::Ready(discovery) => {
                let eligible = eligible_profile_ids(discovery);
                if let Some(previous) =
                    previous_profile_id.filter(|previous| eligible.contains(&previous.as_str()))
                {
                    Some(previous)
                } else if eligible.len() == 1 {
                    Some(eligible[0].to_string())
                } else {
                    None
                }
            }
            _ => None,
        };
        let selected_pcsx2_profile_id = match &self.pcsx2_profiles {
            Pcsx2ProfilesState::Ready(discovery) => {
                let eligible = eligible_pcsx2_profile_ids(discovery);
                if let Some(previous) = previous_pcsx2_profile_id
                    .filter(|previous| eligible.contains(&previous.as_str()))
                {
                    Some(previous)
                } else if eligible.len() == 1 {
                    Some(eligible[0].to_string())
                } else {
                    None
                }
            }
            _ => None,
        };
        let (selected_dolphin_profile_id, dolphin_profile_selection) = match &self.dolphin_profiles
        {
            DolphinProfilesState::Ready(discovery) => {
                let selection =
                    select_dolphin_profile(discovery, previous_dolphin_profile_id.as_deref());
                let selected = match &selection {
                    EmulatorProfileSelection::Auto { profile_id, .. } => Some(profile_id.clone()),
                    EmulatorProfileSelection::NeedsChoice { .. }
                    | EmulatorProfileSelection::SetupNeeded => None,
                };
                (selected, Some(selection))
            }
            _ => (None, None),
        };
        let (selected_xenia_profile_id, xenia_profile_selection) = match &self.xenia_profiles {
            XeniaProfilesState::Ready(discovery) => {
                let candidates = xenia_profile_candidates(discovery);
                let selection = select_emulator_profile(
                    &candidates,
                    self.remembered_profile_id("xenia").as_deref(),
                    previous_xenia_profile_id.as_deref(),
                );
                let selected = match &selection {
                    EmulatorProfileSelection::Auto { profile_id, .. } => Some(profile_id.clone()),
                    EmulatorProfileSelection::NeedsChoice { .. }
                    | EmulatorProfileSelection::SetupNeeded => None,
                };
                (selected, Some(selection))
            }
            XeniaProfilesState::NotScanned => (None, None),
        };
        self.cheat_workflow = Some(CheatWorkflowState {
            archive_path,
            display_name,
            normalized_name,
            platform,
            region,
            source_root,
            size_bytes,
            adapter,
            identity_request: persisted_identity_request.clone(),
            identity: match (persisted_identity_request, persisted_identity) {
                (Some(request), Some(report)) => CheatStepResource::Ready((request, report)),
                _ => CheatStepResource::NotLoaded,
            },
            preview_request: None,
            preview: CheatStepResource::NotLoaded,
            transaction: CheatTransactionState::Idle,
            transaction_notice: None,
            selected_profile_id,
            selected_pcsx2_profile_id,
            pcsx2_inventory_profile_id: None,
            pcsx2_inventory: CheatStepResource::NotLoaded,
            pcsx2_gamehacking: CheatStepResource::NotLoaded,
            gamecube_gamehacking: CheatStepResource::NotLoaded,
            gamecube_gamehacking_request: None,
            gamecube_gamehacking_cancellation: None,
            gamecube_gamehacking_generation: 0,
            gamecube_gamehacking_blocked: false,
            bsfree_gamecube: CheatStepResource::NotLoaded,
            bsfree_gamecube_cancellation: None,
            bsfree_gamecube_generation: 0,
            bsfree_wii: CheatStepResource::NotLoaded,
            bsfree_wii_cancellation: None,
            bsfree_wii_generation: 0,
            selected_dolphin_profile_id,
            dolphin_explicit_root: String::new(),
            dolphin_inventory_profile_id: None,
            dolphin_inventory: CheatStepResource::NotLoaded,
            dolphin_provider_request: None,
            dolphin_provider: CheatStepResource::NotLoaded,
            dolphin_provider_selection: None,
            dolphin_destination_error: None,
            dolphin_local_lookup: DolphinLocalLookupState::NotAttempted,
            dolphin_profile_selection,
            // Remembered standard/install-only profiles are rediscovery hints,
            // not a hidden choice when more than one credible profile exists.
            dolphin_profile_choice: None,
            dolphin_details_open: false,
            dolphin_show_exact_changes: false,
            selected_xenia_profile_id,
            xenia_explicit_root: String::new(),
            xenia_provider_request: None,
            xenia_provider: CheatStepResource::NotLoaded,
            xenia_selected_candidate_index: None,
            xenia_selection: None,
            xenia_destination_error: None,
            xenia_profile_selection,
            xenia_profile_choice: None,
            xenia_details_open: false,
            xenia_show_exact_changes: false,
            source_mode,
            existing_library_profile_id: None,
            existing_library: CheatStepResource::NotLoaded,
            source_list: CheatStepResource::NotLoaded,
            source_fetch: CheatStepResource::NotLoaded,
            selected_source_id,
            fetch_force_refresh,
            candidates: CheatStepResource::NotLoaded,
            candidates_request: None,
            candidate_query: String::new(),
            candidate_selection: None,
            candidate_load_error: None,
        });
        true
    }

    /// Opens the full-page workspace and starts its read-only trusted
    /// source inventory only when the exact archive context is new.
    fn open_cheats_mods_workspace(&mut self, context: &egui::Context, archive_path: PathBuf) {
        if !self.prepare_cheats_mods_workspace(archive_path) {
            return;
        }
        // Read-only listing of the local trusted-source cache; safe to
        // start immediately (no network, background thread).
        self.start_cheat_source_list(context.clone());
        if self
            .cheat_workflow
            .as_ref()
            .is_some_and(|workflow| matches!(workflow.identity, CheatStepResource::NotLoaded))
        {
            self.start_game_identity_inspection(context.clone());
        }
        if self
            .cheat_workflow
            .as_ref()
            .is_some_and(|workflow| workflow.adapter == CheatEmulatorAdapter::Pcsx2)
            && matches!(
                self.pcsx2_profiles,
                Pcsx2ProfilesState::NotScanned | Pcsx2ProfilesState::Error(_)
            )
        {
            self.start_pcsx2_profile_scan(context.clone());
        }
        if self
            .cheat_workflow
            .as_ref()
            .is_some_and(|workflow| workflow.adapter == CheatEmulatorAdapter::Dolphin)
        {
            self.seed_explicit_root_from_remembered_profile("dolphin");
            if matches!(
                self.dolphin_profiles,
                DolphinProfilesState::NotScanned | DolphinProfilesState::Error(_)
            ) {
                self.start_dolphin_profile_scan(context.clone());
            }
        }
        if self
            .cheat_workflow
            .as_ref()
            .is_some_and(|workflow| workflow.adapter == CheatEmulatorAdapter::Xenia)
        {
            self.seed_explicit_root_from_remembered_profile("xenia");
            if matches!(self.xenia_profiles, XeniaProfilesState::NotScanned) {
                self.start_xenia_profile_scan();
            }
        }
    }

    /// Seeds the workflow's explicit-root text field from the remembered
    /// profile for `adapter`, but only when the field is still empty -
    /// never overwrites anything the user has already typed this
    /// session. This is what lets a remembered portable Dolphin install
    /// or a remembered Xenia Canary directory be rediscovered
    /// automatically without asking again, since neither adapter has a
    /// single standard path EmuWiz can otherwise find on its own.
    fn seed_explicit_root_from_remembered_profile(&mut self, adapter: &str) {
        let Some(root) = self.remembered_profile_root(adapter) else {
            return;
        };
        let Some(root) = root.to_str().map(str::to_string) else {
            return;
        };
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        match adapter {
            "dolphin" if workflow.dolphin_explicit_root.trim().is_empty() => {
                workflow.dolphin_explicit_root = root;
            }
            "xenia" if workflow.xenia_explicit_root.trim().is_empty() => {
                workflow.xenia_explicit_root = root;
            }
            _ => {}
        }
    }

    fn start_game_identity_inspection(&mut self, context: egui::Context) {
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        if workflow.adapter == CheatEmulatorAdapter::Unsupported {
            return;
        }
        let request = GameIdentityRequest {
            archive_path: workflow.archive_path.clone(),
            platform: workflow.platform.clone(),
            adapter: workflow.adapter,
        };
        let path = request.archive_path.clone();
        let platform = request.platform.clone();
        let worker_request = request.clone();
        let (sender, receiver) = mpsc::channel();
        workflow.identity_request = Some(request);
        workflow.identity = CheatStepResource::Loading { receiver };
        workflow.preview_request = None;
        workflow.preview = CheatStepResource::NotLoaded;
        thread::spawn(move || {
            let report = inspect_catalogued_game_identity(&path, platform.as_deref());
            let _ = sender.send(Ok((worker_request, report)));
            context.request_repaint();
        });
    }

    /// GUI Batch A: starts (or restarts, on a new selection) the real,
    /// off-UI-thread evidence gather for the Selected page's identity
    /// panel - see `selected_evidence_page::gather_selected_evidence`.
    /// Started automatically when the selected game changes so identity
    /// evidence is available in the selected-game details surface and to
    /// the launch planner. The worker remains generation-guarded and
    /// read-only.
    fn start_selected_evidence_load(&mut self, context: egui::Context, path: PathBuf) {
        self.cancel_selected_evidence_work();
        self.selected_evidence_generation += 1;
        let generation = self.selected_evidence_generation;
        let cancel = Arc::new(AtomicBool::new(false));
        self.selected_evidence_cancel = Some(Arc::clone(&cancel));
        let (sender, receiver) = mpsc::channel();
        self.selected_evidence = selected_evidence_page::SelectedEvidenceState::Loading {
            generation,
            path: path.clone(),
            receiver,
        };
        // A new selection invalidates any in-flight or completed enrichment
        // pass for the previous file.
        self.selected_evidence_enrichment = SelectedEvidenceEnrichmentState::Idle;
        let platform_hint = match &self.state {
            LoadState::Ready(data) => data
                .records
                .iter()
                .find(|record| record.mount_plan.archive.path == path)
                .and_then(|record| {
                    record
                        .metadata
                        .platform
                        .as_deref()
                        .or(record.identity.platform.as_deref())
                })
                .map(str::to_owned),
            LoadState::Loading { .. } | LoadState::Error(_) => None,
        };
        thread::spawn(move || {
            // Fast pass only: bounded header read + the bounded per-platform
            // identity inspector. For loose files, the whole-file checksum
            // and No-Intro DAT resolution are the deferred enrichment pass
            // (`start_selected_evidence_enrichment`). Compressed archives
            // terminate after bounded member evidence, so neither path can
            // hold back the visible identity.
            let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                selected_evidence_page::gather_selected_evidence_fast(
                    &path,
                    platform_hint.as_deref(),
                )
            }))
            .unwrap_or_else(|_| {
                Err(
                    "the identity worker stopped unexpectedly while inspecting this file"
                        .to_string(),
                )
            });
            let result = if cancel.load(Ordering::Relaxed) {
                Err("identity inspection was cancelled after the selection changed".to_string())
            } else {
                result
            };
            let _ = sender.send((generation, result));
            context.request_repaint();
        });
    }

    fn cancel_selected_evidence_work(&mut self) {
        if let Some(cancel) = self.selected_evidence_cancel.take() {
            cancel.store(true, Ordering::Relaxed);
        }
    }

    /// Cancels and detaches evidence work as soon as Library focus no longer
    /// names the path represented by the state machine. Generation checks
    /// still guard every reply; cancellation additionally stops the costly
    /// hash instead of allowing stale I/O to continue in the background.
    fn reconcile_selected_evidence_selection(&mut self) {
        let state_path = match &self.selected_evidence {
            selected_evidence_page::SelectedEvidenceState::Loading { path, .. }
            | selected_evidence_page::SelectedEvidenceState::Error { path, .. } => Some(path),
            selected_evidence_page::SelectedEvidenceState::Ready { report, .. } => {
                Some(&report.path)
            }
            selected_evidence_page::SelectedEvidenceState::Idle => None,
        };
        if state_path.map(PathBuf::as_path) != self.archive_context.focused.as_deref()
            && state_path.is_some()
        {
            self.cancel_selected_evidence_work();
            self.selected_evidence = selected_evidence_page::SelectedEvidenceState::Idle;
            self.selected_evidence_enrichment = SelectedEvidenceEnrichmentState::Idle;
        }
    }

    /// Starts the deferred enrichment pass for an already-visible `Ready`
    /// loose-file report whose `hashes` are not yet filled in: the whole-file
    /// checksum and the No-Intro DAT lookup, both resolved entirely off the UI
    /// thread. Generation-guarded like every other background loader; a new
    /// selection (which bumps `selected_evidence_generation` and resets the
    /// enrichment state to `Idle`) makes a late result be discarded. Archive
    /// reports never call this method.
    fn start_selected_evidence_enrichment(
        &mut self,
        context: egui::Context,
        path: PathBuf,
        generation: u64,
        platform: Option<String>,
    ) {
        let (sender, receiver) = mpsc::channel();
        self.selected_evidence_enrichment = SelectedEvidenceEnrichmentState::Loading {
            generation,
            path: path.clone(),
            receiver,
        };
        let cancel = Arc::clone(
            self.selected_evidence_cancel
                .get_or_insert_with(|| Arc::new(AtomicBool::new(false))),
        );
        let no_intro_source_cache = Arc::clone(&self.no_intro_source_cache);
        thread::spawn(move || {
            let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                if cancel.load(Ordering::Relaxed) {
                    return Err(
                        "additional evidence was cancelled after the selection changed".to_string(),
                    );
                }
                let config_path = archivefs_core::dat::sources::default_dat_sources_config_path();
                let no_intro_state = config_path
                    .as_deref()
                    .ok()
                    .and_then(|config_path| {
                        archivefs_core::dat::sources::load_dat_sources_config_from(config_path).ok()
                    })
                    .map(|config| {
                        archivefs_core::dat::sources::DatSourceRegistry::from_config(&config).0
                    })
                    .map(|registry| {
                        no_intro_source_cache
                            .lock()
                            .unwrap_or_else(|poisoned| poisoned.into_inner())
                            .resolve(&registry, platform.as_deref())
                            .clone()
                    });
                if cancel.load(Ordering::Relaxed) {
                    return Err(
                        "additional evidence was cancelled after the selection changed".to_string(),
                    );
                }
                let resolved_source = match &no_intro_state {
                    Some(selected_evidence_no_intro::NoIntroSourceState::Selected(imported)) => {
                        Some(imported.as_ref())
                    }
                    _ => None,
                };
                selected_evidence_page::compute_selected_evidence_enrichment_cancellable(
                    &path,
                    resolved_source,
                    Some(&cancel),
                )
            }))
            .unwrap_or_else(|_| {
                Err("the additional-evidence worker stopped unexpectedly".to_string())
            });
            let _ = sender.send((generation, result));
            context.request_repaint();
        });
    }

    /// If the fast pass has produced a `Ready` report for the current
    /// selection whose whole-file `hashes` are still unset, and no
    /// enrichment pass has been started or finished for it, start one. Kept
    /// out of `poll_selected_evidence` so it can read the freshly-settled
    /// `Ready` state and the live record set in the same frame.
    fn maybe_start_selected_evidence_enrichment(&mut self, context: &egui::Context) {
        let selected_evidence_page::SelectedEvidenceState::Ready {
            generation, report, ..
        } = &self.selected_evidence
        else {
            return;
        };
        if !matches!(
            report.enrichment,
            selected_evidence_page::SelectedEvidenceEnrichmentStatus::Pending
        ) {
            return;
        }
        let generation = *generation;
        let path = report.path.clone();
        let already = match &self.selected_evidence_enrichment {
            SelectedEvidenceEnrichmentState::Idle => false,
            SelectedEvidenceEnrichmentState::Loading {
                generation: g,
                path: p,
                ..
            }
            | SelectedEvidenceEnrichmentState::Done {
                generation: g,
                path: p,
            } => *g == generation && *p == path,
        };
        if already {
            return;
        }
        let platform = report
            .identity
            .platform
            .map(str::to_owned)
            .or_else(|| Some(report.game_identity_report.platform.label().to_string()));
        self.start_selected_evidence_enrichment(context.clone(), path, generation, platform);
    }

    /// GUI Batch A: the explicit "Check Hasheous" action - a real network
    /// call, always off the UI thread, never started automatically. Uses
    /// the adapter's own default host/timeout constants; clicking the
    /// button is itself the opt-in this batch requires.
    fn start_selected_hasheous_check(&mut self, context: egui::Context) {
        let selected_evidence_page::SelectedEvidenceState::Ready {
            generation, report, ..
        } = &mut self.selected_evidence
        else {
            return;
        };
        let Some(sha1) = report.hashes.as_ref().map(|hashes| hashes.sha1.clone()) else {
            return;
        };
        let generation = *generation;
        let (sender, receiver) = mpsc::channel();
        if let selected_evidence_page::SelectedEvidenceState::Ready { hasheous, .. } =
            &mut self.selected_evidence
        {
            *hasheous = selected_evidence_page::HasheousState::Loading {
                generation,
                receiver,
            };
        }
        thread::spawn(move || {
            use archivefs_core::identity_source::hasheous::client::{
                HASHEOUS_DEFAULT_BASE_URL, HasheousConfig, REQUEST_TIMEOUT,
            };
            let config = HasheousConfig {
                enabled: true,
                base_url: HASHEOUS_DEFAULT_BASE_URL.to_string(),
                timeout: REQUEST_TIMEOUT,
            };
            let outcome = selected_evidence_page::run_hasheous_check_live(&config, &sha1);
            let _ = sender.send((generation, outcome));
            context.request_repaint();
        });
    }

    /// GUI Batch A: applies the pure [`selected_evidence_page::SelectedEvidenceAction`]
    /// the panel returned this frame - the only two things it can ever ask
    /// for, both read-only.
    fn handle_selected_evidence_action(
        &mut self,
        context: &egui::Context,
        action: Option<selected_evidence_page::SelectedEvidenceAction>,
    ) {
        match action {
            Some(selected_evidence_page::SelectedEvidenceAction::Load(path)) => {
                self.start_selected_evidence_load(context.clone(), path);
            }
            Some(selected_evidence_page::SelectedEvidenceAction::CheckHasheous) => {
                self.start_selected_hasheous_check(context.clone());
            }
            None => {}
        }
    }

    /// GUI Batch A: drains a completed evidence-load or Hasheous-check
    /// message, discarding anything whose generation is no longer current
    /// (the same stale-result guard every other background loader in this
    /// app uses).
    fn poll_selected_evidence(&mut self) {
        let base_result = match &self.selected_evidence {
            selected_evidence_page::SelectedEvidenceState::Loading {
                generation,
                receiver,
                ..
            } => match receiver.try_recv() {
                Ok((message_generation, result)) => Some((*generation, message_generation, result)),
                Err(TryRecvError::Empty) => None,
                Err(TryRecvError::Disconnected) => Some((
                    *generation,
                    *generation,
                    Err("the identity worker stopped without returning a result".to_string()),
                )),
            },
            _ => None,
        };
        if let Some((state_generation, message_generation, result)) = base_result
            && state_generation == self.selected_evidence_generation
            && message_generation == state_generation
        {
            let path = match &self.selected_evidence {
                selected_evidence_page::SelectedEvidenceState::Loading { path, .. } => path.clone(),
                _ => return,
            };
            self.selected_evidence = match result {
                Ok(report) => selected_evidence_page::SelectedEvidenceState::Ready {
                    generation: message_generation,
                    report: Box::new(report),
                    hasheous: selected_evidence_page::HasheousState::Idle,
                },
                Err(message) => selected_evidence_page::SelectedEvidenceState::Error {
                    generation: message_generation,
                    path,
                    message,
                },
            };
        }
        // Two separate borrows of `self.selected_evidence` (read to poll the
        // channel, then a fresh mutable one to write the result) rather than
        // one collapsed condition - the write must start after the read
        // borrow above has already ended.
        #[allow(clippy::collapsible_if)]
        if let selected_evidence_page::SelectedEvidenceState::Ready { hasheous, .. } =
            &self.selected_evidence
            && let selected_evidence_page::HasheousState::Loading {
                generation,
                receiver,
            } = hasheous
            && let Ok((message_generation, outcome)) = receiver.try_recv()
            && message_generation == *generation
        {
            if let selected_evidence_page::SelectedEvidenceState::Ready { hasheous, .. } =
                &mut self.selected_evidence
            {
                *hasheous = selected_evidence_page::HasheousState::Done {
                    generation: message_generation,
                    outcome,
                };
            }
        }

        // Drain a completed deferred enrichment pass (whole-file checksum +
        // No-Intro lookup) and merge it into the `Ready` report the panel is
        // already showing, if the selection has not moved on since.
        let enrichment_result = match &self.selected_evidence_enrichment {
            SelectedEvidenceEnrichmentState::Loading {
                generation,
                receiver,
                ..
            } => match receiver.try_recv() {
                Ok((message_generation, result)) => Some((*generation, message_generation, result)),
                Err(TryRecvError::Empty) => None,
                Err(TryRecvError::Disconnected) => Some((
                    *generation,
                    *generation,
                    Err(
                        "the additional-evidence worker stopped without returning a result"
                            .to_string(),
                    ),
                )),
            },
            SelectedEvidenceEnrichmentState::Idle
            | SelectedEvidenceEnrichmentState::Done { .. } => None,
        };
        if let Some((state_generation, message_generation, result)) = enrichment_result
            && state_generation == self.selected_evidence_generation
            && message_generation == state_generation
        {
            let (generation, path) = match &self.selected_evidence_enrichment {
                SelectedEvidenceEnrichmentState::Loading {
                    generation, path, ..
                } => (*generation, path.clone()),
                SelectedEvidenceEnrichmentState::Idle
                | SelectedEvidenceEnrichmentState::Done { .. } => return,
            };
            if let selected_evidence_page::SelectedEvidenceState::Ready {
                generation: ready_generation,
                report,
                ..
            } = &mut self.selected_evidence
                && *ready_generation == generation
                && report.path == path
            {
                match result {
                    Ok(enrichment) => {
                        selected_evidence_page::apply_selected_evidence_enrichment(
                            report, enrichment,
                        );
                    }
                    Err(message) => {
                        selected_evidence_page::apply_selected_evidence_enrichment_error(
                            report, message,
                        );
                    }
                }
            }
            self.selected_evidence_enrichment =
                SelectedEvidenceEnrichmentState::Done { generation, path };
        }
    }

    /// GUI Batch B: starts (or refreshes) the read-only "Sources &
    /// Providers" status load - see `identity_sources_page`'s own module
    /// doc. Explicit only (a button press); never called automatically.
    fn start_identity_sources_load(&mut self, context: egui::Context) {
        self.identity_sources_generation += 1;
        let generation = self.identity_sources_generation;
        let (sender, receiver) = mpsc::channel();
        self.identity_sources = identity_sources_page::IdentitySourcesState::Loading {
            generation,
            receiver,
        };
        thread::spawn(move || {
            let config_path = archivefs_core::dat::sources::default_dat_sources_config_path();
            let status =
                identity_sources_page::gather_no_intro_sources_status(config_path.as_deref().ok());
            let _ = sender.send((generation, status));
            context.request_repaint();
        });
    }

    /// GUI Batch B: applies the pure
    /// [`identity_sources_page::IdentitySourcesAction`] the panel returned
    /// this frame - the only thing it can ever ask for, and read-only.
    fn handle_identity_sources_action(
        &mut self,
        context: &egui::Context,
        action: Option<identity_sources_page::IdentitySourcesAction>,
    ) {
        if let Some(identity_sources_page::IdentitySourcesAction::Load) = action {
            self.start_identity_sources_load(context.clone());
        }
    }

    /// GUI Batch B: drains a completed sources-status load, discarding
    /// anything whose generation is no longer current - the same
    /// stale-result guard `poll_selected_evidence` already uses.
    fn poll_identity_sources(&mut self) {
        if let identity_sources_page::IdentitySourcesState::Loading {
            generation,
            receiver,
        } = &self.identity_sources
            && let Ok((message_generation, status)) = receiver.try_recv()
            && message_generation == *generation
        {
            self.identity_sources = identity_sources_page::IdentitySourcesState::Ready {
                generation: message_generation,
                status,
            };
        }
    }

    /// GUI Batch C: starts (or refreshes) the read-only "Plan Preview" load
    /// for the currently-ready selected-evidence report - see
    /// `plan_preview_page`'s own module doc. Explicit only (a button
    /// press); never called automatically. A no-op when the evidence
    /// report is not `Ready` (nothing to plan for yet).
    fn start_plan_preview_load(&mut self, context: egui::Context) {
        let selected_evidence_page::SelectedEvidenceState::Ready { report, .. } =
            &self.selected_evidence
        else {
            return;
        };
        let source_path = report.path.clone();
        let identity = report.identity_result.clone();
        let identity_presentation = report.identity.clone();
        let physical_hash = report.hashes.as_ref().map(|hashes| hashes.sha1.clone());

        self.plan_preview_generation += 1;
        let generation = self.plan_preview_generation;
        let (sender, receiver) = mpsc::channel();
        self.plan_preview = plan_preview_page::PlanPreviewState::Loading {
            generation,
            receiver,
        };
        thread::spawn(move || {
            let master_root = Config::load_default()
                .ok()
                .and_then(|config| config.master_rom_root);
            let outcome = plan_preview_page::gather_plan_preview(
                &source_path,
                &identity,
                &identity_presentation,
                physical_hash.as_deref(),
                master_root.as_deref(),
            );
            let _ = sender.send((generation, outcome));
            context.request_repaint();
        });
    }

    /// GUI Batch C: applies the pure
    /// [`plan_preview_page::PlanPreviewAction`] the panel returned this
    /// frame - the only thing it can ever ask for, and read-only.
    fn handle_plan_preview_action(
        &mut self,
        context: &egui::Context,
        action: Option<plan_preview_page::PlanPreviewAction>,
    ) {
        if let Some(plan_preview_page::PlanPreviewAction::Load) = action {
            self.start_plan_preview_load(context.clone());
        }
    }

    /// GUI Batch C: drains a completed plan-preview load, discarding
    /// anything whose generation is no longer current - the same
    /// stale-result guard `poll_identity_sources` already uses.
    fn poll_plan_preview(&mut self) {
        if let plan_preview_page::PlanPreviewState::Loading {
            generation,
            receiver,
        } = &self.plan_preview
            && let Ok((message_generation, outcome)) = receiver.try_recv()
            && message_generation == *generation
        {
            self.plan_preview = plan_preview_page::PlanPreviewState::Ready {
                generation: message_generation,
                outcome,
            };
        }
    }

    fn start_cheat_preview(&mut self, context: egui::Context) {
        let Some((key, work)) = self.cheat_workflow.as_ref().and_then(|workflow| {
            build_cheat_preview_request(
                workflow,
                &self.retroarch_profiles,
                &self.pcsx2_profiles,
                &self.dolphin_profiles,
            )
        }) else {
            return;
        };
        if self.cheat_workflow.as_ref().is_some_and(|workflow| {
            workflow.preview_request.as_ref() == Some(&key)
                && !matches!(workflow.preview, CheatStepResource::NotLoaded)
        }) {
            return;
        }
        let archive_path = key.archive_path.clone();
        let worker_key = key.clone();
        let (sender, receiver) = mpsc::channel();
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        workflow.preview_request = Some(key);
        workflow.preview = CheatStepResource::Loading { receiver };
        self.history.record(HistoryEntry::new(
            ActivityAction::CheatPreview,
            Some(archive_path),
            ActivityOutcome::Started,
            "Read-only Cheats & Mods preview started.",
        ));
        thread::spawn(move || {
            let (outcome, materialized) = match work {
                CheatPreviewWork::Shared(request) => (
                    match build_shared_preview(&request) {
                        Ok(report) => CheatPreviewOutcome::Ready(report),
                        Err(error) => {
                            CheatPreviewOutcome::Failed(CheatPreviewFailure::Shared(error))
                        }
                    },
                    None,
                ),
                CheatPreviewWork::RetroArch(request) => {
                    match materialize_retroarch_shared_preview(&request) {
                        Ok(materialized) => (
                            CheatPreviewOutcome::Ready(materialized.preview.clone()),
                            Some(materialized),
                        ),
                        Err(error) => (
                            CheatPreviewOutcome::Failed(CheatPreviewFailure::Materialization(
                                error,
                            )),
                            None,
                        ),
                    }
                }
            };
            let _ = sender.send(Ok(CheatPreviewResponse {
                key: worker_key,
                outcome,
                materialized,
                generated: None,
                dolphin_generated: None,
                xenia_generated: None,
                pcsx2_generated: None,
                gamecube_gamehacking_generated: None,
                bsfree_gamecube_generated: None,

                bsfree_wii_generated: None,
            }));
            context.request_repaint();
        });
    }

    /// Stage 4: builds the ranked candidate list for the selected archive
    /// against the verified catalogue snapshot, off the UI thread.
    ///
    /// Bound to the same request key the preview uses, so a result that
    /// arrives after the archive, profile, or snapshot changed is discarded
    /// rather than shown against the wrong context.
    /// Stage 4's dispatch target - reached from the "Find matching cheat
    /// files" button. Every call produces exactly one immediately visible
    /// outcome: it starts a background match (`Loading`, then `Ready` or a
    /// worker `Failed`), or it sets an explained `Failed` state on the spot
    /// when a prerequisite is unmet (`CheatCandidatePrerequisite`) - never
    /// a silent no-op. A call while a match is already running is itself a
    /// no-op (guards against a double click restarting the work).
    fn start_cheat_candidate_match(&mut self, context: egui::Context) {
        let Some(workflow) = self.cheat_workflow.as_ref() else {
            return;
        };
        if workflow.adapter != CheatEmulatorAdapter::RetroArch
            || workflow.source_mode != CheatSourceMode::ArchiveFsTrustedCatalogue
            || matches!(workflow.candidates, CheatStepResource::Loading { .. })
        {
            return;
        }
        let archive_path = workflow.archive_path.clone();
        let outcome = build_cheat_candidate_request(workflow, &self.retroarch_profiles);
        match outcome {
            Ok((key, catalogue_root, archive)) => {
                let worker_key = key.clone();
                let worker_root = catalogue_root.clone();
                let (sender, receiver) = mpsc::channel();
                let Some(workflow) = self.cheat_workflow.as_mut() else {
                    return;
                };
                workflow.candidates_request = Some(key);
                workflow.candidates = CheatStepResource::Loading { receiver };
                workflow.candidate_selection = None;
                workflow.candidate_load_error = None;
                workflow.preview = CheatStepResource::NotLoaded;
                workflow.preview_request = None;
                workflow.transaction = CheatTransactionState::Idle;
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive_path),
                    ActivityOutcome::Started,
                    "Matching the selected archive against the trusted cheat catalogue.",
                ));
                thread::spawn(move || {
                    let snapshot = load_cheat_catalogue_snapshot(
                        &HostReadOnlyFilesystem,
                        "trusted-catalogue",
                        &worker_root,
                    );
                    let list = build_cheat_candidates(
                        &snapshot,
                        &archive,
                        &CheatCandidateOptions::default(),
                    );
                    let _ = sender.send(Ok(CheatCandidateStage {
                        key: worker_key,
                        catalogue_root: worker_root,
                        list,
                    }));
                    context.request_repaint();
                });
            }
            Err(reason) => {
                let Some(workflow) = self.cheat_workflow.as_mut() else {
                    return;
                };
                workflow.candidates_request = None;
                workflow.candidates = CheatStepResource::Failed(format!(
                    "{CHEAT_MATCH_BLOCKED_PREFIX}{}",
                    reason.message()
                ));
                workflow.candidate_selection = None;
                workflow.candidate_load_error = None;
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive_path),
                    ActivityOutcome::Rejected,
                    format!("Matching blocked: {}", reason.message()),
                ));
            }
        }
    }

    /// Stage 5/6: opens one chosen candidate and builds its cheat picker.
    ///
    /// Deliberately synchronous: this is one bounded read of a single small
    /// file in direct response to a click, and doing it inline keeps the
    /// chosen candidate and its parsed cheats impossible to get out of step.
    fn apply_cheat_candidate_choice(&mut self, relative_path: &str) {
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        let CheatStepResource::Ready(stage) = &workflow.candidates else {
            return;
        };
        let Some(candidate) = stage
            .list
            .candidates
            .iter()
            .find(|candidate| candidate.catalogue_relative_path == relative_path)
            .cloned()
        else {
            return;
        };
        if !candidate.manually_selectable {
            // The UI never offers this, but a candidate that can never be
            // installed must not become the selection through any path.
            return;
        }
        let catalogue_root = stage.catalogue_root.clone();
        let archive_path = workflow.archive_path.clone();
        workflow.preview = CheatStepResource::NotLoaded;
        workflow.preview_request = None;
        workflow.transaction = CheatTransactionState::Idle;
        match load_candidate_document(
            &catalogue_root,
            &candidate.catalogue_relative_path,
            candidate.source_file_hash.as_deref(),
        ) {
            Ok(loaded) => {
                let selection = CheatSelection::from_document(&loaded.document);
                let cheat_count = selection.entries.len();
                let blocked = selection.blocked_count();
                workflow.candidate_load_error = None;
                workflow.candidate_selection = Some(CheatCandidateSelection {
                    candidate,
                    loaded,
                    selection,
                });
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive_path),
                    ActivityOutcome::Completed,
                    format!(
                        "Candidate '{relative_path}' opened: {cheat_count} cheat(s), {blocked} unavailable."
                    ),
                ));
            }
            Err(error) => {
                workflow.candidate_selection = None;
                workflow.candidate_load_error = Some(error.detail.clone());
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive_path),
                    ActivityOutcome::Failed,
                    format!(
                        "Candidate '{relative_path}' could not be opened: {}",
                        error.detail
                    ),
                ));
            }
        }
    }

    /// Applies one Dolphin code picker edit and invalidates anything
    /// downstream, the same way `update_cheat_selection` does for RetroArch.
    fn update_dolphin_code_selection(
        &mut self,
        edit: impl FnOnce(&mut DolphinProviderCodeSelection),
    ) {
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        let Some(state) = workflow.dolphin_provider_selection.as_mut() else {
            return;
        };
        edit(&mut state.selection);
        workflow.preview = CheatStepResource::NotLoaded;
        workflow.preview_request = None;
        workflow.transaction = CheatTransactionState::Idle;
    }

    fn start_dolphin_provider_fetch(&mut self, context: egui::Context, force_refresh: bool) {
        let Some(workflow) = self.cheat_workflow.as_ref() else {
            return;
        };
        if workflow.adapter != CheatEmulatorAdapter::Dolphin
            || !platform_is_gamecube(workflow.platform.as_deref())
            || matches!(workflow.dolphin_provider, CheatStepResource::Loading { .. })
        {
            return;
        }
        let Some(identity) = ready_game_identity(workflow) else {
            return;
        };
        let Some(game_id) = identity.verified_dolphin_game_id().map(str::to_string) else {
            return;
        };
        let Some(revision) = identity.verified_dolphin_revision() else {
            return;
        };
        let Some(region) = region_for_game_id(&game_id) else {
            return;
        };
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_or(0, |duration| duration.as_secs());
        let mut options = match GeckoProviderFetchOptions::with_default_cache(now) {
            Ok(options) => options,
            Err(error) => {
                if let Some(workflow) = self.cheat_workflow.as_mut() {
                    workflow.dolphin_provider = CheatStepResource::Failed(error.to_string());
                }
                return;
            }
        };
        options.force_refresh = force_refresh;
        let query = GeckoProviderQuery {
            game_id: game_id.clone(),
            region,
            revision,
        };
        let key = DolphinProviderRequestKey {
            archive_path: workflow.archive_path.clone(),
            game_id,
            revision,
        };
        let archive_path = workflow.archive_path.clone();
        let (sender, receiver) = mpsc::channel();
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        workflow.dolphin_provider_request = Some(key);
        workflow.dolphin_provider = CheatStepResource::Loading { receiver };
        workflow.dolphin_provider_selection = None;
        workflow.dolphin_destination_error = None;
        workflow.preview_request = None;
        workflow.preview = CheatStepResource::NotLoaded;
        workflow.transaction = CheatTransactionState::Idle;
        self.history.record(HistoryEntry::new(
            ActivityAction::DolphinGeckoCandidateMatch,
            Some(archive_path),
            ActivityOutcome::Started,
            if force_refresh {
                "Refreshing exact-ID Gecko definitions from Dolphin upstream."
            } else {
                "Loading exact-ID Gecko definitions from Dolphin upstream or its local cache."
            },
        ));
        thread::spawn(move || {
            let result =
                fetch_dolphin_upstream_gecko(&query, &options).map_err(|error| error.to_string());
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    /// The synchronous, network-free counterpart to
    /// `start_dolphin_provider_fetch`: tries the local full catalogue
    /// first, then a validated cached single-game result. Never spawns a
    /// thread and never issues a network request - per the Dolphin cheat
    /// catalogue design, an explicit fetch (Details > Refresh) is the only
    /// way to reach the network once the local sources have nothing.
    /// Returns `true` if it populated `dolphin_provider`.
    fn try_resolve_dolphin_provider_from_local_sources(
        &mut self,
        dolphin_profile_paths: &HashMap<String, PathBuf>,
    ) -> bool {
        let Some(workflow) = self.cheat_workflow.as_ref() else {
            return false;
        };
        if workflow.adapter != CheatEmulatorAdapter::Dolphin
            || !platform_is_gamecube(workflow.platform.as_deref())
            || !matches!(workflow.dolphin_provider, CheatStepResource::NotLoaded)
        {
            return false;
        }
        let Some(identity) = ready_game_identity(workflow) else {
            return false;
        };
        let Some(game_id) = identity.verified_dolphin_game_id().map(str::to_string) else {
            return false;
        };
        let Some(revision) = identity.verified_dolphin_revision() else {
            return false;
        };
        let Some(region) = region_for_game_id(&game_id) else {
            return false;
        };
        let (Ok(catalogue_root), Ok(provider_root)) = (
            default_dolphin_catalogue_cache_root(),
            default_gecko_provider_cache_root(),
        ) else {
            return false;
        };
        let outcome = resolve_dolphin_gecko_lookup(
            &catalogue_root,
            &provider_root,
            &game_id,
            &region,
            revision,
        );
        let (fetch, local_state) = match outcome {
            Ok(DolphinGeckoLookupResult::Found(result)) => (
                Some(GeckoProviderFetchResult {
                    result,
                    status: GeckoProviderFetchStatus::Catalogue,
                    refresh_error: None,
                }),
                DolphinLocalLookupState::NotAttempted,
            ),
            Ok(
                DolphinGeckoLookupResult::NoCatalogueInstalled {
                    cached: Some(result),
                }
                | DolphinGeckoLookupResult::NotInCatalogue {
                    cached: Some(result),
                }
                | DolphinGeckoLookupResult::RegionMismatch {
                    cached: Some(result),
                }
                | DolphinGeckoLookupResult::CatalogueEntryHasNoUsableCodes {
                    cached: Some(result),
                    ..
                },
            ) => (
                Some(GeckoProviderFetchResult {
                    result,
                    status: GeckoProviderFetchStatus::FreshCache,
                    refresh_error: None,
                }),
                DolphinLocalLookupState::NotAttempted,
            ),
            Ok(DolphinGeckoLookupResult::NoCatalogueInstalled { cached: None }) => {
                (None, DolphinLocalLookupState::NoCatalogueInstalled)
            }
            Ok(DolphinGeckoLookupResult::NotInCatalogue { cached: None }) => {
                (None, DolphinLocalLookupState::NotInCatalogue)
            }
            Ok(DolphinGeckoLookupResult::RegionMismatch { cached: None }) => {
                (None, DolphinLocalLookupState::RegionMismatch)
            }
            Ok(DolphinGeckoLookupResult::CatalogueEntryHasNoUsableCodes {
                warnings,
                cached: None,
            }) => (None, DolphinLocalLookupState::NoUsableCodes { warnings }),
            Err(_) => (None, DolphinLocalLookupState::NotAttempted),
        };

        let Some(fetch) = fetch else {
            if let Some(workflow) = self.cheat_workflow.as_mut() {
                workflow.dolphin_local_lookup = local_state;
            }
            return false;
        };

        let key = DolphinProviderRequestKey {
            archive_path: workflow.archive_path.clone(),
            game_id,
            revision,
        };
        let (selection, destination_error) = build_dolphin_provider_selection(
            dolphin_profile_paths,
            workflow.selected_dolphin_profile_id.as_deref(),
            &fetch,
        );
        let archive_path = workflow.archive_path.clone();
        let message = format!(
            "Local Dolphin cheat source returned {} exact-ID code(s) for {} ({}).",
            fetch.result.entries.len(),
            fetch.result.game_id,
            dolphin_provider_fetch_status_label(fetch.status)
        );

        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return false;
        };
        workflow.dolphin_provider_request = Some(key);
        workflow.dolphin_destination_error = destination_error;
        workflow.dolphin_provider_selection = selection;
        workflow.dolphin_provider = CheatStepResource::Ready(fetch);
        workflow.dolphin_local_lookup = DolphinLocalLookupState::NotAttempted;
        self.history.record(HistoryEntry::new(
            ActivityAction::DolphinGeckoCandidateMatch,
            Some(archive_path),
            ActivityOutcome::Completed,
            message,
        ));
        true
    }

    /// Dolphin Stage 5: stages the surgically edited GameSettings file and
    /// builds its shared install preview. Synchronous for the same reason
    /// as `start_dolphin_candidate_match` - a single small local file.
    fn start_dolphin_install_preview(&mut self) {
        let Some(workflow) = self.cheat_workflow.as_ref() else {
            return;
        };
        let Some(profile_id) = workflow.selected_dolphin_profile_id.clone() else {
            return;
        };
        let CheatStepResource::Ready(provider) = &workflow.dolphin_provider else {
            return;
        };
        let Some(state) = workflow.dolphin_provider_selection.as_ref() else {
            return;
        };
        let key = cheat_preview_key(workflow);
        let archive_path = workflow.archive_path.clone();
        let configuration_path = match &self.dolphin_profiles {
            DolphinProfilesState::Ready(discovery) => discovery
                .profiles
                .iter()
                .find(|profile| profile.eligible && profile.profile_id == profile_id)
                .map(|profile| profile.configuration_path.clone()),
            _ => None,
        };
        let Some(configuration_path) = configuration_path else {
            self.history.record(HistoryEntry::new(
                ActivityAction::CheatPreview,
                Some(archive_path),
                ActivityOutcome::Rejected,
                "Install preview blocked: the selected Dolphin profile is no longer eligible.",
            ));
            return;
        };
        let names = match state.selection.resolve_names(&provider.result) {
            Ok(names) => names,
            Err(error) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive_path),
                    ActivityOutcome::Rejected,
                    format!("Install preview blocked: {}", error.detail),
                ));
                return;
            }
        };
        let staging_root = match default_generated_dolphin_staging_root() {
            Ok(root) => root,
            Err(message) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive_path),
                    ActivityOutcome::Failed,
                    message,
                ));
                return;
            }
        };
        self.history.record(HistoryEntry::new(
            ActivityAction::CheatPreview,
            Some(archive_path.clone()),
            ActivityOutcome::Started,
            format!(
                "Generating an install preview for {} selected Gecko code(s).",
                names.len()
            ),
        ));
        let response = (|| {
            let staged = stage_dolphin_provider_ini(
                &staging_root,
                &state.destination,
                &provider.result,
                &state.selection,
            )?;
            let preview = build_dolphin_install_preview(&DolphinInstallPreviewRequest {
                selected_archive: archive_path.clone(),
                configuration_path,
                game_id: provider.result.game_id.clone(),
                revision: Some(provider.result.revision),
                staged: staged.clone(),
            })?;
            Ok::<_, archivefs_core::patch_manager::DolphinInstallPlanError>((
                preview,
                staged,
                staging_root,
            ))
        })();
        let message = match response {
            Ok((preview, staged, staging_root)) => CheatPreviewResponse {
                key: key.clone(),
                outcome: CheatPreviewOutcome::Ready(preview.report),
                materialized: None,
                generated: None,
                dolphin_generated: Some(GeneratedDolphinInstall {
                    staging_root,
                    provider: provider.clone(),
                    destination: state.destination.path.clone(),
                    staged,
                }),
                xenia_generated: None,
                pcsx2_generated: None,
                gamecube_gamehacking_generated: None,
                bsfree_gamecube_generated: None,

                bsfree_wii_generated: None,
            },
            Err(error) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive_path),
                    ActivityOutcome::Failed,
                    format!("Install preview failed: {}", error.detail),
                ));
                CheatPreviewResponse {
                    key: key.clone(),
                    outcome: CheatPreviewOutcome::Failed(CheatPreviewFailure::DolphinInstallPlan(
                        error,
                    )),
                    materialized: None,
                    generated: None,
                    dolphin_generated: None,
                    xenia_generated: None,
                    pcsx2_generated: None,
                    gamecube_gamehacking_generated: None,
                    bsfree_gamecube_generated: None,

                    bsfree_wii_generated: None,
                }
            }
        };
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        workflow.preview_request = Some(key);
        workflow.preview = CheatStepResource::Ready(message);
        workflow.transaction = CheatTransactionState::Idle;
    }

    /// Explicit-directory-only and synchronous - see
    /// `discover_xenia_profiles`'s own documentation for why this never
    /// needs a background thread or a failure state.
    fn start_xenia_profile_scan(&mut self) {
        let explicit_root = self
            .cheat_workflow
            .as_ref()
            .map(|workflow| workflow.xenia_explicit_root.trim().to_string())
            .filter(|value| !value.is_empty())
            .map(PathBuf::from);
        let roots = XeniaProfileDiscoveryRoots {
            explicit_configuration_roots: explicit_root.into_iter().collect(),
        };
        let discovery = discover_xenia_profiles(&roots);
        self.history.record(HistoryEntry::new(
            ActivityAction::XeniaProfileScan,
            None,
            ActivityOutcome::Completed,
            format!(
                "Xenia Canary profile discovery found {} profile(s) ({} eligible).",
                discovery.profiles.len(),
                discovery
                    .profiles
                    .iter()
                    .filter(|profile| profile.eligible)
                    .count()
            ),
        ));
        let eligible = eligible_xenia_profile_ids(&discovery);
        let candidates = xenia_profile_candidates(&discovery);
        let remembered = self.remembered_profile_id("xenia");
        let mut to_persist: Option<(String, PathBuf)> = None;
        if let Some(workflow) = self.cheat_workflow.as_mut()
            && workflow.adapter == CheatEmulatorAdapter::Xenia
        {
            let session_explicit = workflow.xenia_profile_choice.clone();
            let selection = select_emulator_profile(
                &candidates,
                remembered.as_deref(),
                session_explicit.as_deref(),
            );
            let install_in_progress = !matches!(workflow.transaction, CheatTransactionState::Idle);
            if let EmulatorProfileSelection::Auto { profile_id, .. } = &selection
                && !install_in_progress
                && workflow.selected_xenia_profile_id.as_deref() != Some(profile_id.as_str())
            {
                workflow.selected_xenia_profile_id = Some(profile_id.clone());
                if let Some(root) = candidates
                    .iter()
                    .find(|candidate| candidate.profile_id == *profile_id)
                    .map(|candidate| candidate.root.clone())
                {
                    to_persist = Some((profile_id.clone(), root));
                }
            } else if !matches!(selection, EmulatorProfileSelection::Auto { .. })
                && !install_in_progress
                && workflow
                    .selected_xenia_profile_id
                    .as_ref()
                    .is_none_or(|selected| !eligible.contains(&selected.as_str()))
            {
                workflow.selected_xenia_profile_id = None;
            }
            workflow.xenia_profile_selection = Some(selection);
        }
        self.xenia_profiles = XeniaProfilesState::Ready(discovery);
        if let Some((profile_id, root)) = to_persist {
            self.persist_remembered_profile("xenia", &profile_id, &root);
        }
    }

    fn start_xenia_provider_fetch(&mut self, context: egui::Context, force_refresh: bool) {
        let Some(workflow) = self.cheat_workflow.as_ref() else {
            return;
        };
        if workflow.adapter != CheatEmulatorAdapter::Xenia
            || matches!(workflow.xenia_provider, CheatStepResource::Loading { .. })
        {
            return;
        }
        let Some(title_id) = ready_game_identity(workflow)
            .and_then(GameIdentityReport::verified_xex_title_id)
            .map(str::to_string)
        else {
            return;
        };
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_or(0, |duration| duration.as_secs());
        let mut options = match XeniaProviderFetchOptions::with_default_cache(now) {
            Ok(options) => options,
            Err(error) => {
                if let Some(workflow) = self.cheat_workflow.as_mut() {
                    workflow.xenia_provider = CheatStepResource::Failed(error.to_string());
                }
                return;
            }
        };
        options.force_refresh = force_refresh;
        let key = XeniaProviderRequestKey {
            archive_path: workflow.archive_path.clone(),
            title_id: title_id.clone(),
        };
        let archive_path = workflow.archive_path.clone();
        let (sender, receiver) = mpsc::channel();
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        workflow.xenia_provider_request = Some(key);
        workflow.xenia_provider = CheatStepResource::Loading { receiver };
        workflow.xenia_selected_candidate_index = None;
        workflow.xenia_selection = None;
        workflow.xenia_destination_error = None;
        workflow.preview_request = None;
        workflow.preview = CheatStepResource::NotLoaded;
        workflow.transaction = CheatTransactionState::Idle;
        self.history.record(HistoryEntry::new(
            ActivityAction::XeniaPatchCandidateMatch,
            Some(archive_path),
            ActivityOutcome::Started,
            if force_refresh {
                "Refreshing exact Title ID patches from the Xenia Canary game-patches provider."
            } else {
                "Loading exact Title ID patches from the Xenia Canary game-patches provider or its local cache."
            },
        ));
        thread::spawn(move || {
            let result = fetch_xenia_provider_patches(&title_id, &options)
                .map_err(|error| error.to_string());
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    /// Applies one Xenia patch picker edit and invalidates anything
    /// downstream, the same way `update_dolphin_code_selection` does.
    fn update_xenia_patch_selection(&mut self, edit: impl FnOnce(&mut XeniaPatchSelection)) {
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        let Some(state) = workflow.xenia_selection.as_mut() else {
            return;
        };
        edit(&mut state.selection);
        workflow.preview = CheatStepResource::NotLoaded;
        workflow.preview_request = None;
        workflow.transaction = CheatTransactionState::Idle;
    }

    /// Stages the merged `.patch.toml` and builds its shared install
    /// preview. Synchronous for the same reason as Dolphin's local path -
    /// a single small local file.
    fn start_xenia_install_preview(&mut self) {
        let Some(workflow) = self.cheat_workflow.as_ref() else {
            return;
        };
        let Some(profile_id) = workflow.selected_xenia_profile_id.clone() else {
            return;
        };
        let Some(state) = workflow.xenia_selection.as_ref() else {
            return;
        };
        let key = cheat_preview_key(workflow);
        let archive_path = workflow.archive_path.clone();
        let configuration_path = match &self.xenia_profiles {
            XeniaProfilesState::Ready(discovery) => discovery
                .profiles
                .iter()
                .find(|profile| profile.eligible && profile.profile_id == profile_id)
                .map(|profile| profile.configuration_path.clone()),
            XeniaProfilesState::NotScanned => None,
        };
        let Some(configuration_path) = configuration_path else {
            self.history.record(HistoryEntry::new(
                ActivityAction::CheatPreview,
                Some(archive_path),
                ActivityOutcome::Rejected,
                "Install preview blocked: the selected Xenia profile is no longer eligible.",
            ));
            return;
        };
        let names = match state.selection.resolve_names() {
            Ok(names) => names,
            Err(error) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive_path),
                    ActivityOutcome::Rejected,
                    format!("Install preview blocked: {}", error.detail),
                ));
                return;
            }
        };
        let staging_root = match default_generated_xenia_staging_root() {
            Ok(root) => root,
            Err(message) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive_path),
                    ActivityOutcome::Failed,
                    message,
                ));
                return;
            }
        };
        let file_name = state
            .destination
            .path
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or_default()
            .to_string();
        self.history.record(HistoryEntry::new(
            ActivityAction::CheatPreview,
            Some(archive_path.clone()),
            ActivityOutcome::Started,
            format!(
                "Generating an install preview for {} selected patch(es).",
                names.len()
            ),
        ));
        let response = (|| {
            let staged = stage_xenia_patch_file(
                &staging_root,
                &file_name,
                &state.candidate,
                state.destination.document.as_ref(),
                &names,
            )?;
            let preview = build_xenia_install_preview(&XeniaInstallPreviewRequest {
                selected_archive: archive_path.clone(),
                configuration_path,
                title_id: state.candidate.title_id.clone(),
                compatibility: state.candidate.compatibility,
                staged: staged.clone(),
            })?;
            Ok::<_, XeniaInstallPlanError>((preview, staged, staging_root))
        })();
        let message = match response {
            Ok((preview, staged, staging_root)) => CheatPreviewResponse {
                key: key.clone(),
                outcome: CheatPreviewOutcome::Ready(preview.report),
                materialized: None,
                generated: None,
                dolphin_generated: None,
                xenia_generated: Some(GeneratedXeniaInstall {
                    staging_root,
                    candidate: state.candidate.clone(),
                    destination: state.destination.path.clone(),
                    staged,
                }),
                pcsx2_generated: None,
                gamecube_gamehacking_generated: None,
                bsfree_gamecube_generated: None,

                bsfree_wii_generated: None,
            },
            Err(error) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive_path),
                    ActivityOutcome::Failed,
                    format!("Install preview failed: {}", error.detail),
                ));
                CheatPreviewResponse {
                    key: key.clone(),
                    outcome: CheatPreviewOutcome::Failed(CheatPreviewFailure::XeniaInstallPlan(
                        error,
                    )),
                    materialized: None,
                    generated: None,
                    dolphin_generated: None,
                    xenia_generated: None,
                    pcsx2_generated: None,
                    gamecube_gamehacking_generated: None,
                    bsfree_gamecube_generated: None,

                    bsfree_wii_generated: None,
                }
            }
        };
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        workflow.preview_request = Some(key);
        workflow.preview = CheatStepResource::Ready(message);
        workflow.transaction = CheatTransactionState::Idle;
    }

    fn start_generated_cheat_preview(&mut self, context: egui::Context) {
        let Some(workflow) = self.cheat_workflow.as_ref() else {
            return;
        };
        let Some(selection) = workflow.candidate_selection.as_ref() else {
            return;
        };
        let Some(destination_root) =
            selected_retroarch_cheat_root(workflow, &self.retroarch_profiles)
        else {
            return;
        };
        let Some(key) =
            workflow
                .candidates_request
                .clone()
                .or_else(|| match &workflow.candidates {
                    CheatStepResource::Ready(stage) => Some(stage.key.clone()),
                    _ => None,
                })
        else {
            return;
        };

        let entries = match selection.selection.resolve(&selection.loaded.document) {
            Ok(entries) => entries,
            Err(error) => {
                let archive = workflow.archive_path.clone();
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive),
                    ActivityOutcome::Rejected,
                    format!("Install preview blocked: {}", error.detail),
                ));
                return;
            }
        };

        let destination_request = CheatDestinationRequest {
            profile_cheat_root: destination_root.clone(),
            platform: workflow.platform.clone(),
            content_basename: cheat_content_basename(workflow),
            playlist_name: None,
            catalogue_name: selection.candidate.display_name.clone(),
        };
        let match_strength = match match_strength_for_candidate(&selection.candidate) {
            Ok(strength) => strength,
            Err(error) => {
                let archive = workflow.archive_path.clone();
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive),
                    ActivityOutcome::Rejected,
                    format!("Install preview blocked: {}", error.detail),
                ));
                return;
            }
        };
        let staging_root = match default_generated_cheat_staging_root() {
            Ok(root) => root,
            Err(message) => {
                let archive = workflow.archive_path.clone();
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    Some(archive),
                    ActivityOutcome::Failed,
                    message,
                ));
                return;
            }
        };
        let archive_path = workflow.archive_path.clone();
        let platform = workflow.platform.clone();
        let candidate_display_name = selection.candidate.display_name.clone();
        let identity = format!(
            "retroarch-catalogue:{}:{}",
            selection.candidate.catalogue_relative_path, selection.loaded.digest
        );
        let comments = vec![format!(
            "Source catalogue file: {}",
            selection.candidate.catalogue_relative_path
        )];

        let worker_key = key.clone();
        let (sender, receiver) = mpsc::channel();
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        workflow.preview_request = Some(key);
        workflow.preview = CheatStepResource::Loading { receiver };
        workflow.transaction = CheatTransactionState::Idle;
        self.history.record(HistoryEntry::new(
            ActivityAction::CheatPreview,
            Some(archive_path.clone()),
            ActivityOutcome::Started,
            format!(
                "Generating an install preview for {} selected cheat(s).",
                entries.len()
            ),
        ));
        thread::spawn(move || {
            let response = (|| {
                let destination = resolve_cheat_destination(&destination_request)?;
                let staged = stage_generated_cheat_file(
                    &staging_root,
                    destination
                        .file_name
                        .strip_suffix(".cht")
                        .unwrap_or(&destination.file_name),
                    &entries,
                    &comments,
                )?;
                let preview = build_cheat_install_preview(&CheatInstallPreviewRequest {
                    selected_archive: archive_path.clone(),
                    platform,
                    verified_identity: identity,
                    destination: destination.clone(),
                    profile_cheat_root: destination_request.profile_cheat_root.clone(),
                    staged: staged.clone(),
                    match_strength,
                })?;
                Ok::<_, CheatInstallPlanError>((preview, destination, staged, staging_root))
            })();
            let message = match response {
                Ok((preview, destination, staged, staging_root)) => CheatPreviewResponse {
                    key: worker_key,
                    outcome: CheatPreviewOutcome::Ready(preview.report),
                    materialized: None,
                    generated: Some(GeneratedCheatInstall {
                        staging_root,
                        destination,
                        staged,
                        candidate_display_name,
                    }),
                    dolphin_generated: None,
                    xenia_generated: None,
                    pcsx2_generated: None,
                    gamecube_gamehacking_generated: None,
                    bsfree_gamecube_generated: None,

                    bsfree_wii_generated: None,
                },
                Err(error) => CheatPreviewResponse {
                    key: worker_key,
                    outcome: CheatPreviewOutcome::Failed(CheatPreviewFailure::InstallPlan(error)),
                    materialized: None,
                    generated: None,
                    dolphin_generated: None,
                    xenia_generated: None,
                    pcsx2_generated: None,
                    gamecube_gamehacking_generated: None,
                    bsfree_gamecube_generated: None,

                    bsfree_wii_generated: None,
                },
            };
            let _ = sender.send(Ok(message));
            context.request_repaint();
        });
    }

    /// Applies one picker edit and invalidates anything downstream of it.
    /// A preview built from a different selection must never survive a
    /// change to that selection.
    fn update_cheat_selection(&mut self, edit: impl FnOnce(&mut CheatSelection)) {
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        let Some(selection) = workflow.candidate_selection.as_mut() else {
            return;
        };
        edit(&mut selection.selection);
        workflow.preview = CheatStepResource::NotLoaded;
        workflow.preview_request = None;
        workflow.transaction = CheatTransactionState::Idle;
    }

    /// Stage 9: rolls the completed install back through the same
    /// journal-backed machinery History & Logs uses, so there is exactly
    /// one rollback implementation.
    fn start_cheat_install_rollback(&mut self, context: egui::Context) {
        let Some(workflow) = self.cheat_workflow.as_ref() else {
            return;
        };
        let CheatTransactionState::Result { result, .. } = &workflow.transaction else {
            return;
        };
        let Some(journal_path) = result.journal_path.clone() else {
            self.history.record(HistoryEntry::new(
                ActivityAction::CheatInstall,
                Some(workflow.archive_path.clone()),
                ActivityOutcome::Rejected,
                "Undo unavailable: this install did not create an undo record.",
            ));
            return;
        };
        let destination_root = PathBuf::from(&result.journal.destination_root.display);
        let archive = workflow.archive_path.clone();
        self.history.record(HistoryEntry::new(
            ActivityAction::CheatInstall,
            Some(archive),
            ActivityOutcome::Started,
            format!(
                "Rollback requested for install '{}'.",
                result.journal.operation_id
            ),
        ));
        // Phase 4 fix: undoing a change requires an explicit Review-then-
        // Confirm step (SharedRollbackState::Review) - a deliberate safety
        // pattern this codebase already uses for every apply-style action,
        // not something to skip. Gamer View has no confirm-dialog UI of
        // its own for it (building one would be new-feature scope, not a
        // polish pass), so - exactly like the existing "Open Advanced
        // View's Mount page to resolve this" precedent for a blocked
        // mount - this switches into Advanced View so the already-built
        // review screen is actually visible. Without also setting
        // `ui_mode` here, this used to silently update `self.view` while
        // still rendering Gamer View, which never reads it: a click with
        // no visible effect at all.
        self.ui_mode = GuiMode::AdvancedView;
        save_gui_mode(self.ui_mode);
        self.view = MainView::HistoryLogs;
        self.feedback = Some(ActionFeedback {
            succeeded: true,
            message: "Opening your undo history so you can review and confirm this change."
                .to_string(),
            cleanup: None,
            warning: None,
            more_information: None,
        });
        self.start_shared_rollback_preview(context, journal_path, destination_root);
    }

    /// Phase 5: "Review" on a Gamer View game whose platform couldn't be
    /// confidently identified. Keeps the exact same game selected (so
    /// Library's Game Details area opens already showing its real
    /// identity/evidence detail, not a blank/generic page) while
    /// switching to the mode that can actually render it - the identical
    /// select-then-switch shape `open_cheats_mods_workspace` and the
    /// Phase 4 Undo fix both already use.
    fn review_identity(&mut self, archive_path: PathBuf) {
        self.archive_context.select_only(archive_path);
        self.ui_mode = GuiMode::AdvancedView;
        save_gui_mode(self.ui_mode);
        self.navigate_to_library_tab(LibraryTab::Archives);
    }

    /// "Open Emulator Setup" from a Gamer View `NeedsSetup` card: keep the
    /// same game selected and switch to Advanced View's Emulator Setup
    /// page. Same select-then-navigate shape as `review_identity`; no new
    /// plumbing and nothing about the game changes. `focus` records which
    /// repair card the page should scroll into view once (consumed by
    /// `show_emulator_setup_page` with `take()`); sidebar/Home navigation
    /// never sets it.
    fn open_emulator_setup_for(&mut self, archive_path: PathBuf, focus: EmulatorSetupFocus) {
        self.archive_context.select_only(archive_path);
        self.ui_mode = GuiMode::AdvancedView;
        save_gui_mode(self.ui_mode);
        self.emulator_setup_focus = Some(focus);
        self.navigate_to_main_view(MainView::EmulatorSetup);
    }

    /// Render the focused archive's complete Game Details surface.  Library
    /// owns the selection now; this method is shared with the retained
    /// internal Selected compatibility route so there is still only one
    /// renderer and one set of readiness/evidence actions.
    fn show_game_details(
        &mut self,
        context: &egui::Context,
        ui: &mut egui::Ui,
        archive_actions_blocked: bool,
        archive_action_block_reason: Option<&'static str>,
    ) -> Option<MountPageAction> {
        if let Some(path) = self.archive_context.focused.clone() {
            let should_load_evidence = match &self.selected_evidence {
                selected_evidence_page::SelectedEvidenceState::Loading {
                    path: loading_path,
                    ..
                } => loading_path != &path,
                selected_evidence_page::SelectedEvidenceState::Ready { report, .. } => {
                    report.path != path
                }
                selected_evidence_page::SelectedEvidenceState::Idle => true,
                selected_evidence_page::SelectedEvidenceState::Error {
                    path: error_path, ..
                } => error_path != &path,
            };
            if should_load_evidence {
                self.start_selected_evidence_load(context.clone(), path);
            }
        }
        self.maybe_start_selected_evidence_enrichment(context);
        if matches!(
            self.dolphin_local_profiles,
            DolphinLocalProfilesState::NotScanned
        ) {
            self.start_dolphin_local_profile_scan(context.clone());
        }
        if matches!(
            self.pcsx2_launch_profiles,
            Pcsx2LaunchProfilesState::NotScanned
        ) {
            self.start_pcsx2_launch_profile_scan(context.clone());
        }
        if matches!(
            self.pcsx2_firmware_evidence,
            Pcsx2FirmwareEvidenceState::NotLoaded
        ) {
            self.start_pcsx2_firmware_evidence_load(context.clone());
        }
        if matches!(self.flycast_profiles, FlycastProfilesState::NotScanned) {
            self.start_flycast_profile_scan(context.clone());
        }
        let live = match &self.state {
            LoadState::Ready(data) => Some(data.as_ref()),
            _ => None,
        };
        let action = show_selected_page(
            ui,
            live,
            SelectedPageViewState {
                selected_archive: self.archive_context.focused.as_deref(),
                selected_count: self.archive_context.selected.len(),
                retroarch_profiles: &self.retroarch_profiles,
                busy: archive_actions_blocked,
                block_reason: archive_action_block_reason,
            },
        );
        ui.add_space(crate::ui::theme::SECTION_GAP);
        self.show_romm_game_panel(context, ui);
        ui.add_space(crate::ui::theme::SECTION_GAP);
        let evidence_action = selected_evidence_page::show_selected_evidence_panel(
            ui,
            self.ui_mode == GuiMode::AdvancedView,
            self.archive_context.focused.as_deref(),
            &self.selected_evidence,
        );
        self.handle_selected_evidence_action(context, evidence_action);
        ui.add_space(crate::ui::theme::SECTION_GAP);
        let live_for_launch_readiness = match &self.state {
            LoadState::Ready(data) => Some(data.as_ref()),
            _ => None,
        };
        match &self.flycast_profiles {
            FlycastProfilesState::Scanning { .. } => {
                ui.label("Checking Flycast installation and Dreamcast BIOS readiness…");
            }
            FlycastProfilesState::Error(message) => {
                widgets::banner(
                    ui,
                    "Flycast readiness could not be checked",
                    message,
                    widgets::StatusTone::Warning,
                );
            }
            FlycastProfilesState::NotScanned | FlycastProfilesState::Ready(_) => {}
        }
        let launch_readiness_input = self.build_launch_readiness_input(live_for_launch_readiness);
        if self.launch_retroarch.poll() || self.launch_retroarch.is_active() {
            ui.ctx().request_repaint();
        }
        if self.launch_dolphin.poll() || self.launch_dolphin.is_active() {
            ui.ctx().request_repaint();
        }
        if self.launch_pcsx2.poll() || self.launch_pcsx2.is_active() {
            ui.ctx().request_repaint();
        }
        if self.launch_standalone.poll() || self.launch_standalone.is_active() {
            ui.ctx().request_repaint();
        }
        launch_readiness_page::show_launch_readiness_panel(
            ui,
            &launch_readiness_input,
            &mut self.launch_retroarch,
            &mut self.launch_dolphin,
            &mut self.launch_pcsx2,
            &mut self.launch_standalone,
        );
        ui.add_space(crate::ui::theme::SECTION_GAP);
        let identity_sources_action = identity_sources_page::show_identity_sources_panel(
            ui,
            self.ui_mode == GuiMode::AdvancedView,
            &self.identity_sources,
        );
        self.handle_identity_sources_action(context, identity_sources_action);
        ui.add_space(crate::ui::theme::SECTION_GAP);
        let plan_preview_action = plan_preview_page::show_plan_preview_panel(
            ui,
            self.ui_mode == GuiMode::AdvancedView,
            self.archive_context.focused.as_deref(),
            &self.plan_preview,
        );
        self.handle_plan_preview_action(context, plan_preview_action);
        ui.add_space(crate::ui::theme::SECTION_GAP);
        let rpcs3_action = rpcs3_page::show_rpcs3_panel(
            ui,
            self.ui_mode == GuiMode::AdvancedView,
            None,
            &self.rpcs3_status,
        );
        self.handle_rpcs3_action(context, rpcs3_action);
        ui.add_space(crate::ui::theme::SECTION_GAP);
        let focused_archive = self.archive_context.focused.clone();
        self.invalidate_pcsx2_status_if_selection_changed(focused_archive.as_deref());
        let verified_ps2_serial = self
            .cheat_workflow
            .as_ref()
            .and_then(pcsx2_identity_for_workflow)
            .and_then(|id| id.serial);
        let pcsx2_action = pcsx2_page::show_pcsx2_panel(
            ui,
            self.ui_mode == GuiMode::AdvancedView,
            verified_ps2_serial.as_deref(),
            &self.pcsx2_status,
        );
        self.handle_pcsx2_action(context, pcsx2_action);
        Some(action).flatten()
    }

    fn review_cheat_apply(&mut self) {
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        if !matches!(
            workflow.adapter,
            CheatEmulatorAdapter::RetroArch
                | CheatEmulatorAdapter::Pcsx2
                | CheatEmulatorAdapter::Dolphin
                | CheatEmulatorAdapter::Xenia
        ) {
            return;
        }
        let CheatStepResource::Ready(response) = &workflow.preview else {
            return;
        };
        let CheatPreviewOutcome::Ready(report) = &response.outcome else {
            return;
        };
        // The approved source root differs by path: a whole-file catalogue
        // install is approved against the immutable snapshot it came from,
        // while a generated selected-cheat/selected-code install (RetroArch,
        // Dolphin, or Xenia) is approved against the private staging root
        // its bytes were written into.
        let Some(approved_source_root) = response
            .generated
            .as_ref()
            .map(|generated| generated.staging_root.clone())
            .or_else(|| {
                response
                    .dolphin_generated
                    .as_ref()
                    .map(|generated| generated.staging_root.clone())
            })
            .or_else(|| {
                response
                    .xenia_generated
                    .as_ref()
                    .map(|generated| generated.staging_root.clone())
            })
            .or_else(|| {
                response
                    .pcsx2_generated
                    .as_ref()
                    .map(|generated| generated.staging_root.clone())
            })
            .or_else(|| {
                response
                    .gamecube_gamehacking_generated
                    .as_ref()
                    .map(|generated| generated.staging_root.clone())
            })
            .or_else(|| {
                response
                    .bsfree_gamecube_generated
                    .as_ref()
                    .map(|generated| generated.staging_root.clone())
            })
            .or_else(|| {
                response
                    .bsfree_wii_generated
                    .as_ref()
                    .map(|generated| generated.staging_root.clone())
            })
            .or_else(|| {
                response
                    .materialized
                    .as_ref()
                    .map(|materialized| materialized.snapshot_root.clone())
            })
        else {
            return;
        };
        let profile_id = match workflow.adapter {
            CheatEmulatorAdapter::RetroArch => workflow.selected_profile_id.as_deref(),
            CheatEmulatorAdapter::Dolphin => workflow.selected_dolphin_profile_id.as_deref(),
            CheatEmulatorAdapter::Xenia => workflow.selected_xenia_profile_id.as_deref(),
            CheatEmulatorAdapter::Pcsx2 => workflow.selected_pcsx2_profile_id.as_deref(),
            CheatEmulatorAdapter::Unsupported => None,
        };
        let Some(profile_id) = profile_id else {
            return;
        };
        match build_shared_transaction_plan(
            report,
            profile_id,
            workflow.source_mode.label(),
            &approved_source_root,
        ) {
            Ok(mut plan) => {
                if let Some(generated) = &response.gamecube_gamehacking_generated {
                    let expected_managed_names = archivefs_core::patch_manager::managed_names(
                        &parse_dolphin_ini(&generated.staged.contents),
                    )
                    .into_iter()
                    .collect();
                    if let Err(error) = require_dolphin_managed_gamehacking_verification(
                        &mut plan,
                        expected_managed_names,
                    ) {
                        self.history.record(HistoryEntry::new(
                            ActivityAction::CheatPreview,
                            Some(workflow.archive_path.clone()),
                            ActivityOutcome::Rejected,
                            format!(
                                "GameCube live-target verification plan blocked: {}",
                                error.detail
                            ),
                        ));
                        return;
                    }
                }
                if let Some(generated) = &response.bsfree_gamecube_generated {
                    let expected_managed_names = archivefs_core::patch_manager::managed_names(
                        &parse_dolphin_ini(&generated.staged.contents),
                    )
                    .into_iter()
                    .collect();
                    if let Err(error) = require_dolphin_managed_gamehacking_verification(
                        &mut plan,
                        expected_managed_names,
                    ) {
                        self.history.record(HistoryEntry::new(
                            ActivityAction::CheatPreview,
                            Some(workflow.archive_path.clone()),
                            ActivityOutcome::Rejected,
                            format!(
                                "BSFree live-target verification plan blocked: {}",
                                error.detail
                            ),
                        ));
                        return;
                    }
                }
                workflow.transaction = CheatTransactionState::Review {
                    key: response.key.clone(),
                    plan,
                    replacement_approved: false,
                };
            }
            Err(error) => self.history.record(HistoryEntry::new(
                ActivityAction::CheatPreview,
                Some(workflow.archive_path.clone()),
                ActivityOutcome::Rejected,
                format!("Shared apply review blocked: {}", error.detail),
            )),
        }
    }

    fn refresh_shared_history(&mut self, context: egui::Context) {
        let history_root = match default_shared_history_root() {
            Ok(path) => path,
            Err(error) => {
                self.shared_history = SharedHistoryState::Failed(error.detail);
                return;
            }
        };
        let (sender, receiver) = mpsc::channel();
        self.shared_history = SharedHistoryState::Loading { receiver };
        self.history.record(HistoryEntry::new(
            ActivityAction::CheatPreview,
            None,
            ActivityOutcome::Started,
            "Refreshing bounded shared transaction history.",
        ));
        thread::spawn(move || {
            let report = discover_shared_apply_history(&history_root);
            let _ = sender.send(Ok(report));
            context.request_repaint();
        });
    }

    fn poll_shared_history(&mut self) {
        let SharedHistoryState::Loading { receiver } = &self.shared_history else {
            return;
        };
        match receiver.try_recv() {
            Ok(Ok(report)) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    None,
                    ActivityOutcome::Completed,
                    format!(
                        "Shared transaction history refreshed: {} journal(s), {} warning(s).",
                        report.journals.len(),
                        report.warnings.len()
                    ),
                ));
                self.shared_history = SharedHistoryState::Ready(report);
            }
            Ok(Err(message)) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatPreview,
                    None,
                    ActivityOutcome::Failed,
                    format!("Shared transaction history refresh failed: {message}"),
                ));
                self.shared_history = SharedHistoryState::Failed(message);
            }
            Err(TryRecvError::Empty) => {}
            Err(TryRecvError::Disconnected) => {
                self.shared_history = SharedHistoryState::Failed(
                    "Transaction history worker stopped unexpectedly.".to_string(),
                );
            }
        }
    }

    fn start_shared_rollback_preview(
        &mut self,
        context: egui::Context,
        journal_path: PathBuf,
        destination_root: PathBuf,
    ) {
        let Ok(history_root) = default_shared_history_root() else {
            self.shared_rollback =
                SharedRollbackState::Failed("Managed history root is unavailable.".to_string());
            return;
        };
        let Ok(backup_root) = default_shared_backup_root() else {
            self.shared_rollback =
                SharedRollbackState::Failed("Managed backup root is unavailable.".to_string());
            return;
        };
        let (sender, receiver) = mpsc::channel();
        self.shared_rollback = SharedRollbackState::Previewing { receiver };
        self.history.record(HistoryEntry::new(
            ActivityAction::CheatPreview,
            None,
            ActivityOutcome::Started,
            "Rollback preview started; no files are being changed.",
        ));
        thread::spawn(move || {
            let preview = preview_shared_rollback(&journal_path, &destination_root, &backup_root);
            let _ = sender.send(Ok((preview, history_root, backup_root)));
            context.request_repaint();
        });
    }

    fn start_shared_rollback(&mut self, context: egui::Context) {
        let state = std::mem::replace(&mut self.shared_rollback, SharedRollbackState::Idle);
        let SharedRollbackState::Review {
            preview,
            history_root,
            backup_root,
        } = state
        else {
            self.shared_rollback = state;
            return;
        };
        if !preview.available {
            self.shared_rollback = SharedRollbackState::Review {
                preview,
                history_root,
                backup_root,
            };
            return;
        }
        let options = SharedRollbackOptions {
            confirmation: SharedRollbackConfirmation {
                preview_id: preview.preview_id.clone(),
                approved: true,
            },
            rollback_operation_id: generate_shared_operation_id(),
            timestamp_unix_seconds: SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .map(|duration| duration.as_secs())
                .unwrap_or(0),
            history_root,
            backup_root,
        };
        let (sender, receiver) = mpsc::channel();
        self.shared_rollback = SharedRollbackState::Applying { receiver };
        self.history.record(HistoryEntry::new(
            ActivityAction::CheatPreview,
            None,
            ActivityOutcome::Started,
            format!(
                "Rollback '{}' started after exact preview confirmation.",
                options.rollback_operation_id
            ),
        ));
        thread::spawn(move || {
            let result = execute_shared_rollback(&preview, &options);
            let _ = sender.send(Ok(result));
            context.request_repaint();
        });
    }

    fn poll_shared_rollback(&mut self) {
        match &self.shared_rollback {
            SharedRollbackState::Previewing { receiver } => match receiver.try_recv() {
                Ok(Ok((preview, history_root, backup_root))) => {
                    self.history.record(HistoryEntry::new(
                        ActivityAction::CheatPreview,
                        None,
                        if preview.available {
                            ActivityOutcome::Completed
                        } else {
                            ActivityOutcome::Rejected
                        },
                        if preview.available {
                            "Rollback preview completed and is available."
                        } else {
                            "Rollback preview completed and is blocked."
                        },
                    ));
                    self.shared_rollback = SharedRollbackState::Review {
                        preview,
                        history_root,
                        backup_root,
                    };
                }
                Ok(Err(message)) => self.shared_rollback = SharedRollbackState::Failed(message),
                Err(TryRecvError::Empty) => {}
                Err(TryRecvError::Disconnected) => {
                    self.shared_rollback = SharedRollbackState::Failed(
                        "Rollback preview worker stopped unexpectedly.".to_string(),
                    );
                }
            },
            SharedRollbackState::Applying { receiver } => match receiver.try_recv() {
                Ok(Ok(result)) => {
                    self.history.record(HistoryEntry::new(
                        ActivityAction::CheatPreview,
                        None,
                        if result.status == SharedApplyStatus::Success {
                            ActivityOutcome::Completed
                        } else {
                            ActivityOutcome::Failed
                        },
                        format!("Rollback finished with {:?}.", result.status),
                    ));
                    if result.status == SharedApplyStatus::Success
                        && let Some(workflow) = self.cheat_workflow.as_mut()
                        && matches!(
                            &workflow.transaction,
                            CheatTransactionState::Result { result: apply, .. }
                                if apply.journal.operation_id == result.preview.original_operation_id
                        )
                    {
                        // The selected provider state was built from the
                        // exact pre-apply destination that rollback just
                        // restored. Return to it instead of leaving a stale
                        // "Installed successfully / Undo" card behind.
                        workflow.transaction = CheatTransactionState::Idle;
                    }
                    self.shared_rollback = SharedRollbackState::Result(result);
                    self.shared_history = SharedHistoryState::NotLoaded;
                }
                Ok(Err(message)) => self.shared_rollback = SharedRollbackState::Failed(message),
                Err(TryRecvError::Empty) => {}
                Err(TryRecvError::Disconnected) => {
                    self.shared_rollback = SharedRollbackState::Failed(
                        "Rollback worker stopped unexpectedly.".to_string(),
                    );
                }
            },
            _ => {}
        }
    }

    fn start_cheat_apply(&mut self, context: egui::Context) {
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        let state = std::mem::replace(&mut workflow.transaction, CheatTransactionState::Idle);
        let CheatTransactionState::Review {
            key,
            plan,
            replacement_approved,
        } = state
        else {
            workflow.transaction = state;
            return;
        };
        if key != cheat_preview_key(workflow)
            || plan.context.selected_archive.to_path_buf().ok().as_ref()
                != Some(&workflow.archive_path)
        {
            return;
        }
        let loose_identity = ready_game_identity(workflow).and_then(|report| {
            report.verified_loose_rom_sha256().map(|digest| {
                (
                    workflow.archive_path.clone(),
                    workflow.platform.clone(),
                    digest.to_string(),
                )
            })
        });
        let history_root = match default_shared_history_root() {
            Ok(path) => path,
            Err(error) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatInstall,
                    Some(workflow.archive_path.clone()),
                    ActivityOutcome::Failed,
                    format!("Apply root unavailable: {}", error.detail),
                ));
                return;
            }
        };
        let backup_root = match default_shared_backup_root() {
            Ok(path) => path,
            Err(error) => {
                self.history.record(HistoryEntry::new(
                    ActivityAction::CheatInstall,
                    Some(workflow.archive_path.clone()),
                    ActivityOutcome::Failed,
                    format!("Backup root unavailable: {}", error.detail),
                ));
                return;
            }
        };
        let operation_id = generate_shared_operation_id();
        let timestamp = SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|duration| duration.as_secs())
            .unwrap_or(0);
        let options = SharedApplyOptions {
            dry_run: false,
            confirmation: Some(SharedApplyConfirmation {
                plan_id: plan.plan_id.clone(),
                general_approved: true,
                replacement_approved,
            }),
            operation_id: operation_id.clone(),
            timestamp_unix_seconds: timestamp,
            current_context: plan.context.clone(),
            history_root,
            backup_root,
        };
        let archive = workflow.archive_path.clone();
        let (sender, receiver) = mpsc::channel();
        workflow.transaction = CheatTransactionState::Applying {
            key: key.clone(),
            receiver,
        };
        workflow.transaction_notice = None;
        self.history.record(HistoryEntry::new(
            ActivityAction::CheatInstall,
            Some(archive),
            ActivityOutcome::Started,
            format!("Shared apply '{operation_id}' started."),
        ));
        thread::spawn(move || {
            if let Some((path, platform, expected_digest)) = loose_identity {
                let current = inspect_catalogued_game_identity(&path, platform.as_deref());
                if current.verified_loose_rom_sha256() != Some(expected_digest.as_str()) {
                    let _ = sender.send(Err(
                        "Loose ROM changed after preview; the approved plan was rejected before writing."
                            .to_string(),
                    ));
                    context.request_repaint();
                    return;
                }
            }
            let result = execute_shared_apply(&plan, &options);
            let _ = sender.send(Ok(result));
            context.request_repaint();
        });
    }

    fn open_cheat_archive_picker(&mut self) {
        let adapter_platform =
            self.cheat_workflow
                .as_ref()
                .and_then(|workflow| match workflow.adapter {
                    CheatEmulatorAdapter::Dolphin => workflow
                        .platform
                        .as_ref()
                        .filter(|platform| matches!(platform.as_str(), "GameCube" | "Wii"))
                        .cloned()
                        .or_else(|| Some("GameCube".to_string())),
                    CheatEmulatorAdapter::Xenia => Some("Xbox360".to_string()),
                    CheatEmulatorAdapter::Pcsx2 => Some("PS2".to_string()),
                    _ => self.library_filters.platform.clone(),
                });
        self.library_filters.platform = adapter_platform.clone();
        self.cheat_archive_picker = Some(CheatArchivePickerState::for_current(
            self.cheat_workflow
                .as_ref()
                .map(|workflow| workflow.archive_path.as_path()),
            adapter_platform,
        ));
    }

    /// Applies one explicit picker choice. Also writes the choice back to
    /// `selected_archive`/`selected_archives` (the field Library, Selected,
    /// and Mount all read) so the archive picked here is immediately the
    /// one every other page considers selected too - archive selection is
    /// authoritative and shared, not a Cheats & Mods-only copy. Queue
    /// membership and mount state are untouched.
    fn apply_cheat_archive_choice(&mut self, context: &egui::Context, archive_path: PathBuf) {
        self.confirm_cheat_archive_change = None;
        self.cheat_archive_picker = None;
        let needs_profile_scan = matches!(
            self.retroarch_profiles,
            RetroArchProfilesState::NotScanned | RetroArchProfilesState::Error(_)
        );
        self.archive_context.select_only(archive_path.clone());
        self.open_cheats_mods_workspace(context, archive_path);
        if self.cheat_workflow.is_some() && needs_profile_scan {
            self.start_retroarch_profile_scan(context.clone());
        }
    }

    /// Lists the trusted cheat sources and their cached snapshots in
    /// the background (read-only cache inspection, no network).
    fn start_cheat_source_list(&mut self, context: egui::Context) {
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        let (sender, receiver) = mpsc::channel();
        workflow.source_list = CheatStepResource::Loading { receiver };
        thread::spawn(move || {
            let result = default_cheat_source_cache_root()
                .map_err(|error| error.to_string())
                .and_then(|cache_root| {
                    list_retroarch_cheat_sources(&cache_root).map_err(|error| error.to_string())
                });
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

    fn start_existing_retroarch_library_inspection(&mut self, context: egui::Context) {
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        let Some(profile_id) = workflow.selected_profile_id.clone() else {
            return;
        };
        let destination = match &self.retroarch_profiles {
            RetroArchProfilesState::Ready(discovery) => discovery
                .profiles
                .iter()
                .find(|profile| profile.eligible && profile.profile_id == profile_id)
                .and_then(|profile| profile.cheat_destination_root.as_ref())
                .filter(|path| !path.lossy)
                .map(|path| PathBuf::from(&path.display)),
            _ => None,
        };
        let Some(destination) = destination else {
            workflow.existing_library_profile_id = Some(profile_id);
            workflow.existing_library = CheatStepResource::Failed(
                "The selected profile has no safely resolved cheat destination.".to_string(),
            );
            return;
        };
        let (sender, receiver) = mpsc::channel();
        let platform = workflow.platform.clone().unwrap_or_default();
        let display_name = workflow.display_name.clone();
        workflow.existing_library_profile_id = Some(profile_id);
        workflow.existing_library = CheatStepResource::Loading { receiver };
        thread::spawn(move || {
            let result =
                inspect_retroarch_cheat_library_for_game(&destination, &platform, &display_name);
            let _ = sender.send(Ok(result));
            context.request_repaint();
        });
    }

    fn start_pcsx2_gamehacking_fetch(&mut self, context: egui::Context, force_refresh: bool) {
        let Some(workflow) = self.cheat_workflow.as_ref() else {
            return;
        };
        if workflow.adapter != CheatEmulatorAdapter::Pcsx2
            || matches!(
                workflow.pcsx2_gamehacking,
                CheatStepResource::Loading { .. }
            )
        {
            return;
        }
        let Some(identity) = pcsx2_identity_for_workflow(workflow) else {
            if let Some(workflow) = self.cheat_workflow.as_mut() {
                workflow.pcsx2_gamehacking = CheatStepResource::Failed(
                    "EmuWiz needs a verified local PCSX2 executable CRC before checking the cached GameHacking.org PS2 catalogue."
                        .to_string(),
                );
            }
            return;
        };
        let mut options = match GameHackingFetchOptions::defaults() {
            Ok(options) => options,
            Err(failure) => {
                if let Some(workflow) = self.cheat_workflow.as_mut() {
                    workflow.pcsx2_gamehacking = CheatStepResource::Failed(failure.to_string());
                }
                return;
            }
        };
        options.force_refresh = force_refresh;
        let archive_path = workflow.archive_path.clone();
        let (sender, receiver) = mpsc::channel();
        let Some(workflow) = self.cheat_workflow.as_mut() else {
            return;
        };
        workflow.pcsx2_gamehacking = CheatStepResource::Loading { receiver };
        workflow.preview = CheatStepResource::NotLoaded;
        workflow.preview_request = None;
        workflow.transaction = CheatTransactionState::Idle;
        self.history.record(HistoryEntry::new(
            ActivityAction::CheatSourceRetrieval,
            Some(archive_path),
            ActivityOutcome::Started,
            "Checking one local PS2 game against GameHacking.org.",
        ));
        thread::spawn(move || {
            let provider = GameHackingProvider::default();
            let result = (|| {
                let matched = provider.match_game(&identity, &options)?;
                let Some(game) = matched.game.clone() else {
                    return Ok(Pcsx2GameHackingState {
                        status: matched.status,
                        detail: matched.detail,
                        game: None,
                        match_candidates: matched.candidates,
                        candidates: Vec::new(),
                        selection: Pcsx2CheatSelection::default(),
                        cached_fallback: false,
                    });
                };
                let fetch = provider.fetch_cheats_with_status(&identity, &game, &options)?;
                let cheats = fetch.data;
                let catalogue = provider.catalogue(&identity, &game, &cheats)?;
                let candidates = build_pcsx2_cheat_candidates(&catalogue, &identity);
                Ok(Pcsx2GameHackingState {
                    status: matched.status,
                    detail: matched.detail,
                    game: Some(game),
                    match_candidates: Vec::new(),
                    candidates,
                    selection: Pcsx2CheatSelection::default(),
                    cached_fallback: fetch.cached_fallback,
                })
            })()
            .map_err(|failure: archivefs_core::patch_manager::GameHackingError| {
                failure.to_string()
            });
            let _ = sender.send(result);
            context.request_repaint();
        });
    }

