/// Whether a currently-missing config should be framed as an ordinary
/// first run rather than a possible problem: only when this session has
/// never once seen the config file present and readable. Kept as its own
/// pure predicate (mirroring `library_table_message`/
/// `gamer_empty_list_guidance`) so the distinction is directly testable
/// without an `egui::Ui`.
fn missing_config_is_first_run(config_previously_confirmed: bool) -> bool {
    !config_previously_confirmed
}

fn show_setup_diagnostics(
    ui: &mut egui::Ui,
    state: &DiagnosticsState,
    action_running: bool,
    feedback: Option<&ActionFeedback>,
    refresh_error: Option<&str>,
    has_last_snapshot: bool,
    config_previously_confirmed: bool,
) -> Option<DiagnosticsUiAction> {
    let mut action = None;
    ui.heading("Setup / Diagnostics");
    ui.label("Check configuration, folders, and required system tools before using EmuWiz.");
    ui.add_space(8.0);
    if let Some(error) = refresh_error {
        ui.colored_label(
            ui.visuals().error_fg_color,
            format!("Archive refresh failed: {error}"),
        );
        ui.label("Diagnostics are being refreshed from the current configuration.");
        if has_last_snapshot
            && ui
                .add_enabled(
                    !action_running,
                    egui::Button::new("View Last Known Snapshot"),
                )
                .clicked()
        {
            return Some(DiagnosticsUiAction::ViewLastSnapshot);
        }
        ui.add_space(8.0);
    }
    if let DiagnosticsState::Error { message, .. } = state {
        ui.colored_label(ui.visuals().error_fg_color, message);
        ui.label("Select Refresh Diagnostics to try again.");
        if ui
            .add_enabled(!action_running, egui::Button::new("Refresh Diagnostics"))
            .clicked()
        {
            return Some(DiagnosticsUiAction::Refresh);
        }
        return None;
    }
    let DiagnosticsState::Ready { report, .. } = state else {
        ui.spinner();
        ui.label("Running diagnostics in the background...");
        ui.add_enabled(false, egui::Button::new("Continue to EmuWiz"));
        return None;
    };
    if report.config_missing && report.config_path_error.is_none() {
        if missing_config_is_first_run(config_previously_confirmed) {
            egui::Frame::group(ui.style()).show(ui, |ui| {
                ui.strong("Welcome to EmuWiz");
                ui.label(
                    "EmuWiz is not configured yet - that is expected on a fresh install, not \
                     an error. Select Create Starter Config below to begin, then add a source \
                     folder on the Sources page.",
                );
                ui.label(
                    "DAT Sources and Cheat Sources live on their own pages and start empty; \
                     both are optional. RomM is optional too. Audits are always read-only: \
                     EmuWiz will not rename, move or delete any ROM without a later, \
                     explicit, reviewed action.",
                );
            });
        } else {
            // Not a first run: this session already saw the config file
            // present and readable, and it is now gone. That can be an
            // intentional removal, but it can just as easily mean a real
            // problem (deleted by accident, an unmounted drive, a bug) -
            // so this is never dressed up as an ordinary welcome.
            egui::Frame::group(ui.style()).show(ui, |ui| {
                ui.colored_label(theme::WARNING, "Configuration file is no longer found");
                ui.label(
                    "EmuWiz found your configuration earlier in this session, and it is no \
                     longer present. If you did not remove it intentionally, check whether it \
                     was deleted, moved, or is on a drive that is no longer mounted, before \
                     creating a new one below.",
                );
            });
        }
        ui.add_space(8.0);
    }
    ui.horizontal_wrapped(|ui| {
        ui.strong("Config path:");
        match &report.config_path {
            Some(path) => {
                ui.monospace(path.display().to_string());
                if ui
                    .add_enabled(!action_running, egui::Button::new("Copy Config Path"))
                    .clicked()
                {
                    action = Some(DiagnosticsUiAction::CopyConfigPath);
                }
                if ui
                    .add_enabled(!action_running, egui::Button::new("Open Config Folder"))
                    .clicked()
                {
                    action = Some(DiagnosticsUiAction::OpenConfigFolder);
                }
            }
            None => {
                ui.colored_label(
                    ui.visuals().error_fg_color,
                    report
                        .config_path_error
                        .as_deref()
                        .unwrap_or("Config path could not be resolved."),
                );
            }
        }
    });
    ui.horizontal_wrapped(|ui| {
        if starter_config_available(report)
            && ui
                .add_enabled(!action_running, egui::Button::new("Create Starter Config"))
                .clicked()
        {
            action = Some(DiagnosticsUiAction::CreateStarterConfig);
        }
        if report.can_create_mount_root
            && ui
                .add_enabled(!action_running, egui::Button::new("Create Mount Root"))
                .clicked()
        {
            action = Some(DiagnosticsUiAction::CreateMountRoot);
        }
        if ui
            .add_enabled(!action_running, egui::Button::new("Refresh Diagnostics"))
            .clicked()
        {
            action = Some(DiagnosticsUiAction::Refresh);
        }
        if ui
            .add_enabled(
                !action_running && diagnostics_state_can_continue(state),
                egui::Button::new("Continue to EmuWiz"),
            )
            .clicked()
        {
            action = Some(DiagnosticsUiAction::Continue);
        }
        if action_running {
            ui.spinner();
            ui.label("Setup action running...");
        }
    });
    if let Some(feedback) = feedback {
        ui.colored_label(
            if feedback.succeeded {
                egui::Color32::from_rgb(70, 170, 90)
            } else {
                ui.visuals().error_fg_color
            },
            &feedback.message,
        );
    }
    ui.separator();
    egui::ScrollArea::vertical()
        .id_salt("setup_diagnostics_checks")
        .show(ui, |ui| {
            for check in &report.checks {
                let (state_label, color) = match check.status {
                    SetupDiagnosticStatus::Ready => ("Ready", egui::Color32::from_rgb(70, 170, 90)),
                    // Neither a pass nor a problem: the check did not run.
                    SetupDiagnosticStatus::NotChecked => ("Not checked", theme::muted(ui)),
                    // Expected on a fresh install - informational, not red.
                    SetupDiagnosticStatus::NotConfigured => ("Not configured", theme::muted(ui)),
                    SetupDiagnosticStatus::Warning => {
                        ("Warning", egui::Color32::from_rgb(220, 170, 40))
                    }
                    SetupDiagnosticStatus::Error => ("Error", ui.visuals().error_fg_color),
                };
                egui::Frame::group(ui.style()).show(ui, |ui| {
                    ui.horizontal(|ui| {
                        ui.colored_label(color, state_label);
                        ui.strong(&check.name);
                    });
                    ui.label(&check.detail);
                    if check.status != SetupDiagnosticStatus::Ready {
                        ui.label(format!("Why it matters: {}", check.why_it_matters));
                        ui.label(format!("Next step: {}", check.next_step));
                    }
                });
                ui.add_space(4.0);
            }
        });
    action
}
enum ActivityPanelAction {
    ShowRelatedArchive(PathBuf),
}

fn activity_outcome_tone(outcome: ActivityOutcome) -> widgets::StatusTone {
    match outcome {
        ActivityOutcome::Completed => widgets::StatusTone::Success,
        ActivityOutcome::Failed | ActivityOutcome::Rejected => widgets::StatusTone::Blocked,
        ActivityOutcome::OfflineUsable => widgets::StatusTone::Info,
        ActivityOutcome::Started | ActivityOutcome::Retried | ActivityOutcome::Confirmed => {
            widgets::StatusTone::Active
        }
        ActivityOutcome::Offered | ActivityOutcome::Skipped | ActivityOutcome::Cancelled => {
            widgets::StatusTone::Pending
        }
    }
}

fn activity_summary_entry(history: &OperationHistory) -> Option<&HistoryEntry> {
    history
        .entries()
        .find(|entry| {
            matches!(
                entry.outcome,
                ActivityOutcome::Failed | ActivityOutcome::Rejected
            )
        })
        .or_else(|| history.entries().next())
}

fn show_activity_panel(
    context: &egui::Context,
    history: &mut OperationHistory,
    expanded: &mut bool,
    clipboard: &mut dyn ClipboardBackend,
) -> Option<ActivityPanelAction> {
    let mut action = None;
    // Root cause of the bottom-clipping bug: `TopBottomPanel::bottom` picks
    // this frame's panel height by loading `PanelState` persisted under
    // its *own id* from the previous frame (egui's `panel.rs`), and only
    // falls back to a fresh default the very first time that id is ever
    // shown. Collapsed and expanded here render wildly different content
    // heights (one status row vs. a history list up to ~220px tall plus a
    // button row), but previously both used the *same* id ("activity") -
    // so the frame right after toggling from collapsed to expanded loaded
    // the collapsed height, squeezed the expanded content into it (that
    // content's own clip rect is the panel rect: see egui's `panel.rs`,
    // "If we overflow, don't do so visibly"), and only corrected itself
    // one frame later. A user's screenshot taken in that window - or
    // rendered while the app is between reactive repaints - shows exactly
    // "one line of content" jammed near the screen edge. Giving each
    // visual state its own id keeps their persisted heights from ever
    // contaminating each other, so there is no longer a wrong state to
    // render even transiently.
    let (panel_id, default_height) = if *expanded {
        ("activity_expanded", ACTIVITY_PANEL_EXPANDED_DEFAULT_HEIGHT)
    } else {
        (
            "activity_collapsed",
            ACTIVITY_PANEL_COLLAPSED_DEFAULT_HEIGHT,
        )
    };
    let maximum_height = if *expanded {
        (context.input(|input| input.screen_rect().height()) * 0.28)
            .clamp(120.0, ACTIVITY_PANEL_EXPANDED_DEFAULT_HEIGHT)
    } else {
        ACTIVITY_PANEL_COLLAPSED_DEFAULT_HEIGHT
    };
    egui::TopBottomPanel::bottom(panel_id)
        .resizable(*expanded)
        .default_height(default_height)
        .height_range(ACTIVITY_PANEL_COLLAPSED_DEFAULT_HEIGHT..=maximum_height)
        .show(context, |ui| {
            ui.horizontal(|ui| {
                if widgets::action_button(
                    ui,
                    if *expanded {
                        "Hide activity"
                    } else {
                        "Show activity"
                    },
                    widgets::ActionStyle::Quiet,
                    true,
                )
                .clicked()
                {
                    *expanded = !*expanded;
                }
                widgets::status_badge(
                    ui,
                    format!("{} events", history.entries.len()),
                    widgets::StatusTone::Info,
                );
                if !*expanded && let Some(entry) = activity_summary_entry(history) {
                    widgets::status_badge(
                        ui,
                        entry.outcome.to_string(),
                        activity_outcome_tone(entry.outcome),
                    );
                    ui.add(egui::Label::new(&entry.message).truncate())
                        .on_hover_text(&entry.message);
                }
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    if *expanded
                        && widgets::action_button(
                            ui,
                            "Clear activity history",
                            widgets::ActionStyle::Destructive,
                            !history.entries.is_empty(),
                        )
                        .clicked()
                    {
                        history.clear();
                    }
                });
            });
            if !*expanded {
                return;
            }
            ui.separator();

            if history.entries.is_empty() {
                ui.weak("No recent activity.");
                return;
            }
            egui::ScrollArea::vertical()
                .id_salt("activity_history")
                .max_height(220.0)
                .auto_shrink([false, false])
                .show(ui, |ui| {
                    // Collected as owned data *before* the loop, rather
                    // than iterating `history.entries()` directly, so a
                    // menu item can freely call `history.clear()`/
                    // `history.remove()` without fighting the borrow
                    // checker over a `history` still being iterated.
                    let rows: Vec<(
                        usize,
                        ActivityAction,
                        ActivityOutcome,
                        String,
                        Option<PathBuf>,
                    )> = history
                        .entries()
                        .enumerate()
                        .map(|(index, entry)| {
                            (
                                index,
                                entry.action,
                                entry.outcome,
                                entry.message.clone(),
                                entry.archive_path.clone(),
                            )
                        })
                        .collect();
                    let mut remove_index = None;
                    for (index, activity, outcome, text, archive_path) in &rows {
                        let response = widgets::card(ui, |ui| {
                            widgets::activity_row_header(
                                ui,
                                outcome.to_string(),
                                activity_outcome_tone(*outcome),
                                activity.to_string(),
                                None,
                                |_ui| {},
                            );
                            ui.add(
                                egui::Label::new(text)
                                    .selectable(true)
                                    .wrap()
                                    .sense(egui::Sense::click()),
                            )
                        });
                        ui.add_space(6.0);
                        response.context_menu(|ui| {
                            if ui.button("Copy message").clicked() {
                                let _ = clipboard.set_text(text.clone());
                                ui.close();
                            }
                            if let Some(archive_path) = archive_path {
                                if ui.button("Copy related path").clicked() {
                                    let _ = clipboard.set_text(archive_path.display().to_string());
                                    ui.close();
                                }
                                if ui.button("Show related archive").clicked() {
                                    action = Some(ActivityPanelAction::ShowRelatedArchive(
                                        archive_path.clone(),
                                    ));
                                    ui.close();
                                }
                            }
                            ui.separator();
                            if ui.button("Remove this entry").clicked() {
                                remove_index = Some(*index);
                                ui.close();
                            }
                            if ui.button("Clear activity history").clicked() {
                                history.clear();
                                ui.close();
                            }
                        });
                    }
                    // Deferred to after the loop: removing mid-iteration
                    // would shift every later index out from under `rows`.
                    if let Some(index) = remove_index {
                        history.remove(index);
                    }
                });
        });
    action
}

fn doctor_summary_text(report: &DoctorReport) -> String {
    let passed = report
        .checks
        .iter()
        .filter(|check| check.status == DoctorStatus::Pass)
        .count();
    let warnings = report
        .checks
        .iter()
        .filter(|check| check.status == DoctorStatus::Warn)
        .count();
    let failed = report
        .checks
        .iter()
        .filter(|check| check.status == DoctorStatus::Fail)
        .count();
    format!(
        "{} checks: {passed} passed, {warnings} warnings, {failed} failed · \
         {} archives ({} mounted, {} pending, {} unknown platform)",
        report.checks.len(),
        report.archives_found,
        report.mounted_archives,
        report.pending_archives,
        report.archives_unknown_platform
    )
}

/// The full-report text behind the Doctor page's "Copy Report" - the
/// design's copy-full-details affordance. Plain text, one check per
/// line, so it pastes cleanly into an issue or support request. The
/// design's per-check "Suggested fix" is deliberately absent:
/// `DoctorCheck` carries no suggestion field today, and inventing fixes
/// in the GUI would be untruthful (see the capability matrix's Doctor
/// "Suggested action" row).
fn doctor_report_text(report: &DoctorReport) -> String {
    let mut lines = vec![
        format!("EmuWiz doctor report"),
        format!("Config: {}", report.config_path.display()),
        doctor_summary_text(report),
        String::new(),
    ];
    for check in &report.checks {
        lines.push(format!(
            "[{}] {} — {}",
            check.status, check.name, check.detail
        ));
    }
    if !report.platform_counts.is_empty() {
        lines.push(String::new());
        lines.push("Platform counts:".to_string());
        for (platform, count) in &report.platform_counts {
            lines.push(format!("  {platform}: {count}"));
        }
    }
    lines.join("\n")
}

fn show_doctor_checks_panel(ui: &mut egui::Ui, doctor: Option<&DoctorReport>) {
    let Some(doctor) = doctor else {
        widgets::empty_state(
            ui,
            "Health checks unavailable",
            "Scan the library before running the full EmuWiz health report.",
            None,
        );
        return;
    };
    for status in [DoctorStatus::Fail, DoctorStatus::Warn] {
        for check in doctor.checks.iter().filter(|check| check.status == status) {
            widgets::card(ui, |ui| {
                ui.horizontal_wrapped(|ui| {
                    widgets::status_badge(
                        ui,
                        check.status.to_string(),
                        if status == DoctorStatus::Fail {
                            widgets::StatusTone::Blocked
                        } else {
                            widgets::StatusTone::Warning
                        },
                    );
                    ui.label(egui::RichText::new(&check.name).strong());
                });
                ui.add(egui::Label::new(&check.detail).wrap());
            });
            ui.add_space(6.0);
        }
    }
    let passed = doctor
        .checks
        .iter()
        .filter(|check| check.status == DoctorStatus::Pass)
        .count();
    egui::CollapsingHeader::new(format!("Passed checks ({passed})"))
        .default_open(false)
        .show(ui, |ui| {
            for check in doctor
                .checks
                .iter()
                .filter(|check| check.status == DoctorStatus::Pass)
            {
                ui.horizontal_wrapped(|ui| {
                    widgets::status_badge(ui, "Pass", widgets::StatusTone::Success);
                    ui.strong(&check.name);
                    ui.label(egui::RichText::new(&check.detail).color(theme::muted(ui)));
                });
            }
        });
}

const INSPECTOR_DETAILS_COLUMN_WIDTH: f32 = 300.0;

/// Whether one entry matches the Archive Inspector's current search text
/// (case-insensitive substring against its exact stored name) and
/// classification filter - pure, so it is directly testable without
/// rendering anything, mirroring `health_issue_matches`'s existing
/// convention in this file.
fn inspector_entry_matches(
    entry: &InspectorEntry,
    search_lower: &str,
    classification_filter: Option<InspectorEntryClassification>,
) -> bool {
    if let Some(filter) = classification_filter
        && entry.classification != filter
    {
        return false;
    }
    search_lower.is_empty() || entry.name.to_lowercase().contains(search_lower)
}

/// Filters and sorts the already-inspected entry list without ever
/// mutating it - `entries` is only ever read here, exactly like
/// `visible_health_issue_indices` reads its own `issues` slice.
fn visible_inspector_entry_indices(
    entries: &[InspectorEntry],
    search: &str,
    classification_filter: Option<InspectorEntryClassification>,
    sort_field: InspectorSortField,
    sort_ascending: bool,
) -> Vec<usize> {
    let search_lower = search.trim().to_lowercase();
    let mut indices: Vec<usize> = entries
        .iter()
        .enumerate()
        .filter_map(|(index, entry)| {
            inspector_entry_matches(entry, &search_lower, classification_filter).then_some(index)
        })
        .collect();
    indices.sort_by(|&left, &right| {
        let (left_entry, right_entry) = (&entries[left], &entries[right]);
        let ordering = match sort_field {
            InspectorSortField::Path => left_entry.name.cmp(&right_entry.name),
            InspectorSortField::Size => left_entry
                .uncompressed_size
                .cmp(&right_entry.uncompressed_size),
            InspectorSortField::Classification => {
                left_entry.classification.cmp(&right_entry.classification)
            }
        }
        .then_with(|| left_entry.name.cmp(&right_entry.name));
        if sort_ascending {
            ordering
        } else {
            ordering.reverse()
        }
    });
    indices
}
fn inspector_entry_details_text(entry: &InspectorEntry) -> String {
    match entry.kind {
        InspectorEntryKind::Directory => "Directory".to_string(),
        InspectorEntryKind::File => format!(
            "{} \u{2014} {} \u{2014} compressed {} \u{2014} {}",
            entry.classification.label(),
            format_size(Some(entry.uncompressed_size)),
            format_size(entry.compressed_size),
            entry.compression_method.as_deref().unwrap_or("Unknown"),
        ),
    }
}

/// Renders one Archive Inspector entry row - the same technique
/// `show_data_row` uses for the Library table (a single `Sense::click()`
/// region with `Painter`-painted cell text, never a child widget inside
/// that region), generalised to two columns via the same now-slice-based
/// `cell_index_at`/`hovered_cell_full_text` helpers the Library table
/// itself uses. Selection here is single (`selected: bool`, no
/// multi-select/Ctrl-click) - "Selecting one entry shows its complete
/// details" never needed the Library table's fuller multi-select model.
fn show_inspector_row(
    ui: &mut egui::Ui,
    entry: &InspectorEntry,
    row_height: f32,
    selected: bool,
    widths: &[f32],
) -> egui::Response {
    let spacing = ui.spacing().item_spacing.x;
    let width = widths.iter().sum::<f32>() + spacing * (widths.len().saturating_sub(1) as f32);
    let (_, rect) = ui.allocate_space(egui::vec2(width, row_height));
    let row_id = egui::Id::new("inspector_row").with(&entry.name);
    let mut response = ui.interact(rect, row_id, egui::Sense::click());

    let visuals = ui.visuals();
    if selected {
        ui.painter()
            .rect_filled(rect, 0.0, visuals.selection.bg_fill);
    } else if response.hovered() {
        ui.painter()
            .rect_filled(rect, 0.0, visuals.widgets.hovered.weak_bg_fill);
    }

    let details_text = inspector_entry_details_text(entry);
    let cells: [&str; 2] = [entry.name.as_str(), details_text.as_str()];
    let font_id = egui::TextStyle::Body.resolve(ui.style());
    let color = ui.visuals().text_color();
    let mut x = rect.left();
    for (text, column_width) in cells.iter().zip(widths.iter().copied()) {
        let cell_rect = egui::Rect::from_min_size(
            egui::pos2(x, rect.top()),
            egui::vec2(column_width, row_height),
        );
        ui.painter().with_clip_rect(cell_rect).text(
            egui::pos2(x + 2.0, rect.center().y),
            egui::Align2::LEFT_CENTER,
            *text,
            font_id.clone(),
            color,
        );
        x += column_width + spacing;
    }

    let pointer_x = response.hover_pos().map(|pos| pos.x);
    if let Some(full_text) =
        hovered_cell_full_text(pointer_x, rect.left(), &cells, widths, spacing, |text| {
            ui.fonts_mut(|fonts| {
                fonts
                    .layout_no_wrap(text.to_string(), font_id.clone(), color)
                    .size()
                    .x
            })
        })
    {
        response = response.on_hover_text(full_text.to_string());
    }

    response
}
fn show_archive_inspector_panel(
    ui: &mut egui::Ui,
    state: &mut ArchiveInspectorState,
    clipboard: &mut dyn ClipboardBackend,
) -> bool {
    let close = widgets::show_tools_overlay_header(ui, "Archive Inspector");
    ui.horizontal(|ui| {
        ui.label("Archive:");
        let path_text = state.archive_path.display().to_string();
        ui.add(egui::Label::new(&path_text).selectable(true).wrap());
        if ui.small_button("Copy").clicked() {
            let _ = clipboard.set_text(path_text.clone());
        }
    });
    ui.add_space(4.0);

    match &state.status {
        ArchiveInspectorStatus::Loading { .. } => {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label("Inspecting archive - this runs in the background.");
            });
            return close;
        }
        ArchiveInspectorStatus::Error(message) => {
            ui.colored_label(ui.visuals().error_fg_color, message);
            return close;
        }
        ArchiveInspectorStatus::Ready(_) => {}
    }
    let ArchiveInspectorStatus::Ready(report) = &state.status else {
        unreachable!("every other status already returned above");
    };

    if report.truncated {
        ui.colored_label(
            ui.visuals().warn_fg_color,
            format!(
                "Showing the first {} of {} entries - this view is incomplete. Use a more \
                 specific search to find a particular entry.",
                report.entries.len(),
                report.total_entries_in_archive
            ),
        );
        ui.add_space(2.0);
    }

    ui.horizontal_wrapped(|ui| {
        for classification in InspectorEntryClassification::ALL {
            let count = report
                .entries
                .iter()
                .filter(|entry| entry.classification == classification)
                .count();
            summary_value(ui, classification.label(), count);
        }
    });
    ui.separator();

    ui.horizontal_wrapped(|ui| {
        ui.label("Search path:");
        show_text_edit_with_context_menu(ui, &mut state.search, clipboard, |text_edit| {
            text_edit
                .id_salt("archivefs_inspector_search")
                .desired_width(260.0)
        });
        ui.label("Classification:");
        egui::ComboBox::from_id_salt("inspector_classification_filter")
            .selected_text(
                state
                    .classification_filter
                    .map(InspectorEntryClassification::label)
                    .unwrap_or("All"),
            )
            .show_ui(ui, |ui| {
                ui.selectable_value(&mut state.classification_filter, None, "All");
                for classification in InspectorEntryClassification::ALL {
                    ui.selectable_value(
                        &mut state.classification_filter,
                        Some(classification),
                        classification.label(),
                    );
                }
            });
        ui.label("Sort by:");
        egui::ComboBox::from_id_salt("inspector_sort_field")
            .selected_text(state.sort_field.to_string())
            .show_ui(ui, |ui| {
                for field in [
                    InspectorSortField::Path,
                    InspectorSortField::Size,
                    InspectorSortField::Classification,
                ] {
                    ui.selectable_value(&mut state.sort_field, field, field.to_string());
                }
            });
        ui.checkbox(&mut state.sort_ascending, "Ascending");
    });

    let visible = visible_inspector_entry_indices(
        &report.entries,
        &state.search,
        state.classification_filter,
        state.sort_field,
        state.sort_ascending,
    );
    ui.horizontal_wrapped(|ui| {
        summary_value(ui, "Entries shown", visible.len());
        summary_value(ui, "Total entries", report.entries.len());
    });
    ui.separator();

    if report.entries.is_empty() {
        ui.label("This archive has no entries.");
        return close;
    }
    if visible.is_empty() {
        ui.label("No entries match the current search/filter.");
        return close;
    }

    let row_height = ui
        .text_style_height(&egui::TextStyle::Body)
        .max(ui.spacing().interact_size.y);
    let spacing = ui.spacing().item_spacing.x;

    ui.strong("Entries");
    egui::ScrollArea::horizontal()
        .id_salt("inspector_entries_horizontal")
        .auto_shrink([false, false])
        .show(ui, |ui| {
            let start_of_frame_width = state.path_column_width;
            ui.set_min_width(start_of_frame_width + spacing + INSPECTOR_DETAILS_COLUMN_WIDTH);

            let mut path_header_rect = None;
            ui.horizontal(|ui| {
                let response = ui.add_sized(
                    [start_of_frame_width, row_height],
                    egui::Label::new(egui::RichText::new("Path").strong()),
                );
                path_header_rect = Some(response.rect);
                ui.add_sized(
                    [INSPECTOR_DETAILS_COLUMN_WIDTH, row_height],
                    egui::Label::new(egui::RichText::new("Details").strong()),
                );
            });
            if let Some(path_header_rect) = path_header_rect {
                let handle_rect = egui::Rect::from_min_size(
                    egui::pos2(
                        path_header_rect.right() - COLUMN_RESIZE_HANDLE_WIDTH,
                        path_header_rect.top(),
                    ),
                    egui::vec2(COLUMN_RESIZE_HANDLE_WIDTH, path_header_rect.height()),
                );
                show_column_resize_handle(
                    ui,
                    egui::Id::new("inspector_path_column_resize"),
                    handle_rect,
                    &mut state.path_column_width,
                );
            }
            ui.separator();

            // Re-read after the resize handle, which may have just
            // changed `state.path_column_width` this very frame - the
            // rows below must always paint with *this* frame's width,
            // never a one-frame-stale copy (matches the Library table's
            // identical fix in `show_loaded_data`).
            let widths = [state.path_column_width, INSPECTOR_DETAILS_COLUMN_WIDTH];

            let body_height = ui.available_height().max(row_height);
            egui::ScrollArea::vertical()
                .id_salt("inspector_entries_vertical")
                .max_height(body_height)
                .auto_shrink([false, false])
                .show_rows(ui, row_height, visible.len(), |ui, row_range| {
                    for visible_index in row_range {
                        let entry_index = visible[visible_index];
                        let entry = &report.entries[entry_index];
                        let selected = state.selected_entry.as_deref() == Some(entry.name.as_str());
                        let response = show_inspector_row(ui, entry, row_height, selected, &widths);
                        if response.clicked() {
                            state.selected_entry = Some(entry.name.clone());
                        }
                    }
                });
        });

    let Some(selected_name) = state.selected_entry.clone() else {
        ui.label("Select an entry to view its details.");
        return close;
    };
    let Some(selected_entry) = report
        .entries
        .iter()
        .find(|entry| entry.name == selected_name)
    else {
        return close;
    };

    ui.separator();
    ui.strong("Selected entry");
    egui::Grid::new("inspector_selected_entry_details")
        .num_columns(2)
        .striped(true)
        .show(ui, |ui| {
            detail_row_with_copy(ui, "Path", &selected_entry.name, clipboard);
            detail_row(
                ui,
                "Type",
                match selected_entry.kind {
                    InspectorEntryKind::File => "File",
                    InspectorEntryKind::Directory => "Directory",
                },
            );
            detail_row(ui, "Classification", selected_entry.classification.label());
            detail_row(
                ui,
                "Uncompressed size",
                &format_size(Some(selected_entry.uncompressed_size)),
            );
            detail_row(
                ui,
                "Compressed size",
                &format_size(selected_entry.compressed_size),
            );
            detail_row(
                ui,
                "Compression method",
                selected_entry
                    .compression_method
                    .as_deref()
                    .unwrap_or("Unknown"),
            );
        });

    close
}

fn source_action_log_category(action: &SourceAction) -> ActivityAction {
    match action {
        SourceAction::Add(_) => ActivityAction::SourceAdded,
        SourceAction::SetEnabled { enabled: true, .. } => ActivityAction::SourceEnabled,
        SourceAction::SetEnabled { enabled: false, .. } => ActivityAction::SourceDisabled,
        SourceAction::ScanOne(_) | SourceAction::ScanAll | SourceAction::AssignPlatform { .. } => {
            ActivityAction::SourceScan
        }
        SourceAction::Remove { .. } => ActivityAction::SourceRemoved,
    }
}

fn source_action_path(action: &SourceAction) -> Option<PathBuf> {
    match action {
        SourceAction::Add(path)
        | SourceAction::SetEnabled { path, .. }
        | SourceAction::ScanOne(path)
        | SourceAction::AssignPlatform { path, .. }
        | SourceAction::Remove { path, .. } => Some(path.clone()),
        SourceAction::ScanAll => None,
    }
}

fn source_action_started_message(action: &SourceAction) -> String {
    match action {
        SourceAction::Add(path) => format!("Adding source '{}'.", path.display()),
        SourceAction::SetEnabled {
            path,
            enabled: true,
        } => format!("Enabling source '{}'.", path.display()),
        SourceAction::SetEnabled {
            path,
            enabled: false,
        } => format!("Disabling source '{}'.", path.display()),
        SourceAction::ScanOne(path) => format!("Scanning source '{}'.", path.display()),
        SourceAction::ScanAll => "Scanning all enabled sources.".to_string(),
        SourceAction::AssignPlatform { path, platform } => format!(
            "Assigning {platform} to source '{}' and rescanning compatible entries.",
            path.display()
        ),
        SourceAction::Remove {
            path,
            keep_catalogue: true,
        } => format!(
            "Removing source '{}' (keeping catalogue entries).",
            path.display()
        ),
        SourceAction::Remove {
            path,
            keep_catalogue: false,
        } => format!(
            "Removing source '{}' and its catalogue entries.",
            path.display()
        ),
    }
}

fn source_action_success_message(outcome: &SourceActionOutcome) -> String {
    match outcome {
        SourceActionOutcome::Added(source) => format!(
            "Source added: {}. Use Scan to catalogue it.",
            source.path.display()
        ),
        SourceActionOutcome::SetEnabled(outcome) => match &outcome.scan {
            Some(scan) => format!(
                "Source enabled: {}. Scan found {} archive(s), {} missing.",
                outcome.source.path.display(),
                scan.counts.archives_seen,
                scan.counts.archives_missing
            ),
            None => format!(
                "Source disabled: {}. Catalogue entries were preserved.",
                outcome.source.path.display()
            ),
        },
        SourceActionOutcome::Scanned(summary) => {
            let succeeded = summary.counts.source_folders_scanned;
            let failed = summary.folder_errors.len();
            if failed == 0 {
                format!(
                    "Scan complete: {succeeded} source(s) scanned, {} archive(s) found, {} \
                     missing.",
                    summary.counts.archives_seen, summary.counts.archives_missing
                )
            } else {
                format!(
                    "Scan complete: {succeeded} source(s) succeeded, {failed} failed. Existing \
                     catalogue entries were preserved for the failed source(s)."
                )
            }
        }
        SourceActionOutcome::PlatformAssigned { platform, scan } => format!(
            "Source assigned {platform}. Rescan found {} item(s); compatible Unknown entries were reclassified. {} incompatible item(s) remained visible and Unknown.",
            scan.counts.archives_seen,
            scan.platform_assignment_warnings.len()
        ),
        SourceActionOutcome::Removed(outcome) => match outcome.catalogue_rows_removed {
            Some(count) => format!(
                "Source removed: {}. {count} catalogue row(s) removed.",
                outcome.removed_source.path.display()
            ),
            None => format!(
                "Source removed: {}. Catalogue entries were preserved.",
                outcome.removed_source.path.display()
            ),
        },
    }
}

/// Runs one [`SourceAction`] against the default config/database paths -
/// the production entry point `ArchiveFsApp::start_source_action` runs on
/// a background thread. Every arm calls straight into the same, already
/// tested `archivefs_core` function the CLI's matching `source`/`sources`
/// subcommand calls (see `crates/archivefs-cli/src/main.rs`'s `source
/// add`/`enable`/`disable`/`scan`/`sources scan-all`/`source remove`
/// handlers) - never a second implementation of validation, scanning, or
/// persistence.
fn run_source_action(action: &SourceAction) -> archivefs_core::Result<SourceActionOutcome> {
    match action {
        SourceAction::Add(path) => add_source_folder_default(path).map(SourceActionOutcome::Added),
        SourceAction::SetEnabled { path, enabled } => {
            set_source_folder_enabled_default(path, *enabled).map(SourceActionOutcome::SetEnabled)
        }
        SourceAction::ScanOne(path) => {
            scan_source_folder_default(path).map(SourceActionOutcome::Scanned)
        }
        SourceAction::ScanAll => {
            scan_all_enabled_sources_default().map(SourceActionOutcome::Scanned)
        }
        SourceAction::AssignPlatform { path, platform } => {
            assign_source_platform_default(path, platform).map(|scan| {
                SourceActionOutcome::PlatformAssigned {
                    platform: platform.clone(),
                    scan,
                }
            })
        }
        SourceAction::Remove {
            path,
            keep_catalogue,
        } => remove_source_folder_default(path, *keep_catalogue).map(SourceActionOutcome::Removed),
    }
}

fn run_bsfree_operation(
    operation: &BsFreeOperation,
) -> Result<BsFreeOperationResult, archivefs_core::patch_manager::BsFreeError> {
    let paths = BsFreePaths::at(default_bsfree_source_root()?);
    match operation {
        BsFreeOperation::LoadStatus => inspect_bsfree_source(&paths)
            .map(Box::new)
            .map(BsFreeOperationResult::Status),
        BsFreeOperation::Download => download_bsfree_database(
            &paths,
            &BsFreeDownloadOptions::default(),
            &HttpsCheatSourceTransport::new(),
        )
        .map(|result| BsFreeOperationResult::Status(Box::new(result.status))),
        BsFreeOperation::Import(source) => import_local_bsfree_database(&paths, source)
            .map(|result| BsFreeOperationResult::Status(Box::new(result.status))),
        BsFreeOperation::Validate => validate_installed_bsfree_source(&paths)
            .map(Box::new)
            .map(BsFreeOperationResult::Status),
        BsFreeOperation::SetEnabled(enabled) => set_bsfree_enabled(&paths, *enabled)
            .map(Box::new)
            .map(BsFreeOperationResult::Status),
        BsFreeOperation::Remove => {
            remove_local_bsfree_source(&paths, true)?;
            Ok(BsFreeOperationResult::Removed)
        }
        BsFreeOperation::Search(request) => BsFreeCatalogue::open_installed(&paths)?
            .search_games(request)
            .map(BsFreeOperationResult::Search),
        BsFreeOperation::LoadGame {
            upstream_uid,
            offset,
        } => {
            let catalogue = BsFreeCatalogue::open_installed(&paths)?;
            let game = catalogue.game(*upstream_uid)?.ok_or_else(|| {
                archivefs_core::patch_manager::BsFreeError {
                    kind: archivefs_core::patch_manager::BsFreeErrorKind::Query,
                    message: "BSFree game is no longer present".to_string(),
                }
            })?;
            let cheats = catalogue.cheats(*upstream_uid, PageRequest::cheats(*offset))?;
            Ok(BsFreeOperationResult::Game(game, cheats))
        }
    }
}

fn library_view_action_log_category(action: &LibraryViewAction) -> ActivityAction {
    match action {
        LibraryViewAction::Add { .. } => ActivityAction::LibraryViewAdded,
        LibraryViewAction::Edit { .. } => ActivityAction::LibraryViewEdited,
        LibraryViewAction::SetEnabled { enabled: true, .. } => ActivityAction::LibraryViewEnabled,
        LibraryViewAction::SetEnabled { enabled: false, .. } => ActivityAction::LibraryViewDisabled,
        LibraryViewAction::Preview(_) => ActivityAction::LibraryViewPreview,
        LibraryViewAction::Apply(_) => ActivityAction::LibraryViewApply,
        LibraryViewAction::Repair(_) => ActivityAction::LibraryViewRepair,
        LibraryViewAction::Remove { .. } => ActivityAction::LibraryViewRemoved,
    }
}

fn library_view_action_started_message(action: &LibraryViewAction) -> String {
    match action {
        LibraryViewAction::Add { name, .. } => format!("Adding library view '{name}'."),
        LibraryViewAction::Edit { name, .. } => format!("Saving changes to library view '{name}'."),
        LibraryViewAction::SetEnabled {
            identifier,
            enabled: true,
        } => format!("Enabling library view '{identifier}'."),
        LibraryViewAction::SetEnabled {
            identifier,
            enabled: false,
        } => format!("Disabling library view '{identifier}'."),
        LibraryViewAction::Preview(identifier) => {
            format!("Previewing library view '{identifier}'.")
        }
        LibraryViewAction::Apply(identifier) => format!("Applying library view '{identifier}'."),
        LibraryViewAction::Repair(identifier) => format!("Repairing library view '{identifier}'."),
        LibraryViewAction::Remove {
            identifier,
            keep_definition: true,
        } => format!(
            "Removing managed symlinks for library view '{identifier}' (keeping its definition)."
        ),
        LibraryViewAction::Remove {
            identifier,
            keep_definition: false,
        } => format!("Removing library view '{identifier}' and its managed symlinks."),
    }
}

/// Builds the Apply/Repair feedback message, including the current skip
/// count so a partial RomM result (unresolved platform mappings,
/// collisions) is never worded as a plain, unqualified success - see
/// `library_view_current_skip_count`. `skipped` is `None` only when the
/// post-apply re-preview itself could not run; the message still reports
/// the apply's own outcome truthfully in that case, it just cannot add a
/// skip count.
fn library_view_apply_summary_message(
    verb: &str,
    view_name: &str,
    report: &LibraryViewApplyReport,
    skipped: Option<usize>,
) -> String {
    let base = format!(
        "{verb} '{}': {} created, {} repaired, {} removed, {} unchanged, {} failed",
        view_name, report.created, report.repaired, report.removed, report.unchanged, report.failed
    );
    match skipped {
        Some(0) => format!("{base}, 0 skipped."),
        Some(skipped) => format!(
            "{base}, {skipped} skipped - this view is not fully applied. Unresolved platform \
             mappings or collisions remain; see Preview for details."
        ),
        None => format!("{base}."),
    }
}

fn library_view_action_success_message(outcome: &LibraryViewActionOutcome) -> String {
    match outcome {
        LibraryViewActionOutcome::Added(view) => format!(
            "Library view added: {} -> {}.",
            view.name,
            view.destination_root.display()
        ),
        LibraryViewActionOutcome::Edited(view) => format!("Library view updated: {}.", view.name),
        LibraryViewActionOutcome::SetEnabled(view) => {
            if view.enabled {
                format!("Library view enabled: {}.", view.name)
            } else {
                format!("Library view disabled: {}.", view.name)
            }
        }
        LibraryViewActionOutcome::Previewed { view, plan } => format!(
            "Preview for '{}': {} to create, {} correct, {} to repair, {} to remove, {} \
             collision(s), {} skipped.",
            view.name,
            plan.counts.create,
            plan.counts.correct,
            plan.counts.repair,
            plan.counts.remove,
            plan.counts.collision,
            plan.counts.skip
        ),
        LibraryViewActionOutcome::Applied {
            view,
            report,
            skipped,
        } => library_view_apply_summary_message("Applied", &view.name, report, *skipped),
        LibraryViewActionOutcome::Repaired {
            view,
            report,
            skipped,
        } => library_view_apply_summary_message("Repaired", &view.name, report, *skipped),
        LibraryViewActionOutcome::Removed {
            view,
            report,
            kept_definition,
        } => {
            if *kept_definition {
                format!(
                    "Removed {} managed symlink(s) for '{}'. Its definition was kept.",
                    report.removed, view.name
                )
            } else {
                format!(
                    "Removed {} managed symlink(s) for '{}' and its definition.",
                    report.removed, view.name
                )
            }
        }
    }
}

/// Re-previews `view_id` immediately after an Apply/Repair, purely to read
/// off the resulting plan's `counts.skip` for an honest post-apply summary -
/// never used to decide whether the apply itself succeeded (that already
/// happened, via the existing `apply_library_view_default`/
/// `repair_library_view_default` call), and never fed back into another
/// apply. Uses the same `preview_library_view_default` the Preview button
/// already calls - no second planning implementation. `None` on any error
/// (e.g. the view was concurrently removed) rather than fabricating a count.
fn library_view_current_skip_count(view_id: &str) -> Option<usize> {
    preview_library_view_default(view_id)
        .ok()
        .map(|(_, plan)| plan.counts.skip)
}

/// Runs one [`LibraryViewAction`] against the default config/database
/// paths - the production entry point `ArchiveFsApp::start_library_view_action`
/// runs on a background thread. Every arm calls straight into the same,
/// already-tested `archivefs_core` `*_default` function the CLI's matching
/// `view` subcommand calls (see `crates/archivefs-cli/src/main.rs`'s `view
/// list`/`preview`/`apply`/`repair`/`remove` handlers) - never a second
/// implementation of planning, applying, or persistence.
fn run_library_view_action(action: &LibraryViewAction) -> Result<LibraryViewActionOutcome, String> {
    match action {
        LibraryViewAction::Add {
            name,
            destination_root,
            source_folders,
            platforms,
            profile,
        } => add_library_view_default(
            name.clone(),
            destination_root.clone(),
            source_folders.clone(),
            platforms.clone(),
            LibraryViewLayoutTemplate::PlatformFilename,
            profile.clone(),
        )
        .map(LibraryViewActionOutcome::Added)
        .map_err(|error| error.to_string()),
        LibraryViewAction::Edit {
            identifier,
            name,
            destination_root,
            source_folders,
            platforms,
            profile,
        } => edit_library_view_default(
            identifier,
            name.clone(),
            destination_root.clone(),
            source_folders.clone(),
            platforms.clone(),
            profile.clone(),
        )
        .map(LibraryViewActionOutcome::Edited)
        .map_err(|error| error.to_string()),
        LibraryViewAction::SetEnabled {
            identifier,
            enabled,
        } => set_library_view_enabled_default(identifier, *enabled)
            .map(LibraryViewActionOutcome::SetEnabled)
            .map_err(|error| error.to_string()),
        LibraryViewAction::Preview(identifier) => preview_library_view_default(identifier)
            .map(|(view, plan)| LibraryViewActionOutcome::Previewed { view, plan })
            .map_err(|error| error.to_string()),
        LibraryViewAction::Apply(identifier) => apply_library_view_default(identifier)
            .map(|(view, report)| {
                let skipped = library_view_current_skip_count(&view.id);
                LibraryViewActionOutcome::Applied {
                    view,
                    report,
                    skipped,
                }
            })
            .map_err(|error| error.to_string()),
        LibraryViewAction::Repair(identifier) => repair_library_view_default(identifier)
            .map(|(view, report)| {
                let skipped = library_view_current_skip_count(&view.id);
                LibraryViewActionOutcome::Repaired {
                    view,
                    report,
                    skipped,
                }
            })
            .map_err(|error| error.to_string()),
        LibraryViewAction::Remove {
            identifier,
            keep_definition,
        } => remove_library_view_default(identifier, *keep_definition)
            .map(|(view, report)| LibraryViewActionOutcome::Removed {
                view,
                report,
                kept_definition: *keep_definition,
            })
            .map_err(|error| error.to_string()),
    }
}

/// Mirrors the CLI's `format_source_availability` wording exactly (see
/// `crates/archivefs-cli/src/main.rs`) so the two never disagree - kept
/// as its own small presentation-layer function rather than shared code,
/// exactly like `RowOrigin::label()` already is for library rows.
fn source_availability_label(availability: SourceAvailability) -> &'static str {
    match availability {
        SourceAvailability::Available => "Available",
        SourceAvailability::Unavailable => "Unavailable",
        SourceAvailability::PermissionDenied => "Permission denied",
        SourceAvailability::Disabled => "Disabled",
        SourceAvailability::ScanFailed => "Scan failed",
    }
}

/// A source's actual platform state, derived purely from the archives the
/// snapshot already has catalogued for it (`PersistedArchive::platform`,
/// matched by `PersistedArchive::source_folder_id == SourceFolderView::id`),
/// never a new query, rescan, persisted field, or schema change. This is
/// ground truth from the same data the Library page already shows, not a
/// guess: if every catalogued archive under a source agrees on one
/// platform, that is the source's platform.
#[derive(Debug, Clone, PartialEq, Eq)]
enum SourcePlatformState {
    /// This source has no catalogued archives yet (never scanned, or
    /// scanned and found nothing).
    NotYetKnown,
    /// Archives exist, but none resolved a platform.
    Unknown,
    /// Every catalogued archive agrees on this one platform.
    Single(String),
    /// Every catalogued archive resolved a platform, but not to the same
    /// one - `usize` is the number of distinct platforms found.
    Mixed(usize),
    /// Some archives resolved a platform and some did not.
    Partial { known: i64, unknown: i64 },
}

/// Computes [`SourcePlatformState`] for one source from the snapshot's full
/// archive list - an `O(archives)` scan per source, over data already
/// loaded in memory (never a filesystem rescan; see the type's own doc
/// comment for why no new persistence is needed).
fn source_platform_state(
    view: &SourceFolderView,
    archives: &[PersistedArchive],
) -> SourcePlatformState {
    let Some(source_id) = view.id else {
        return SourcePlatformState::NotYetKnown;
    };
    let mut resolved: Vec<&str> = Vec::new();
    let mut unresolved: i64 = 0;
    for archive in archives {
        if archive.source_folder_id != source_id {
            continue;
        }
        match archive.platform.as_deref() {
            Some(platform) => resolved.push(platform),
            None => unresolved += 1,
        }
    }
    if resolved.is_empty() && unresolved == 0 {
        return SourcePlatformState::NotYetKnown;
    }
    if resolved.is_empty() {
        return SourcePlatformState::Unknown;
    }
    if unresolved > 0 {
        return SourcePlatformState::Partial {
            known: resolved.len() as i64,
            unknown: unresolved,
        };
    }
    let mut distinct = resolved;
    distinct.sort_unstable();
    distinct.dedup();
    match distinct.as_slice() {
        [single] => SourcePlatformState::Single((*single).to_string()),
        many => SourcePlatformState::Mixed(many.len()),
    }
}

/// Simple, human-facing wording for [`SourcePlatformState`] - deliberately
/// avoids "unclassified", "heuristic", and "detected automatically"; a real
/// platform name is shown whenever the catalogued archives actually agree
/// on one. Deliberately just the *value*, with no "Platform:" prefix of
/// its own - the caller (the source card's facts grid) already supplies
/// that as the row's own label column, so prefixing it here as well would
/// render as the literal duplicate "Platform: Platform: X".
fn source_platform_value_label(state: &SourcePlatformState) -> String {
    match state {
        SourcePlatformState::NotYetKnown => "not yet known".to_string(),
        SourcePlatformState::Unknown => "Unknown".to_string(),
        SourcePlatformState::Single(platform) => platform.clone(),
        SourcePlatformState::Mixed(count) => format!("Mixed ({count} platforms)"),
        SourcePlatformState::Partial { known, unknown } => {
            format!("Partial ({known} known, {unknown} unknown)")
        }
    }
}

/// The design's per-archive validation label on the Mount page - a pure
/// mapping from the live `MountState`, so the preview can never disagree
/// with what the batch engine will actually do (`Pending` is the only
/// state `queued_pending_paths` lets through to a mount attempt).
fn mount_validation_label(state: MountState) -> &'static str {
    match state {
        MountState::Pending => "Ready to mount",
        MountState::Mounted => "Already mounted — will be skipped",
        MountState::MountPathExists => "Destination already exists — will be skipped",
        MountState::NotMountable => "Loose ROM · no EmuWiz mount required",
    }
}

/// Drops queued paths whose archive no longer exists in the live
/// snapshot (source removed, rescan, etc.). Deliberately keeps queued
/// archives that are merely no longer `Pending` (mounted meanwhile, or a
/// destination collision) - those stay visible on the Mount page with
/// their skip reason instead of vanishing silently.
fn prune_mount_queue(queue: &mut Vec<PathBuf>, records: &[ArchiveRecord]) {
    queue.retain(|path| {
        records
            .iter()
            .any(|record| record.mount_plan.archive.path == *path)
    });
}

/// The queued paths that a "Mount queue" run will actually attempt - in
/// queue order, `Pending` archives only, mirroring
/// `show_bulk_row_context_menu`'s contract that
/// `mount_all_items_for_paths` is only ever fed genuinely eligible
/// archives.
fn queued_pending_paths(queue: &[PathBuf], records: &[ArchiveRecord]) -> Vec<PathBuf> {
    queue
        .iter()
        .filter(|path| {
            records.iter().any(|record| {
                record.mount_plan.archive.path == **path
                    && record.mount_state == MountState::Pending
                    && record.is_mount_input()
            })
        })
        .cloned()
        .collect()
}

/// Case-insensitive substring match over the fields the Mount page
/// displays (name, platform, archive path, planned destination) - the
/// Mount page's counterpart of the Library's `search_text` matching.
fn mount_row_matches(record: &ArchiveRecord, filter: &str) -> bool {
    let needle = filter.trim().to_lowercase();
    if needle.is_empty() {
        return true;
    }
    format!(
        "{} {} {} {}",
        record.identity.display_name,
        record.identity.platform.as_deref().unwrap_or(""),
        record.mount_plan.archive.path.display(),
        record.mount_plan.mount_path.display()
    )
    .to_lowercase()
    .contains(&needle)
}

/// What the Mount page asks `update` to do - executing a mount goes
/// through the app's own `start_mount_all` (the proven batch engine),
/// never directly from render code.
enum MountPageAction {
    MountQueue,
    Refresh,
    /// Navigate to the Mount page (the Selected page's plain "Open Mounts"
    /// shortcut into the real mount-queue workflow).
    GoToMount,
    /// Open the first-class Cheats & Mods workspace for this exact
    /// archive (the Selected page's entry point).
    OpenCheatsMods(PathBuf),
    /// Start the shared background RetroArch profile scan from the
    /// Selected page's entry section.
    ScanRetroArchProfiles,
}

/// What the user chose in the shared mount-queue confirmation strip.
enum QueueConfirmChoice {
    Mount,
    Cancel,
}

/// The inline "mount the queue" confirmation strip, used by the Mount
/// page's own queue review (`show_mount_page`). The Selected page no longer
/// renders any mount queue at all, so this is not shared with it anymore.
fn show_mount_queue_confirmation(
    ui: &mut egui::Ui,
    attempted: usize,
    busy: bool,
) -> Option<QueueConfirmChoice> {
    let mut choice = None;
    widgets::card(ui, |ui| {
        widgets::status_badge(ui, "Confirmation", widgets::StatusTone::Warning);
        if attempted == 1 {
            ui.strong("Mount 1 queued archive?");
        } else {
            ui.strong(format!("Mount {attempted} queued archives?"));
        }
        ui.label(
            "Only archives that are ready to mount are attempted; already-mounted \
             archives and existing destinations are skipped by the batch engine.",
        );
        ui.horizontal(|ui| {
            if widgets::action_button(
                ui,
                "Mount now",
                widgets::ActionStyle::Primary,
                !busy && attempted > 0,
            )
            .clicked()
            {
                choice = Some(QueueConfirmChoice::Mount);
            }
            if widgets::action_button(ui, "Cancel", widgets::ActionStyle::Quiet, true).clicked() {
                choice = Some(QueueConfirmChoice::Cancel);
            }
        });
    });
    choice
}

/// The Selected page's own view state - a game-details/review surface, not a
/// mount-queue screen. Queue review, manipulation, and the mount-queue
/// confirmation flow live only on the Mount page (`show_mount_page`,
/// `administration_pages.rs`), which already owns that machinery end to end;
/// this page never re-implements or duplicates it, and offers only a plain
/// "Open Mounts" shortcut into the real workflow.
struct SelectedPageViewState<'a> {
    selected_archive: Option<&'a Path>,
    selected_count: usize,
    retroarch_profiles: &'a RetroArchProfilesState,
    busy: bool,
    block_reason: Option<&'a str>,
}

/// Renders the Selected page: a focused game-details/review surface (Cheats
/// & Mods entry point here; identity evidence, launch readiness, identity
/// sources, plan preview, and RPCS3/PCSX2 panels rendered by the caller
/// immediately after this returns). Never renders or manipulates the mount
/// queue - see `SelectedPageViewState`'s own doc.
fn show_selected_page(
    ui: &mut egui::Ui,
    live: Option<&LoadedData>,
    view_state: SelectedPageViewState<'_>,
) -> Option<MountPageAction> {
    let SelectedPageViewState {
        selected_archive,
        selected_count,
        retroarch_profiles,
        busy,
        block_reason,
    } = view_state;
    let mut action = None;
    widgets::page_header_with_icon(
        ui,
        crate::ui::icons::SELECTED,
        "Game Details",
        "Review identity, launch readiness and available actions for this game.",
    );

    widgets::section_header(
        ui,
        "Cheats & Mods",
        Some("Open the dedicated workspace for the archive selected in Library."),
    );
    match selected_archive {
        Some(path) => {
            if widgets::path_value(ui, "Selected archive", path) {
                ui.ctx().copy_text(path.display().to_string());
            }
        }
        None => {
            ui.label("No archive is selected in the Library.");
        }
    }
    let entry_blocker = cheat_entry_blocker(
        selected_archive,
        selected_count,
        live.map(|data| data.records.as_slice()),
        retroarch_profiles,
    );
    ui.horizontal(|ui| {
        if widgets::action_button(
            ui,
            "Open Cheats & Mods",
            widgets::ActionStyle::Secondary,
            entry_blocker.is_none() && !busy,
        )
        .clicked()
            && let Some(path) = selected_archive
        {
            action = Some(MountPageAction::OpenCheatsMods(path.to_path_buf()));
        }
        // The only mount-related affordance this page offers: a plain
        // shortcut into the real Mount page/workflow. No queue is reviewed,
        // built, or confirmed here.
        if widgets::action_button(ui, "Open Mounts", widgets::ActionStyle::Quiet, !busy).clicked() {
            action = Some(MountPageAction::GoToMount);
        }
        if matches!(
            retroarch_profiles,
            RetroArchProfilesState::NotScanned | RetroArchProfilesState::Error(_)
        ) && widgets::action_button(
            ui,
            "Scan for RetroArch profiles",
            widgets::ActionStyle::Quiet,
            !busy,
        )
        .clicked()
        {
            action = Some(MountPageAction::ScanRetroArchProfiles);
        }
    });
    if let Some(reason) = entry_blocker {
        widgets::banner(ui, "Unavailable", reason, widgets::StatusTone::Pending);
    }
    if busy && let Some(reason) = block_reason {
        ui.label(reason);
    }
    action
}

/// What `try_resolve_dolphin_provider_from_local_sources` found, kept
/// distinct from `dolphin_provider` itself because `NotLoaded` alone can no
/// longer distinguish "hasn't looked yet" from "looked locally and found
/// nothing" now that a fruitless local lookup does not fall through to an
/// automatic network request.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
enum DolphinLocalLookupState {
    #[default]
    NotAttempted,
    NoCatalogueInstalled,
    NotInCatalogue,
    RegionMismatch,
    NoUsableCodes {
        warnings: Vec<String>,
    },
}

struct CheatWorkflowState {
    /// Exact-byte identity - the same `ArchiveRecord.mount_plan.archive
    /// .path` identity the rest of the app uses, never a filename.
    archive_path: PathBuf,
    display_name: String,
    normalized_name: String,
    platform: Option<String>,
    region: Option<String>,
    source_root: PathBuf,
    size_bytes: Option<u64>,
    /// The emulator adapter is explicit and independent from archive
    /// selection. PCSX2 is offered only for a canonical PS2 archive.
    adapter: CheatEmulatorAdapter,
    identity_request: Option<GameIdentityRequest>,
    identity: CheatStepResource<(GameIdentityRequest, GameIdentityReport)>,
    preview_request: Option<CheatPreviewRequestKey>,
    preview: CheatStepResource<CheatPreviewResponse>,
    transaction: CheatTransactionState,
    transaction_notice: Option<String>,
    /// The explicitly selected profile. Preselected only when exactly
    /// one eligible profile exists (the CLI's own auto-selection rule);
    /// with several eligible profiles the user must choose - never
    /// silently picked.
    selected_profile_id: Option<String>,
    selected_pcsx2_profile_id: Option<String>,
    /// The PCSX2 profile identity bound to this archive's inventory.
    pcsx2_inventory_profile_id: Option<String>,
    pcsx2_inventory: CheatStepResource<Pcsx2PnachInventory>,
    pcsx2_gamehacking: CheatStepResource<Pcsx2GameHackingState>,
    /// Dolphin-family GameHacking.org coverage. Wii is adapted into this
    /// existing state only after its own identity and safety policy runs.
    gamecube_gamehacking: CheatStepResource<GameCubeGameHackingState>,
    gamecube_gamehacking_request: Option<DolphinGameHackingRequestKey>,
    gamecube_gamehacking_cancellation: Option<Arc<AtomicBool>>,
    gamecube_gamehacking_generation: u64,
    /// True exactly when the current `gamecube_gamehacking` `Failed` state
    /// was classified as `GameHackingErrorKind::CloudflareBlocked` (see
    /// `GAMEHACKING_PROVIDER_CHALLENGE_MESSAGE`) rather than an ordinary
    /// failure - drives the dedicated neutral/blocked banner and hides
    /// Retry, since retrying immediately cannot help and core-side cooldown
    /// gating already prevents hammering a blocked origin.
    gamecube_gamehacking_blocked: bool,
    /// BSFree Archive GameCube coverage in Cheats & Mods: an optional local
    /// SQLite source, matched by platform + title to the selected archive's
    /// verified Dolphin Game ID. Installable only for the proven hex-pair
    /// formats; every other BSFree record stays browseable.
    bsfree_gamecube: CheatStepResource<BsFreeGameCubeGuiState>,
    bsfree_gamecube_cancellation: Option<Arc<AtomicBool>>,
    bsfree_gamecube_generation: u64,
    /// BSFree Wii coverage: the same optional local SQLite source, matched by
    /// platform + title to the archive's verified Dolphin Wii Game ID. Only
    /// the verified hex-pair subset is installable.
    bsfree_wii: CheatStepResource<BsFreeWiiGuiState>,
    bsfree_wii_cancellation: Option<Arc<AtomicBool>>,
    bsfree_wii_generation: u64,
    selected_dolphin_profile_id: Option<String>,
    /// An optional additional Dolphin configuration directory to scan,
    /// typed by the user - covers portable/AppImage installs, which have
    /// no fixed native or Flatpak path EmuWiz can discover on its own.
    /// Never auto-populated; rescanning without it drops nothing already
    /// found under the standard native/Flatpak locations.
    dolphin_explicit_root: String,
    /// The Dolphin profile identity bound to this archive's inventory.
    dolphin_inventory_profile_id: Option<String>,
    dolphin_inventory: CheatStepResource<DolphinGameIniInventory>,
    /// External discovery is bound only to exact archive/game/revision identity.
    /// Dolphin paths enter only when the adapter builds the selection below.
    dolphin_provider_request: Option<DolphinProviderRequestKey>,
    dolphin_provider: CheatStepResource<GeckoProviderFetchResult>,
    dolphin_provider_selection: Option<DolphinProviderSelectionState>,
    dolphin_destination_error: Option<String>,
    /// What the network-free local lookup (catalogue, then cached
    /// single-game result) found when it found nothing usable to show in
    /// `dolphin_provider` - lets the beginner view distinguish "still
    /// looking" (`NotAttempted`, `dolphin_provider` stays `NotLoaded`
    /// briefly) from "looked locally and there is genuinely nothing here"
    /// (any other variant, `dolphin_provider` stays `NotLoaded`
    /// indefinitely since no automatic network request follows).
    dolphin_local_lookup: DolphinLocalLookupState,
    /// The most recent automatic-selection outcome for the Dolphin
    /// profile - drives the beginner view's "using X automatically"
    /// confirmation, the "choose one of N profiles" chooser, or the
    /// setup-needed state. Recomputed whenever `dolphin_profiles`
    /// changes; never recomputed merely because the page re-renders.
    dolphin_profile_selection: Option<EmulatorProfileSelection>,
    /// The profile currently highlighted in the profile chooser dialog,
    /// pending the user's explicit "Use selected profile" confirmation.
    dolphin_profile_choice: Option<String>,
    /// Whether the beginner page's "Details" disclosure is expanded.
    /// Owned here (not egui's own collapsing-header memory) so it is
    /// trivially set from a test fixture and so it can be reset
    /// deliberately whenever the workflow state it discloses changes.
    /// Collapsed (`false`) by default.
    dolphin_details_open: bool,
    /// Whether the beginner install confirmation's "Show exact changes"
    /// disclosure is expanded. Resets to `false` whenever a fresh
    /// confirmation begins (see `start_beginner_install_dolphin`).
    dolphin_show_exact_changes: bool,
    selected_xenia_profile_id: Option<String>,
    /// An explicit Xenia Canary directory typed by the user - the only
    /// way EmuWiz ever learns of a Xenia install, since it has no
    /// single standard location.
    xenia_explicit_root: String,
    xenia_provider_request: Option<XeniaProviderRequestKey>,
    xenia_provider: CheatStepResource<XeniaProviderFetchResult>,
    /// Which of the provider's returned candidate documents the user
    /// picked - Xenia's own dataset legitimately has multiple files per
    /// Title ID (different Title Update/module-hash variants).
    xenia_selected_candidate_index: Option<usize>,
    xenia_selection: Option<XeniaSelectionState>,
    xenia_destination_error: Option<String>,
    /// The most recent automatic-selection outcome for the Xenia Canary
    /// profile - same role as `dolphin_profile_selection`.
    xenia_profile_selection: Option<EmulatorProfileSelection>,
    /// The profile currently highlighted in the profile chooser dialog,
    /// pending the user's explicit "Use selected profile" confirmation.
    xenia_profile_choice: Option<String>,
    /// Xenia's counterpart to `dolphin_details_open`.
    xenia_details_open: bool,
    /// Xenia's counterpart to `dolphin_show_exact_changes`.
    xenia_show_exact_changes: bool,
    /// Independent source mode. Changing it never changes the archive,
    /// profile, destination, or any fetched result retained by another mode.
    source_mode: CheatSourceMode,
    /// The profile identity bound to the current read-only installed-library
    /// inspection. A profile change invalidates only this observation.
    existing_library_profile_id: Option<String>,
    existing_library: CheatStepResource<RetroArchCheatLibraryInspection>,
    /// Step 2: the trusted-source cache listing, loaded in the
    /// background when the workflow opens.
    source_list: CheatStepResource<CheatSourceList>,
    /// Step 2: the most recent catalogue retrieval (network fetch or
    /// offline cached-snapshot reuse). A result whose source no longer
    /// matches `selected_source_id` at receive time is discarded.
    source_fetch: CheatStepResource<CheatSourceFetchResult>,
    /// The explicitly selected trusted source - preselected only when
    /// exactly one enabled trusted source exists (same single-candidate
    /// rule as profiles).
    selected_source_id: Option<String>,
    /// Whether "Fetch / Update catalogue" bypasses the fresh-cache
    /// short-circuit (the CLI's `--force-refresh`). Never applies to
    /// offline reuse.
    fetch_force_refresh: bool,
    /// Stage 4: the ranked candidate cheat files for this exact archive,
    /// bound to the key that produced them.
    candidates: CheatStepResource<CheatCandidateStage>,
    candidates_request: Option<CheatPreviewRequestKey>,
    /// Stage 4 search box, used only when the list is capped.
    candidate_query: String,
    /// Stages 5 and 6: the chosen candidate, its parsed cheats, and the
    /// user's per-cheat choices. Cleared whenever the candidate list is.
    candidate_selection: Option<CheatCandidateSelection>,
    /// A candidate the user chose that could not be opened - kept so the
    /// failure stays on screen instead of silently reverting the choice.
    candidate_load_error: Option<String>,
}

/// One completed candidate match, bound to the exact context that produced
/// it so a stale result can never be shown against a different archive,
/// profile, or catalogue snapshot.
struct CheatCandidateStage {
    key: CheatPreviewRequestKey,
    catalogue_root: PathBuf,
    list: CheatCandidateList,
}

/// The chosen candidate and everything derived from it.
struct CheatCandidateSelection {
    candidate: CheatCandidate,
    loaded: LoadedCandidate,
    selection: CheatSelection,
}

/// What one generated-install preview produced, alongside the shared
/// report. Retained so review, confirmation, and the result view can all
/// name the exact destination and staged bytes the user approved.
#[derive(Clone)]
struct GeneratedCheatInstall {
    staging_root: PathBuf,
    destination: ResolvedCheatDestination,
    staged: StagedCheatFile,
    candidate_display_name: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct DolphinProviderRequestKey {
    archive_path: PathBuf,
    game_id: String,
    revision: u16,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct DolphinGameHackingRequestKey {
    archive_path: PathBuf,
    platform: String,
    game_id: String,
    revision: Option<u16>,
    generation: u64,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum WiiGameHackingFetchMode {
    CacheOnly,
    ExplicitNetworkAllowed,
}

fn dolphin_gamehacking_request_key(
    workflow: &CheatWorkflowState,
    generation: u64,
) -> Option<DolphinGameHackingRequestKey> {
    let report = ready_game_identity(workflow)?;
    let game_id = report.verified_dolphin_game_id()?.to_string();
    let is_wii = workflow.platform.as_deref() == Some("Wii");
    let revision = if is_wii {
        wii_identity_for_workflow(workflow)?.candidate_revision
    } else {
        report.verified_dolphin_revision()
    };
    Some(DolphinGameHackingRequestKey {
        archive_path: workflow.archive_path.clone(),
        platform: if is_wii { "Wii" } else { "GameCube" }.to_string(),
        game_id,
        revision,
        generation,
    })
}

/// Adapter-owned state derived from inert provider results plus the selected
/// Dolphin destination. Provider retrieval never receives either of these paths.
#[derive(Clone)]
struct DolphinProviderSelectionState {
    destination: LoadedDolphinDestination,
    selection: DolphinProviderCodeSelection,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct XeniaProviderRequestKey {
    archive_path: PathBuf,
    title_id: String,
}

/// Adapter-owned state derived from the chosen candidate document plus
/// the real destination file it would install to.
#[derive(Clone)]
struct XeniaSelectionState {
    candidate: XeniaCandidate,
    destination: LoadedXeniaDestination,
    selection: XeniaPatchSelection,
}

/// The Dolphin equivalent of `GeneratedCheatInstall`: the same matched file,
/// re-written with only `[Gecko_Enabled]` replaced.
#[derive(Clone)]
struct GeneratedDolphinInstall {
    staging_root: PathBuf,
    provider: GeckoProviderFetchResult,
    destination: PathBuf,
    staged: StagedDolphinIni,
}

/// The GameHacking.org GameCube counterpart to `GeneratedDolphinInstall`:
/// the staged, surgically edited GameSettings file for a selection of
/// externally sourced `ActionReplay`/`Gecko` cheats, rather than the
/// bundled Gecko catalogue.
#[derive(Clone)]
struct GeneratedGameCubeGameHackingInstall {
    staging_root: PathBuf,
    staged: StagedGameCubeIni,
    profile: DolphinProfile,
}

/// The BSFree Archive GameCube equivalent of
/// `GeneratedGameCubeGameHackingInstall`, additionally carrying the two-pass
/// duplicate/conflict analysis the BSFree provider computed before staging, so
/// the review/result UI can list already-installed, skipped, conflict, and
/// unsupported cheats honestly.
struct GeneratedBsFreeGameCubeInstall {
    staging_root: PathBuf,
    staged: StagedGameCubeIni,
    profile: DolphinProfile,
    findings: Vec<BsFreeDedupFinding>,
    skipped_duplicates: Vec<String>,
    skipped_unselectable: Vec<String>,
}

/// The BSFree Wii equivalent of [`GeneratedBsFreeGameCubeInstall`]: the staged
/// Dolphin GameSettings INI (produced by the shared Wii adapter) plus the
/// dedup/conflict findings. The staged artifact type is the same, because both
/// platforms write the same Dolphin `GameSettings` structure.
#[derive(Clone)]
struct GeneratedBsFreeWiiInstall {
    staging_root: PathBuf,
    staged: StagedGameCubeIni,
    profile: DolphinProfile,
    findings: Vec<BsFreeWiiDedupFinding>,
    skipped_duplicates: Vec<String>,
    skipped_unselectable: Vec<String>,
}

/// The Xenia equivalent of `GeneratedDolphinInstall`: the exact chosen
/// candidate document, staged as a real merged `.patch.toml`.
#[derive(Clone)]
struct GeneratedXeniaInstall {
    staging_root: PathBuf,
    candidate: XeniaCandidate,
    destination: PathBuf,
    staged: StagedXeniaPatchFile,
}

struct Pcsx2GameHackingState {
    status: GameHackingMatchStatus,
    detail: String,
    game: Option<GameHackingGame>,
    match_candidates: Vec<GameHackingMatchCandidate>,
    candidates: Vec<Pcsx2CheatCandidate>,
    selection: Pcsx2CheatSelection,
    cached_fallback: bool,
}

/// GameCube-only GameHacking.org coverage: matched title, named cheats,
/// and - unlike the initial preview-only milestone - a selection of
/// exactly which `ActionReplay`/`Gecko` cheats to install into the real
/// Dolphin GameSettings file. `RawUnknown`/`Unsupported` cheats can never
/// be selected (see `GameCubeCheatSelection::from_cheats`).
struct GameCubeGameHackingState {
    status: GameHackingGameCubeMatchStatus,
    detail: String,
    game: Option<GameHackingGameCubeGame>,
    match_candidates: Vec<GameHackingGameCubeMatchCandidate>,
    cheats: Vec<GameHackingGameCubeCheat>,
    selection: GameCubeCheatSelection,
    cached_fallback: bool,
}

fn gamecube_gamehacking_selection_for(
    cheats: &[GameHackingGameCubeCheat],
) -> GameCubeCheatSelection {
    GameCubeCheatSelection::from_cheats(cheats, &parse_dolphin_ini(""))
}

/// BSFree GameCube coverage inside Cheats & Mods: the matched BSFree game,
/// its classified cheats, and the user's explicit per-cheat selection. Only
/// the installable formats (`GeckoEquivalent`, `ActionReplayNative`) can be
/// selected; everything else stays browseable but unselectable. Identity is
/// the selected archive's verified Dolphin Game ID; the BSFree game itself is
/// matched by platform + title and always requires review before Apply.
struct BsFreeGameCubeGuiState {
    status: BsFreeGameCubeSearchStatus,
    detail: String,
    candidates: Vec<BsFreeGameCubeMatch>,
    game: Option<BsFreeGameCubeMatch>,
    cheats: Vec<BsFreeGameCubeCheat>,
    selection: BsFreeGameCubeCheatSelection,
    /// Destination-based duplicate/conflict analysis computed once per fetch
    /// against the real Dolphin GameSettings file, so the list can show
    /// "Already installed"/"Conflict" honestly. Refreshed on every re-search.
    analysis: Vec<BsFreeDedupFinding>,
    /// Editable search title, pre-filled with the archive's title. A different
    /// search re-runs the bounded local BSFree query.
    search_title: String,
}

/// BSFree Wii coverage inside Cheats & Mods, mirroring the GameCube state.
/// Only the verified hex-pair subset is selectable; every other BSFree Wii
/// record (encrypted, unverified device, malformed) stays browse-only.
struct BsFreeWiiGuiState {
    status: BsFreeWiiSearchStatus,
    detail: String,
    candidates: Vec<BsFreeWiiMatch>,
    game: Option<BsFreeWiiMatch>,
    cheats: Vec<BsFreeWiiCheat>,
    selection: BsFreeWiiCheatSelection,
    /// Destination-based duplicate/conflict analysis, computed once per fetch
    /// against the real Dolphin GameSettings file.
    analysis: Vec<BsFreeWiiDedupFinding>,
    search_title: String,
}

fn dolphin_game_from_wii_game(game: GameHackingWiiGame) -> GameHackingGameCubeGame {
    GameHackingGameCubeGame {
        game_id: game.game_id,
        title: game.title,
        system: game.system,
        region: game.region,
        dolphin_game_id: game.dolphin_game_id,
        revision: game.revision,
        hash: game.crc32,
        source_url: game.source_url,
    }
}

fn wii_game_from_dolphin_game(game: &GameHackingGameCubeGame) -> GameHackingWiiGame {
    GameHackingWiiGame {
        game_id: game.game_id,
        title: game.title.clone(),
        system: "Wii".to_string(),
        region: game.region.clone(),
        dolphin_game_id: game.dolphin_game_id.clone(),
        revision: game.revision,
        disc_number: None,
        crc32: game.hash.clone(),
        source_url: game.source_url.clone(),
    }
}

fn dolphin_candidate_from_wii(
    candidate: GameHackingWiiMatchCandidate,
) -> GameHackingGameCubeMatchCandidate {
    let strength = match candidate.strength {
        GameHackingWiiMatchStrength::ExactGameIdAndRevision => {
            GameHackingGameCubeMatchStrength::ExactGameIdAndRevision
        }
        GameHackingWiiMatchStrength::ExactGameIdAndRegion => {
            GameHackingGameCubeMatchStrength::ExactGameIdAndRegion
        }
        GameHackingWiiMatchStrength::ExactGameId
        | GameHackingWiiMatchStrength::ExactGameIdRevisionUnverified => {
            GameHackingGameCubeMatchStrength::ExactGameId
        }
    };
    GameHackingGameCubeMatchCandidate {
        game: dolphin_game_from_wii_game(candidate.game),
        strength,
        requires_user_confirmation: candidate.requires_user_confirmation,
    }
}

fn dolphin_cheat_from_wii(cheat: GameHackingWiiCheat) -> GameHackingGameCubeCheat {
    let code_format = if !cheat.safety.installable() {
        GameCubeCodeFormat::Unsupported
    } else {
        match cheat.code_format {
            WiiCodeFormat::ActionReplay => GameCubeCodeFormat::ActionReplay,
            WiiCodeFormat::Gecko => GameCubeCodeFormat::Gecko,
            WiiCodeFormat::RawUnknown => GameCubeCodeFormat::RawUnknown,
            WiiCodeFormat::Unsupported => GameCubeCodeFormat::Unsupported,
        }
    };
    let mut notes = cheat.description.into_iter().collect::<Vec<_>>();
    if !cheat.safety.installable() {
        notes.push(format!("Preview only: {}.", cheat.safety.reason()));
    }
    notes.extend(cheat.safety_warnings);
    GameHackingGameCubeCheat {
        id: cheat.id,
        name: cheat.name,
        author: cheat.author,
        description: (!notes.is_empty()).then(|| notes.join(" ")),
        code_format,
        code_lines: cheat.code_lines,
        source_game_id: cheat.source_game_id,
        source_url: cheat.source_url,
    }
}

fn wii_match_state(
    matched: GameHackingWiiMatch,
    cheats: Vec<GameHackingWiiCheat>,
    cached_fallback: bool,
) -> GameCubeGameHackingState {
    let status = match matched.status {
        GameHackingWiiMatchStatus::Matched => GameHackingGameCubeMatchStatus::Matched,
        GameHackingWiiMatchStatus::Candidates => GameHackingGameCubeMatchStatus::Candidates,
        GameHackingWiiMatchStatus::NoMatch => GameHackingGameCubeMatchStatus::NoMatch,
        GameHackingWiiMatchStatus::IdentityIncomplete => {
            GameHackingGameCubeMatchStatus::IdentityIncomplete
        }
    };
    let cheats = cheats
        .into_iter()
        .map(dolphin_cheat_from_wii)
        .collect::<Vec<_>>();
    GameCubeGameHackingState {
        status,
        detail: matched.detail,
        game: matched.game.map(dolphin_game_from_wii_game),
        match_candidates: matched
            .candidates
            .into_iter()
            .map(dolphin_candidate_from_wii)
            .collect(),
        selection: gamecube_gamehacking_selection_for(&cheats),
        cheats,
        cached_fallback,
    }
}

#[derive(Clone)]
struct GeneratedPcsx2Install {
    staging_root: PathBuf,
    /// Present only when a legacy CRC-only file was found with
    /// EmuWiz-managed cheats that needed consolidating into the
    /// serial+CRC file this PCSX2 build actually reads. Applied as its own
    /// chained operation, with its own journal and independent Undo (via
    /// the generic History & Logs rollback flow), immediately after the
    /// primary install succeeds - PCSX2's shared preview pipeline treats
    /// two verified-exact entries for one identity in the same report as
    /// an unresolvable ambiguity, so this can never be folded into the
    /// primary plan.
    legacy_migration_report: Option<SharedPreviewReport>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GameIdentityRequest {
    archive_path: PathBuf,
    platform: Option<String>,
    adapter: CheatEmulatorAdapter,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct CheatPreviewRequestKey {
    archive_path: PathBuf,
    platform: Option<String>,
    adapter: CheatEmulatorAdapter,
    profile_id: Option<String>,
    source_mode: CheatSourceMode,
    source_id: Option<String>,
    snapshot_id: Option<String>,
}

#[derive(Debug)]
enum CheatPreviewOutcome {
    Ready(SharedPreviewReport),
    Failed(CheatPreviewFailure),
}

#[derive(Debug)]
enum CheatPreviewFailure {
    Shared(SharedPreviewError),
    Materialization(RetroArchMaterializationError),
    /// Generating, staging, or previewing a selected-cheat install failed.
    InstallPlan(CheatInstallPlanError),
    /// Generating, staging, or previewing a Dolphin Gecko install failed.
    DolphinInstallPlan(DolphinInstallPlanError),
    /// Generating, staging, or previewing a Xenia patch install failed.
    XeniaInstallPlan(XeniaInstallPlanError),
    /// Generating, staging, or previewing a PCSX2 PNACH install failed.
    Pcsx2InstallPlan(Pcsx2InstallPlanError),
    /// Generating, staging, or previewing a GameHacking.org GameCube
    /// cheat install or removal failed.
    GameCubeGameHackingInstallPlan(GameCubeInstallPlanError),
    /// Generating, staging, or previewing a BSFree Archive GameCube cheat
    /// install failed.
    BsFreeGameCubeInstallPlan(BsFreeGameCubeError),
}

impl std::fmt::Display for CheatPreviewFailure {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Shared(error) => error.fmt(formatter),
            Self::Materialization(error) => error.fmt(formatter),
            Self::InstallPlan(error) => error.fmt(formatter),
            Self::DolphinInstallPlan(error) => error.fmt(formatter),
            Self::XeniaInstallPlan(error) => error.fmt(formatter),
            Self::Pcsx2InstallPlan(error) => error.fmt(formatter),
            Self::GameCubeGameHackingInstallPlan(error) => error.fmt(formatter),
            Self::BsFreeGameCubeInstallPlan(error) => error.fmt(formatter),
        }
    }
}

struct CheatPreviewResponse {
    key: CheatPreviewRequestKey,
    outcome: CheatPreviewOutcome,
    materialized: Option<RetroArchMaterializedPreview>,
    /// Present only for the generated-file install path: the staged bytes
    /// and the destination they were previewed against.
    generated: Option<GeneratedCheatInstall>,
    /// Present only for the Dolphin Gecko install path.
    dolphin_generated: Option<GeneratedDolphinInstall>,
    /// Present only for the Xenia patch install path.
    xenia_generated: Option<GeneratedXeniaInstall>,
    /// Present only for the GameHacking.org PCSX2 install path.
    pcsx2_generated: Option<GeneratedPcsx2Install>,
    /// Present only for the GameHacking.org GameCube install/removal path.
    gamecube_gamehacking_generated: Option<GeneratedGameCubeGameHackingInstall>,
    /// Present only for the BSFree Archive GameCube install path. A staged
    /// Dolphin GameSettings INI plus the provider's dedup/conflict findings;
    /// kept distinct so the two sources never cross-talk in the shared
    /// review/apply/result UI.
    bsfree_gamecube_generated: Option<GeneratedBsFreeGameCubeInstall>,
    /// Present only for the BSFree Archive Wii install path - the same shape
    /// as the GameCube one, routed through the shared Wii/Dolphin adapter.
    bsfree_wii_generated: Option<GeneratedBsFreeWiiInstall>,
}

enum CheatPreviewWork {
    Shared(SharedPreviewRequest),
    RetroArch(RetroArchMaterializationRequest),
}

enum CheatTransactionState {
    Idle,
    Review {
        key: CheatPreviewRequestKey,
        plan: SharedTransactionPlan,
        replacement_approved: bool,
    },
    Applying {
        key: CheatPreviewRequestKey,
        receiver: Receiver<Result<SharedApplyResult, String>>,
    },
    Result {
        key: CheatPreviewRequestKey,
        result: SharedApplyResult,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CheatEmulatorAdapter {
    RetroArch,
    Pcsx2,
    Dolphin,
    Xenia,
    Unsupported,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CheatSourceMode {
    ExistingRetroArchLibrary,
    ArchiveFsTrustedCatalogue,
}

impl CheatSourceMode {
    fn label(self) -> &'static str {
        match self {
            Self::ExistingRetroArchLibrary => "Existing RetroArch library",
            Self::ArchiveFsTrustedCatalogue => "EmuWiz cached catalogue",
        }
    }
}

fn cheat_archive_change_requires_confirmation(
    workflow: Option<&CheatWorkflowState>,
    candidate: &Path,
) -> bool {
    workflow.is_some_and(|workflow| {
        workflow.archive_path != candidate
            && !matches!(workflow.source_fetch, CheatStepResource::NotLoaded)
    })
}

/// Drops every candidate-derived stage. Called whenever the archive,
/// profile, adapter, source mode, or catalogue snapshot changes, so a
/// candidate, cheat selection, or preview from one context can never be
/// shown - or applied - against another.
fn clear_cheat_candidate_state(workflow: &mut CheatWorkflowState) {
    workflow.candidates = CheatStepResource::NotLoaded;
    workflow.candidates_request = None;
    workflow.candidate_query.clear();
    workflow.candidate_selection = None;
    workflow.candidate_load_error = None;
    workflow.preview_request = None;
    workflow.preview = CheatStepResource::NotLoaded;
    workflow.transaction = CheatTransactionState::Idle;
}

#[derive(Default)]
struct CheatArchivePickerState {
    search: String,
    platform_filter: Option<String>,
    source_filter: Option<PathBuf>,
    candidate: Option<PathBuf>,
}

impl CheatArchivePickerState {
    fn for_current(current: Option<&Path>, platform_filter: Option<String>) -> Self {
        Self {
            candidate: current.map(Path::to_path_buf),
            platform_filter,
            ..Self::default()
        }
    }
}

enum CheatArchivePickerAction {
    Cancel,
    Select(PathBuf),
}

fn cheat_picker_row_matches(
    row: &ArchiveRow,
    search: &str,
    platform_filter: Option<&str>,
    source_filter: Option<&Path>,
) -> bool {
    if row.origin != RowOrigin::Live {
        return false;
    }
    let normalized = search.trim().to_lowercase();
    let source_matches =
        source_filter.is_none_or(|wanted| row.source_path.as_deref() == Some(wanted));
    let platform_matches = platform_filter.is_none_or(|wanted| row.platform == wanted);
    let text_matches = normalized.is_empty()
        || row.matches(&normalized)
        || row.source_path.as_ref().is_some_and(|source| {
            source
                .to_string_lossy()
                .to_lowercase()
                .contains(&normalized)
        });
    source_matches && platform_matches && text_matches
}

fn cheat_picker_visible_indices(
    rows: &[ArchiveRow],
    picker: &CheatArchivePickerState,
) -> Vec<usize> {
    let mut indices: Vec<usize> = rows
        .iter()
        .enumerate()
        .filter(|(_, row)| {
            cheat_picker_row_matches(
                row,
                &picker.search,
                picker.platform_filter.as_deref(),
                picker.source_filter.as_deref(),
            )
        })
        .map(|(index, _)| index)
        .collect();
    indices.sort_by(|left, right| rows[*left].path.cmp(&rows[*right].path));
    indices
}

fn move_cheat_picker_candidate(
    rows: &[ArchiveRow],
    visible: &[usize],
    current: Option<&Path>,
    direction: ArrowDirection,
) -> Option<PathBuf> {
    if visible.is_empty() {
        return None;
    }
    let current_position = current.and_then(|current| {
        visible
            .iter()
            .position(|index| rows[*index].path == current)
    });
    let position = match (current_position, direction) {
        (Some(position), ArrowDirection::Down) => (position + 1).min(visible.len() - 1),
        (Some(position), ArrowDirection::Up) => position.saturating_sub(1),
        (None, ArrowDirection::Down) => 0,
        (None, ArrowDirection::Up) => visible.len() - 1,
    };
    Some(rows[visible[position]].path.clone())
}

fn show_cheat_archive_picker(
    context: &egui::Context,
    picker: &mut CheatArchivePickerState,
    rows: &[ArchiveRow],
    shared_platform: &mut Option<String>,
    clipboard: &mut dyn ClipboardBackend,
) -> Option<CheatArchivePickerAction> {
    let default_size = cheat_archive_picker_size(context.input(|input| input.screen_rect().size()));
    let mut action = None;
    let mut open = true;
    egui::Window::new("Choose an archive for Cheats & Mods")
        .id(egui::Id::new("cheats_mods_archive_picker"))
        .open(&mut open)
        .collapsible(false)
        .resizable(true)
        .default_size(default_size)
        .min_size(egui::vec2(520.0, 420.0))
        .anchor(egui::Align2::CENTER_CENTER, egui::Vec2::ZERO)
        .show(context, |ui| {
            ui.label("This changes only the Cheats & Mods context. It does not mount, queue, fetch, or modify the archive.");
            let search_has_focus = ui
                .add(
                egui::TextEdit::singleline(&mut picker.search)
                    .hint_text("Search name, platform, source, mount state, or path")
                    .desired_width(f32::INFINITY),
                )
                .has_focus();

            let mut platforms: Vec<String> = rows
                .iter()
                .filter(|row| row.origin == RowOrigin::Live)
                .map(|row| row.platform.clone())
                .collect();
            platforms.sort();
            platforms.dedup();
            let mut sources: Vec<PathBuf> = rows
                .iter()
                .filter(|row| row.origin == RowOrigin::Live)
                .filter_map(|row| row.source_path.clone())
                .collect();
            sources.sort();
            sources.dedup();
            ui.horizontal_wrapped(|ui| {
                egui::ComboBox::from_id_salt("cheat_picker_platform")
                    .selected_text(picker.platform_filter.as_deref().unwrap_or("All platforms"))
                    .show_ui(ui, |ui| {
                        ui.selectable_value(&mut picker.platform_filter, None, "All platforms");
                        for platform in &platforms {
                            ui.selectable_value(
                                &mut picker.platform_filter,
                                Some(platform.clone()),
                                platform,
                            );
                        }
                    });
                egui::ComboBox::from_id_salt("cheat_picker_source")
                    .selected_text(
                        picker
                            .source_filter
                            .as_ref()
                            .map(|path| path.display().to_string())
                            .unwrap_or_else(|| "All sources".to_string()),
                    )
                    .show_ui(ui, |ui| {
                        ui.selectable_value(&mut picker.source_filter, None, "All sources");
                        for source in &sources {
                            ui.selectable_value(
                                &mut picker.source_filter,
                                Some(source.clone()),
                                source.display().to_string(),
                            );
                        }
                    });
            });
            *shared_platform = picker.platform_filter.clone();

            let visible = cheat_picker_visible_indices(rows, picker);
            if !search_has_focus && ui.input(|input| input.key_pressed(egui::Key::ArrowDown)) {
                picker.candidate = move_cheat_picker_candidate(
                    rows,
                    &visible,
                    picker.candidate.as_deref(),
                    ArrowDirection::Down,
                );
            }
            if !search_has_focus && ui.input(|input| input.key_pressed(egui::Key::ArrowUp)) {
                picker.candidate = move_cheat_picker_candidate(
                    rows,
                    &visible,
                    picker.candidate.as_deref(),
                    ArrowDirection::Up,
                );
            }

            ui.separator();
            ui.label(format!("{} matching archives", visible.len()));
            egui::ScrollArea::vertical()
                .id_salt("cheat_archive_picker_rows")
                .max_height((ui.available_height() * 0.52).max(160.0))
                .auto_shrink([false, false])
                .show(ui, |ui| {
                    for index in &visible {
                        let row = &rows[*index];
                        let title = row
                            .path
                            .file_name()
                            .map(|name| name.to_string_lossy())
                            .unwrap_or_else(|| row.path.as_os_str().to_string_lossy());
                        let selected = picker.candidate.as_deref() == Some(row.path.as_path());
                        let response = ui
                            .add(
                                egui::Button::selectable(
                                selected,
                                format!("{title}  ·  {}  ·  {}", row.platform, row.state),
                                )
                                .truncate(),
                            )
                            .on_hover_text(row.path.display().to_string());
                        if response.clicked() {
                            picker.candidate = Some(row.path.clone());
                        }
                        response.context_menu(|ui| {
                            if ui.button("Copy archive path").clicked() {
                                let _ = clipboard.set_text(row.path.display().to_string());
                                ui.close();
                            }
                        });
                    }
                });

            if let Some(candidate) = picker.candidate.as_ref()
                && let Some(row) = rows.iter().find(|row| row.path == *candidate)
            {
                widgets::card(ui, |ui| {
                    ui.strong("Selected archive preview");
                    ui.horizontal_wrapped(|ui| {
                        widgets::status_badge(ui, &row.platform, widgets::StatusTone::Info);
                        widgets::status_badge(ui, &row.state, widgets::StatusTone::Pending);
                    });
                    if widgets::path_value(ui, "Archive", &row.path) {
                        let _ = clipboard.set_text(row.path.display().to_string());
                    }
                    if let Some(source) = &row.source_path
                        && widgets::path_value(ui, "Source", source)
                    {
                        let _ = clipboard.set_text(source.display().to_string());
                    }
                    match row.path.extension().and_then(|value| value.to_str()) {
                        Some(extension) if extension.eq_ignore_ascii_case("rvz") => {
                            ui.label("Identity: RVZ is visible from platform evidence; exact Game ID extraction is not available yet.");
                        }
                        Some(extension)
                            if ["iso", "gcm", "gcz", "wbfs", "ciso"]
                                .iter()
                                .any(|candidate| extension.eq_ignore_ascii_case(candidate)) =>
                        {
                            ui.label("Identity: exact disc identity is checked after selection; the item stays visible if inspection is unavailable.");
                        }
                        _ if row.unknown_platform => {
                            ui.label("Unknown because no header identity, source assignment, folder alias, or filename evidence matched.");
                        }
                        _ => {}
                    }
                });
            }
            ui.separator();
            ui.horizontal(|ui| {
                if ui.button("Cancel").clicked() {
                    action = Some(CheatArchivePickerAction::Cancel);
                }
                let choose = ui.add_enabled(
                    picker.candidate.as_ref().is_some_and(|candidate| {
                        rows.iter().any(|row| {
                            row.origin == RowOrigin::Live && row.path == *candidate
                        })
                    }),
                    egui::Button::new("Use selected archive"),
                );
                if choose.clicked()
                    || (!search_has_focus
                        && choose.enabled()
                        && ui.input(|input| input.key_pressed(egui::Key::Enter)))
                {
                    action = picker
                        .candidate
                        .clone()
                        .map(CheatArchivePickerAction::Select);
                }
            });
        });
    if !open && action.is_none() {
        action = Some(CheatArchivePickerAction::Cancel);
    }
    if action.is_none() && context.input(|input| input.key_pressed(egui::Key::Escape)) {
        action = Some(CheatArchivePickerAction::Cancel);
    }
    action
}

fn cheat_archive_picker_size(screen: egui::Vec2) -> egui::Vec2 {
    egui::vec2(
        (screen.x * 0.82).clamp(620.0, 1080.0),
        (screen.y * 0.82).clamp(480.0, 760.0),
    )
}

/// A background-loaded cheat-workflow resource. Stale-result protection
/// is ownership, the app's existing pattern: starting a new load
/// replaces this state wholesale, dropping the previous receiver, so a
/// superseded worker's `send` fails and its result can never apply.
/// Closing the workflow - or the selected archive changing - drops the
/// whole `CheatWorkflowState` the same way.
enum CheatStepResource<T> {
    NotLoaded,
    Loading {
        receiver: Receiver<Result<T, String>>,
    },
    Ready(T),
    Failed(String),
}

enum SharedHistoryState {
    NotLoaded,
    Loading {
        receiver: Receiver<Result<SharedHistoryReport, String>>,
    },
    Ready(SharedHistoryReport),
    Failed(String),
}

enum SharedRollbackState {
    Idle,
    Previewing {
        receiver: Receiver<Result<(SharedRollbackPreview, PathBuf, PathBuf), String>>,
    },
    Review {
        preview: SharedRollbackPreview,
        history_root: PathBuf,
        backup_root: PathBuf,
    },
    Applying {
        receiver: Receiver<Result<SharedRollbackResult, String>>,
    },
    Result(SharedRollbackResult),
    Failed(String),
}

enum HistoryPageAction {
    PreviewRollback {
        journal_path: PathBuf,
        destination_root: PathBuf,
    },
    ConfirmRollback,
    CancelRollback,
    Refresh,
}

/// Display label for a cached trusted-source snapshot's freshness.
fn cheat_freshness_label(freshness: CheatSourceFreshness) -> &'static str {
    match freshness {
        CheatSourceFreshness::Fresh => "Fresh",
        CheatSourceFreshness::Stale => "Stale",
        CheatSourceFreshness::Missing => "Not cached",
        CheatSourceFreshness::Unknown => "Unknown",
    }
}

fn cheat_freshness_tone(freshness: CheatSourceFreshness) -> widgets::StatusTone {
    match freshness {
        CheatSourceFreshness::Fresh => widgets::StatusTone::Success,
        CheatSourceFreshness::Stale => widgets::StatusTone::Warning,
        CheatSourceFreshness::Missing | CheatSourceFreshness::Unknown => {
            widgets::StatusTone::Pending
        }
    }
}

/// Display label for how a catalogue retrieval was satisfied.
fn cheat_fetch_status_label(status: CheatSourceFetchStatus) -> &'static str {
    match status {
        CheatSourceFetchStatus::Fetched => "Downloaded fresh catalogue",
        CheatSourceFetchStatus::CacheReused => "Reused cached snapshot",
        CheatSourceFetchStatus::OfflineReused => "Offline: reused cached snapshot",
    }
}

/// Builds the destination-bound code selection for a ready Dolphin
/// provider result - shared by the background-fetch completion handler and
/// `try_resolve_dolphin_provider_from_local_sources`, so both paths land
/// on exactly the same selection/error behavior regardless of whether the
/// result came from a network fetch or a purely local lookup.
fn build_dolphin_provider_selection(
    dolphin_profile_paths: &HashMap<String, PathBuf>,
    selected_dolphin_profile_id: Option<&str>,
    fetch: &GeckoProviderFetchResult,
) -> (Option<DolphinProviderSelectionState>, Option<String>) {
    let selection = selected_dolphin_profile_id
        .and_then(|profile_id| dolphin_profile_paths.get(profile_id))
        .map(|configuration_path| {
            load_dolphin_destination(configuration_path, &fetch.result.game_id)
        });
    match selection {
        Some(Ok(destination)) => {
            let codes = DolphinProviderCodeSelection::from_provider(&fetch.result, &destination);
            (
                Some(DolphinProviderSelectionState {
                    destination,
                    selection: codes,
                }),
                None,
            )
        }
        Some(Err(error)) => (None, Some(error.to_string())),
        None => (
            None,
            Some("Choose an eligible Dolphin profile before selecting provider codes.".to_string()),
        ),
    }
}

/// A short, non-technical name for a recognised disc image format, used
/// only in the beginner-facing "exact Game ID unavailable" message. Full
/// transport/parse diagnostics remain under Details, never here.
fn dolphin_identity_format_label(format: IdentityImageFormat) -> &'static str {
    match format {
        IdentityImageFormat::Iso => "This GameCube/Wii image",
        IdentityImageFormat::ZipContainingIso => "This ZIP archive",
        IdentityImageFormat::Rvz => "This RVZ file",
        IdentityImageFormat::Ciso => "This CISO file",
        IdentityImageFormat::Wbfs => "This WBFS file",
        IdentityImageFormat::Chd => "This disc image format",
        IdentityImageFormat::Deferred => "This disc image format",
        IdentityImageFormat::Gdi
        | IdentityImageFormat::Cdi
        | IdentityImageFormat::LooseCartridgeRom
        | IdentityImageFormat::Xex
        | IdentityImageFormat::ZipContainingXex
        | IdentityImageFormat::Xbe
        | IdentityImageFormat::ZipContainingXbe
        | IdentityImageFormat::XboxDiscImage
        | IdentityImageFormat::Pkg
        | IdentityImageFormat::ScummVmDirectory
        | IdentityImageFormat::Pbp
        | IdentityImageFormat::Unsupported => "This file",
    }
}

/// The beginner-facing detail line for `BeginnerCheatStatus::IdentityUnavailable` -
/// derived entirely from the same `GameIdentityReport` Details already
/// shows, so the two views can never disagree. Never fabricates identity
/// from the filename and never suggests mounting will definitely help.
fn dolphin_identity_unavailable_detail(report: &GameIdentityReport) -> String {
    let format_label = dolphin_identity_format_label(report.format);
    let status = report
        .evidence
        .iter()
        .find(|item| item.kind == IdentityKind::DolphinGameId)
        .map(|item| item.status);
    match status {
        Some(IdentityStatus::Invalid) => format!(
            "{format_label} is recognised as a GameCube/Wii image, but its disc header could not be verified. The file may be malformed or use an unrecognised layout."
        ),
        Some(IdentityStatus::Deferred) => format!(
            "{format_label} is recognised as a GameCube/Wii image, but EmuWiz cannot yet read an exact Game ID from it without decompressing the full image. Cheats cannot be matched safely without one."
        ),
        Some(IdentityStatus::Missing) => {
            format!("{format_label} is recognised, but the disc-header block is not present in it.")
        }
        Some(IdentityStatus::Unsupported) | None => format!(
            "{format_label} is recognised as a GameCube/Wii game, but exact identity extraction is not supported for it yet."
        ),
        Some(_) => "Exact Game ID is not yet available for this file.".to_string(),
    }
}

/// The Details "Game ID" row's three-way state - distinct from
/// `BeginnerCheatStatus::IdentityUnavailable` only in that it does not
/// require `dolphin_profile_selection` to be resolved first, matching what
/// the row itself actually depends on.
enum DolphinIdentityRowState<'a> {
    Verified(&'a str),
    Pending,
    Unavailable,
}

fn dolphin_identity_row_state(workflow: &CheatWorkflowState) -> DolphinIdentityRowState<'_> {
    match ready_game_identity(workflow) {
        Some(report) => match report.verified_dolphin_game_id() {
            Some(id) => DolphinIdentityRowState::Verified(id),
            None => DolphinIdentityRowState::Unavailable,
        },
        None => DolphinIdentityRowState::Pending,
    }
}

fn dolphin_provider_fetch_status_label(status: GeckoProviderFetchStatus) -> &'static str {
    match status {
        GeckoProviderFetchStatus::Downloaded => "downloaded",
        GeckoProviderFetchStatus::FreshCache => "fresh cache",
        GeckoProviderFetchStatus::RateLimitedCache => "rate-limited cache",
        GeckoProviderFetchStatus::StaleCacheFallback => "stale cache fallback",
        GeckoProviderFetchStatus::Catalogue => "local Dolphin cheat catalogue",
        GeckoProviderFetchStatus::NotAvailable => "no upstream file for this game",
    }
}

/// The beginner page's plain-English status - one of the exact statuses
/// the milestone specifies. Every adapter maps its own technical state
/// into this same small vocabulary so a first-time user never has to
/// learn provider/profile/identity terminology just to tell whether
/// EmuWiz found anything yet.
#[derive(Debug, Clone, PartialEq, Eq)]
enum BeginnerCheatStatus {
    FindingCompatibleCheats,
    CheatsFound {
        compatible_count: usize,
    },
    NoCompatibleCheatsFound,
    /// Dolphin's upstream GameSettings dataset has no file at all for this
    /// exact game ID (an exact-lookup HTTP 404). Distinct from
    /// `NoCompatibleCheatsFound` (a file exists, but nothing in it is safe
    /// to offer): here there is nothing to offer because upstream simply
    /// never published anything for this game - a normal outcome, not an
    /// error, so it renders with neutral/info styling rather than the
    /// warning/blocked tones used elsewhere in this enum.
    NoUpstreamCheatsAvailable,
    EmulatorSetupNeeded,
    /// Multiple valid profiles were found; the profile chooser (rendered
    /// separately) is asking the user to pick one.
    ChooseEmulatorProfile,
    CouldNotCheckForCheats {
        detail: String,
    },
    UsingSavedResultsWhileOffline,
    /// Identity inspection reached a final result, but it never produced a
    /// `Verified` exact game ID (malformed image, or a recognised format
    /// EmuWiz cannot yet decode without extracting the full image) -
    /// a terminal state, never re-attempted automatically, so the page
    /// never spins on "Finding compatible cheats" forever.
    IdentityUnavailable {
        detail: String,
    },
}

impl BeginnerCheatStatus {
    fn label(&self) -> String {
        match self {
            Self::FindingCompatibleCheats => "Finding compatible cheats".to_string(),
            Self::CheatsFound { compatible_count } => {
                let noun = if *compatible_count == 1 {
                    "compatible enhancement"
                } else {
                    "compatible enhancements"
                };
                format!("{compatible_count} {noun} found")
            }
            Self::NoCompatibleCheatsFound => "No compatible cheats found".to_string(),
            Self::NoUpstreamCheatsAvailable => {
                "No upstream Dolphin cheats are available for this game.".to_string()
            }
            Self::EmulatorSetupNeeded => "Emulator setup needed".to_string(),
            Self::ChooseEmulatorProfile => "Choose an emulator profile".to_string(),
            Self::CouldNotCheckForCheats { .. } => "Could not check for cheats".to_string(),
            Self::UsingSavedResultsWhileOffline => "Using saved results while offline".to_string(),
            Self::IdentityUnavailable { .. } => "Exact Game ID unavailable".to_string(),
        }
    }

    fn tone(&self) -> widgets::StatusTone {
        match self {
            Self::FindingCompatibleCheats
            | Self::EmulatorSetupNeeded
            | Self::ChooseEmulatorProfile => widgets::StatusTone::Pending,
            Self::CheatsFound { .. } => widgets::StatusTone::Success,
            Self::NoCompatibleCheatsFound | Self::UsingSavedResultsWhileOffline => {
                widgets::StatusTone::Warning
            }
            Self::NoUpstreamCheatsAvailable => widgets::StatusTone::Info,
            Self::CouldNotCheckForCheats { .. } | Self::IdentityUnavailable { .. } => {
                widgets::StatusTone::Blocked
            }
        }
    }
}

/// Computes the beginner status for Dolphin from the same state the
/// technical Details view already reads - no separate tracking, so the
/// two views can never disagree about what actually happened.
fn dolphin_beginner_status(workflow: &CheatWorkflowState) -> BeginnerCheatStatus {
    match &workflow.dolphin_profile_selection {
        None | Some(EmulatorProfileSelection::SetupNeeded) => {
            return BeginnerCheatStatus::EmulatorSetupNeeded;
        }
        Some(EmulatorProfileSelection::NeedsChoice { .. }) => {
            return BeginnerCheatStatus::ChooseEmulatorProfile;
        }
        Some(EmulatorProfileSelection::Auto { .. }) => {}
    }
    if workflow.platform.as_deref() == Some("Wii") {
        return wii_gamehacking_beginner_status(workflow);
    }
    // Identity has reached a final result but never produced a `Verified`
    // exact game ID (malformed image, or a recognised format EmuWiz
    // cannot yet decode - see `dolphin_identity_unavailable_detail`).
    // `start_dolphin_provider_fetch`/`try_resolve_dolphin_provider_from_local_sources`
    // both require a verified game ID before doing anything, so without
    // this check `dolphin_provider` would stay `NotLoaded` forever and the
    // page would show "Finding compatible cheats" indefinitely instead of
    // this honest terminal state.
    if let Some(report) = ready_game_identity(workflow)
        && report.verified_dolphin_game_id().is_none()
    {
        return BeginnerCheatStatus::IdentityUnavailable {
            detail: dolphin_identity_unavailable_detail(report),
        };
    }
    match &workflow.dolphin_provider {
        CheatStepResource::NotLoaded => match workflow.dolphin_local_lookup {
            DolphinLocalLookupState::NotAttempted => BeginnerCheatStatus::FindingCompatibleCheats,
            // The local catalogue/cache lookup already ran and found
            // nothing; the Dolphin catalogue card explains why and offers
            // the fix, so this stays the same honest "nothing found"
            // wording rather than a spinner that would never resolve.
            _ => BeginnerCheatStatus::NoCompatibleCheatsFound,
        },
        CheatStepResource::Loading { .. } => BeginnerCheatStatus::FindingCompatibleCheats,
        CheatStepResource::Failed(message) => BeginnerCheatStatus::CouldNotCheckForCheats {
            detail: message.clone(),
        },
        CheatStepResource::Ready(fetch) => {
            if fetch.status == GeckoProviderFetchStatus::NotAvailable {
                return BeginnerCheatStatus::NoUpstreamCheatsAvailable;
            }
            if fetch.status == GeckoProviderFetchStatus::StaleCacheFallback {
                return BeginnerCheatStatus::UsingSavedResultsWhileOffline;
            }
            let compatible_count = workflow
                .dolphin_provider_selection
                .as_ref()
                .map(|state| state.selection.selectable_count())
                .unwrap_or(0);
            if compatible_count == 0 {
                BeginnerCheatStatus::NoCompatibleCheatsFound
            } else {
                BeginnerCheatStatus::CheatsFound { compatible_count }
            }
        }
    }
}

fn wii_gamehacking_beginner_status(workflow: &CheatWorkflowState) -> BeginnerCheatStatus {
    match &workflow.gamecube_gamehacking {
        CheatStepResource::NotLoaded | CheatStepResource::Loading { .. } => {
            BeginnerCheatStatus::FindingCompatibleCheats
        }
        CheatStepResource::Failed(message) => BeginnerCheatStatus::CouldNotCheckForCheats {
            detail: message.clone(),
        },
        CheatStepResource::Ready(state) if state.cached_fallback => {
            BeginnerCheatStatus::UsingSavedResultsWhileOffline
        }
        CheatStepResource::Ready(state) => {
            let compatible_count = state
                .selection
                .entries
                .iter()
                .filter(|entry| entry.selectable)
                .count();
            if compatible_count == 0 {
                BeginnerCheatStatus::NoCompatibleCheatsFound
            } else {
                BeginnerCheatStatus::CheatsFound { compatible_count }
            }
        }
    }
}

/// Xenia's counterpart to `dolphin_beginner_status`.
fn xenia_beginner_status(workflow: &CheatWorkflowState) -> BeginnerCheatStatus {
    match &workflow.xenia_profile_selection {
        None | Some(EmulatorProfileSelection::SetupNeeded) => {
            return BeginnerCheatStatus::EmulatorSetupNeeded;
        }
        Some(EmulatorProfileSelection::NeedsChoice { .. }) => {
            return BeginnerCheatStatus::ChooseEmulatorProfile;
        }
        Some(EmulatorProfileSelection::Auto { .. }) => {}
    }
    match &workflow.xenia_provider {
        CheatStepResource::NotLoaded | CheatStepResource::Loading { .. } => {
            BeginnerCheatStatus::FindingCompatibleCheats
        }
        CheatStepResource::Failed(message) => BeginnerCheatStatus::CouldNotCheckForCheats {
            detail: message.clone(),
        },
        CheatStepResource::Ready(fetch) => {
            if fetch.status == XeniaProviderFetchStatus::StaleCacheFallback {
                return BeginnerCheatStatus::UsingSavedResultsWhileOffline;
            }
            let compatible_count = workflow
                .xenia_selection
                .as_ref()
                .filter(|state| {
                    state.selection.compatibility != XeniaCandidateCompatibility::Incompatible
                })
                .map(|state| state.selection.selectable_count())
                .unwrap_or(0);
            if compatible_count == 0 {
                BeginnerCheatStatus::NoCompatibleCheatsFound
            } else {
                BeginnerCheatStatus::CheatsFound { compatible_count }
            }
        }
    }
}

fn summarise_cheat_warnings(warnings: &[String]) -> Vec<String> {
    warnings
        .iter()
        .map(|warning| {
            let count = warning.split_whitespace().next().unwrap_or("Some");
            if warning.contains("retained but are non-actionable because parsing was incomplete") {
                format!(
                    "{count} catalogue files could not be parsed and were excluded from matching."
                )
            } else if warning.contains("unsupported content or encoding") {
                format!("{count} files used unsupported content encoding and were excluded.")
            } else if warning.contains("paths used unsupported encoding") {
                format!("{count} paths used unsupported encoding and were excluded safely.")
            } else if warning == "cached snapshot is stale" {
                "The cached catalogue is stale; update it when a network connection is available."
                    .to_string()
            } else {
                warning.clone()
            }
        })
        .collect()
}

/// Renders catalogue-indexing warnings as a concise, bounded summary
/// instead of dumping every entry directly into the page - the Sources
/// page's original complaint was thousands of malformed/unsupported
/// cheat-file diagnostics rendered as one banner each, unbounded, right
/// in the normal workflow. Shows a compact "N catalogue issues found, the
/// catalogue still works" banner, with a bounded explanation
/// representative entries, with the complete list (plus a "Copy all"
/// action) always reachable behind `technical_details` - no diagnostic
/// data is discarded, only its default on-screen footprint is bounded.
fn show_cheat_warnings_summary(
    ui: &mut egui::Ui,
    warnings: &[String],
    id_salt: impl std::hash::Hash,
    clipboard: &mut dyn ClipboardBackend,
) {
    const SAMPLE_LIMIT: usize = 3;
    if warnings.is_empty() {
        return;
    }
    let summarised = summarise_cheat_warnings(warnings);
    widgets::banner(
        ui,
        &format!(
            "{} catalogue issue{} found",
            summarised.len(),
            if summarised.len() == 1 { "" } else { "s" }
        ),
        "The catalogue still works. These files were skipped.",
        widgets::StatusTone::Warning,
    );
    // The exact "First use of widget ID .../Second use of widget ID ..."
    // collision this fixes: without an `id_salt`, every "What happened?"
    // header in this file shares one identical, literal-text-derived ID -
    // any two calls to this function rendered in the same frame (e.g. two
    // catalogue sources' warning sections both visible at once) collided.
    // `id_salt` is already unique per call site (source ID, archive SHA,
    // resolved commit, ...); it was already passed to the *inner*
    // `technical_details` disclosure below, just never to this outer one.
    egui::CollapsingHeader::new("What happened?")
        .id_salt(&id_salt)
        .default_open(false)
        .show(ui, |ui| {
            for warning in summarised.iter().take(SAMPLE_LIMIT) {
                ui.label(format!("• {warning}"));
            }
            if summarised.len() > SAMPLE_LIMIT {
                ui.weak(format!(
                    "+ {} more - see Technical details below.",
                    summarised.len() - SAMPLE_LIMIT
                ));
            }
            widgets::technical_details(ui, id_salt, |ui| {
                if widgets::action_button(ui, "Copy all", widgets::ActionStyle::Quiet, true)
                    .clicked()
                {
                    let _ = clipboard.set_text(warnings.join("\n"));
                }
                for warning in warnings {
                    ui.label(format!("• {warning}"));
                }
            });
        });
}

/// What the cheat workflow panel asks `update` to do.
#[derive(Clone)]
enum CheatWorkflowAction {
    ChooseArchive,
    OpenLibrary,
    RescanProfiles,
    RescanPcsx2Profiles,
    InspectPcsx2Profile,
    FetchPcsx2GameHacking {
        force_refresh: bool,
    },
    ConfirmPcsx2GameHackingMatch {
        game_id: u64,
    },
    TogglePcsx2CheatSelected {
        id: String,
        selected: bool,
    },
    InstallSelectedPcsx2,
    RescanDolphinProfiles,
    InspectDolphinProfile,
    InspectExistingLibrary,
    RefreshSources,
    ManageCatalogue,
    UseCachedSnapshot,
    ReviewApply,
    ConfirmApply,
    CancelApply,
    OpenApplyHistory,
    /// Stage 4: build (or rebuild) the ranked candidate list.
    MatchCandidates,
    /// Stage 4: choose one candidate by its catalogue-relative path.
    SelectCandidate(String),
    /// Stage 5: go back to the candidate list without losing it.
    ClearCandidateChoice,
    /// Stage 6 toggles. `enabled` distinguishes "included in the installed
    /// file" from "active as soon as RetroArch loads it".
    ToggleCheatSelected {
        index: u32,
        selected: bool,
    },
    ToggleCheatEnabled {
        index: u32,
        enabled: bool,
    },
    SelectAllCheats,
    ClearAllCheats,
    /// Stage 7: generate the file and preview installing it.
    BuildInstallPreview,
    /// Stage 9: restore whatever the install replaced.
    RollbackInstall,
    /// Retrieve exact-ID Gecko definitions from the one configured external
    /// provider. Refresh bypasses only a fresh cache, subject to rate limiting.
    FetchDolphinProvider {
        force_refresh: bool,
    },
    /// Dolphin Stage 4 toggles.
    ToggleDolphinCodeSelected {
        index: usize,
        selected: bool,
    },
    SelectAllDolphinCodes,
    ClearAllDolphinCodes,
    /// Dolphin Stage 5: stage the edited file and preview installing it.
    BuildDolphinInstallPreview,
    RescanXeniaProfiles,
    /// Retrieve patches for the verified Title ID from the Xenia Canary
    /// game-patches upstream provider. Refresh bypasses only a fresh
    /// cache, subject to rate limiting.
    FetchXeniaProvider {
        force_refresh: bool,
    },
    /// Choose which returned candidate document to work with - Xenia's
    /// own dataset legitimately has multiple files per Title ID.
    SelectXeniaCandidate(usize),
    ClearXeniaCandidateChoice,
    /// The explicit expert override required before a partially verified
    /// (module-hash-unverified) candidate can ever be staged.
    AcknowledgeXeniaPartialVerification(bool),
    ToggleXeniaPatchSelected {
        index: usize,
        selected: bool,
    },
    SelectAllXeniaPatches,
    ClearAllXeniaPatches,
    BuildXeniaInstallPreview,
    /// The beginner profile chooser selects and remembers one candidate in
    /// the same click. Choosing a profile is not a destructive operation.
    ChooseDolphinProfile(String),
    ChooseXeniaProfile(String),
    /// One click: builds the install preview and moves straight to the
    /// review stage, so the beginner "Install selected" button never
    /// requires a separate technical Preview step first.
    InstallSelectedDolphin,
    InstallSelectedXenia,
    ToggleDolphinShowExactChanges(bool),
    ToggleXeniaShowExactChanges(bool),
    ToggleDolphinDetailsOpen(bool),
    ToggleXeniaDetailsOpen(bool),
    /// GameCube-only GameHacking.org coverage: matches against the cached
    /// catalogue and, once matched, downloads only that one game's cheats.
    FetchGameCubeGameHacking {
        force_refresh: bool,
    },
    ConfirmGameCubeGameHackingMatch {
        game_id: u64,
    },
    ToggleGameCubeGameHackingCheatSelected {
        index: usize,
        selected: bool,
    },
    InstallSelectedGameCubeGameHacking,
    RemoveSelectedGameCubeGameHacking,
    /// BSFree Archive GameCube coverage: search the optional local SQLite
    /// database for the selected archive's game (bounded, read-only).
    FetchBsFreeGameCube {
        search_title: String,
    },
    /// Confirm one of several BSFree GameCube search candidates and load its
    /// classified cheats.
    ConfirmBsFreeGameCubeMatch {
        upstream_uid: i64,
    },
    ToggleBsFreeGameCubeCheatSelected {
        index: usize,
        selected: bool,
    },
    SelectAllBsFreeGameCubeCheats,
    ClearAllBsFreeGameCubeCheats,
    InstallSelectedBsFreeGameCube,
    /// BSFree Archive Wii coverage: search the optional local SQLite database
    /// for the selected archive's Wii game (bounded, read-only).
    FetchBsFreeWii {
        search_title: String,
    },
    /// Confirm one of several BSFree Wii search candidates and load its
    /// classified cheats.
    ConfirmBsFreeWiiMatch {
        upstream_uid: i64,
    },
    ToggleBsFreeWiiCheatSelected {
        index: usize,
        selected: bool,
    },
    SelectAllBsFreeWiiCheats,
    ClearAllBsFreeWiiCheats,
    InstallSelectedBsFreeWii,
}

